// ── Company logo helpers ──────────────────────────────────────────────────
// Single source of truth: the default proposal template's logoUrl. Settings → Company
// keeps all three default templates (quote/proposal/invoice) in sync on upload, so any
// of them would do — proposal is the canonical read.
const FALLBACK_LOGO_PATH = '/treemarkables-logo.png';

async function getCompanyLogoUrl(businessId?: string | null): Promise<string> {
  try {
    // Scope to the document's tenant when known (public PDF/email paths are
    // session-less, so the unscoped lookup returns Treemarkables' logo for every
    // tenant). Falls back to the unscoped default when no businessId is supplied.
    const tpl = businessId
      ? await storage.getDefaultDocumentTemplateForBusiness(businessId, 'proposal')
      : await storage.getDefaultDocumentTemplate('proposal');
    return tpl?.logoUrl || FALLBACK_LOGO_PATH;
  } catch {
    return FALLBACK_LOGO_PATH;
  }
}

function resolveLogoFsPath(logoUrl: string): string {
  // URLs look like "/logos/logo-123.png" or "/treemarkables-logo.png" — both served from /client/public.
  const relative = logoUrl.startsWith('/') ? logoUrl.slice(1) : logoUrl;
  return path.join(__dirname, '..', 'client', 'public', relative);
}

async function getCompanyLogoFilePath(businessId?: string | null): Promise<string> {
  const url = await getCompanyLogoUrl(businessId);
  const resolved = resolveLogoFsPath(url);
  if (fs.existsSync(resolved)) return resolved;
  return path.join(__dirname, '..', 'client', 'public', 'treemarkables-logo.png');
}

// Load the company logo's bytes regardless of which backing store it lives in:
//   • /objects/photos/<uuid>.<ext> — uploaded since the GCS migration
//   • /logos/<filename>            — legacy local-disk uploads (may be wiped)
//   • /treemarkables-logo.png      — bundled fallback in client/public/
// Used for the email's inline CID attachment and the PDF generator's image
// embed, both of which need raw bytes (not a URL).
async function getCompanyLogoBytes(businessId?: string | null): Promise<{ buffer: Buffer; contentType: string; ext: string } | null> {
  const url = await getCompanyLogoUrl(businessId);
  try {
    if (url.startsWith('/objects/photos/')) {
      const svc = new PhotoStorageService();
      const data = await svc.downloadPhotoBuffer(url);
      if (data?.buffer) {
        const contentType = data.contentType || 'image/png';
        const ext = contentType === 'image/jpeg' ? '.jpg'
          : contentType === 'image/webp' ? '.webp'
          : contentType === 'image/svg+xml' ? '.svg'
          : '.png';
        return { buffer: data.buffer, contentType, ext };
      }
    } else {
      // Legacy /logos/<name> and bundled /treemarkables-logo.png both live on
      // the local filesystem under client/public/ (or, for legacy uploads,
      // uploads/logos/). Try both before falling back to the default.
      const candidates = [
        path.join(__dirname, '..', 'uploads', url.startsWith('/') ? url.slice(1) : url),
        path.join(__dirname, '..', 'client', 'public', url.startsWith('/') ? url.slice(1) : url),
      ];
      for (const candidate of candidates) {
        if (fs.existsSync(candidate)) {
          const buffer = fs.readFileSync(candidate);
          const lower = candidate.toLowerCase();
          const ext = path.extname(lower);
          const contentType = ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg'
            : ext === '.webp' ? 'image/webp'
            : ext === '.svg' ? 'image/svg+xml'
            : 'image/png';
          return { buffer, contentType, ext: ext || '.png' };
        }
      }
    }
  } catch (err) {
    console.warn('Could not load company logo from primary source, falling back to default:', err);
  }
  // Final fallback — bundled default
  const fallbackPath = path.join(__dirname, '..', 'client', 'public', 'treemarkables-logo.png');
  if (fs.existsSync(fallbackPath)) {
    return { buffer: fs.readFileSync(fallbackPath), contentType: 'image/png', ext: '.png' };
  }
  return null;
}

// Initialize OpenAI client for call transcription
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

// Shared supplier-invoice extraction: runs GPT-5 over an invoice image/PDF and
// (best-effort) stores the document in GCS. Used by both the manual upload route
// (/api/jobs/:jobId/supplier-invoices/extract) and the forward-to-inbox webhook
// (bills-<jobId>@…). A storage outage must never lose the AI read, so storage
// failures are swallowed and surfaced as storageError.
export async function extractSupplierInvoiceFile(
  buffer: Buffer,
  originalname: string,
  mimetype: string,
) {
  const isPdf = mimetype === 'application/pdf' || originalname.toLowerCase().endsWith('.pdf');
  const base64 = buffer.toString('base64');

  const extractionInstruction = `You are extracting data from a supplier / purchase invoice for a New Zealand trades business (electrician, plumber, or builder). This is a bill the tradie received from a supplier or subcontractor.

Return ONLY JSON with these keys:
{
  "supplierName": string,            // the company that issued the invoice
  "invoiceNumber": string|null,
  "invoiceDate": string|null,        // YYYY-MM-DD
  "dueDate": string|null,            // YYYY-MM-DD
  "subtotal": number|null,           // ex-GST total
  "gst": number|null,                // GST amount (NZ GST is 15%)
  "total": number|null,              // inc-GST grand total
  "currency": string,                // default "NZD"
  "costCategory": string,            // one of: materials, subcontractor, equipment, disposal, other — infer from supplier/items
  "lineItems": [
    { "description": string, "quantity": number|null, "unitCost": number|null, "totalCost": number }
  ]
}

Rules: use numbers (not strings) for amounts, null when a value is genuinely absent, amounts in NZD. unitCost is the per-unit ex-GST price when determinable, otherwise the line total. totalCost is the line total. Do NOT invent values you cannot see.`;

  // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
  const visionResponse = await openai.chat.completions.create({
    model: 'gpt-5',
    messages: [
      {
        role: 'user',
        content: [
          { type: 'text', text: extractionInstruction },
          isPdf
            ? ({ type: 'file', file: { filename: originalname || 'invoice.pdf', file_data: `data:application/pdf;base64,${base64}` } } as any)
            : ({ type: 'image_url', image_url: { url: `data:${mimetype};base64,${base64}` } } as any),
        ],
      },
    ],
    response_format: { type: 'json_object' },
    max_completion_tokens: 3000,
  });

  const raw = visionResponse.choices[0]?.message?.content || '{}';
  let extracted: any = {};
  try {
    extracted = JSON.parse(raw);
  } catch {
    extracted = {};
  }

  let documentUrl: string | null = null;
  let thumbnailUrl: string | null = null;
  let storageError: string | null = null;
  try {
    const photoStorage = new PhotoStorageService();
    if (isPdf) {
      const { url } = await photoStorage.uploadDocument(buffer, originalname, mimetype || 'application/pdf');
      documentUrl = url;
    } else {
      const { url, thumbnailUrl: thumb } = await photoStorage.uploadPhoto(buffer, originalname, mimetype);
      documentUrl = url;
      thumbnailUrl = thumb;
    }
  } catch (storageErr) {
    storageError = storageErr instanceof Error ? storageErr.message : 'Document storage failed';
    console.error('Supplier invoice document storage failed (continuing with extraction):', storageError);
  }

  return {
    extracted,
    raw,
    document: {
      url: documentUrl,
      thumbnailUrl,
      originalFilename: originalname,
      mimeType: mimetype,
      fileSize: buffer.length,
      isPdf,
    },
    storageError,
  };
}

// ========================================
// TWILIO WEBHOOK VALIDATION
// ========================================

// Validate Twilio webhook request signature
function validateTwilioSignature(req: Request): boolean {
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  if (!authToken) {
    // Fail CLOSED in production — an unset token must never mean "accept any
    // forged callback". Only allow the skip in non-production for local dev.
    if (process.env.NODE_ENV === 'production') {
      console.error('❌ TWILIO_AUTH_TOKEN not set in production - rejecting webhook');
      return false;
    }
    console.warn('⚠️ TWILIO_AUTH_TOKEN not set - skipping signature validation (dev only)');
    return true;
  }

  const signature = req.headers['x-twilio-signature'] as string;
  if (!signature) {
    console.error('❌ Missing X-Twilio-Signature header');
    return false;
  }

  // Construct the full URL (Twilio uses full URL for validation)
  const protocol = req.headers['x-forwarded-proto'] || req.protocol;
  const host = req.headers['x-forwarded-host'] || req.headers.host;
  const url = `${protocol}://${host}${req.originalUrl}`;

  // Validate signature
  const validator = twilio.validateRequest(
    authToken,
    signature,
    url,
    req.body
  );

  if (!validator) {
    console.error('❌ Invalid Twilio signature');
  }

  return validator;
}

// Verify Meta/Facebook's X-Hub-Signature-256 header: HMAC-SHA256 of the RAW
// request body keyed with the app secret. Fails closed when FACEBOOK_APP_SECRET
// is unset (Facebook inbound is otherwise dropped, so rejecting is correct).
function verifyFacebookSignature(req: Request): boolean {
  const appSecret = process.env.FACEBOOK_APP_SECRET;
  if (!appSecret) {
    console.warn('⚠️ FACEBOOK_APP_SECRET not set - rejecting Messenger webhook');
    return false;
  }
  const header = (req.headers['x-hub-signature-256'] || req.headers['x-hub-signature']) as string | undefined;
  if (!header || !header.startsWith('sha256=')) {
    console.error('❌ Missing/invalid X-Hub-Signature-256 header');
    return false;
  }
  const rawBody = (req as any).rawBody as Buffer | undefined;
  if (!rawBody) {
    console.error('❌ Raw body unavailable for Facebook signature check');
    return false;
  }
  const expected = 'sha256=' + createHmac('sha256', appSecret).update(rawBody).digest('hex');
  try {
    const a = Buffer.from(header);
    const b = Buffer.from(expected);
    return a.length === b.length && timingSafeEqual(a, b);
  } catch {
    return false;
  }
}

// ========================================
// BUSINESS HOURS NOTIFICATION HELPERS
// ========================================

// Check if current time is within business hours (7am-4pm Mon-Fri, NZ time)
function isWithinBusinessHours(): boolean {
  const now = new Date();
  const nzTime = new Date(now.toLocaleString('en-US', { timeZone: 'Pacific/Auckland' }));
  
  const day = nzTime.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
  const hour = nzTime.getHours();
  
  // Check if it's Monday-Friday (1-5) and between 7am-4pm
  return day >= 1 && day <= 5 && hour >= 7 && hour < 16;
}

// Queue or send schedule notification based on business hours
async function queueScheduleNotification(employee: any, job: any, assignment: any): Promise<void> {
  const now = new Date();
  
  // Check if we're within business hours
  if (isWithinBusinessHours()) {
    // Send immediately
    await sendScheduleNotification(employee, job, assignment);
  } else {
    // Calculate next business day 7am
    const nextSendTime = getNextBusinessHourTime();
    
    // Log that notification is queued
    console.log(`[Notification Queue] Schedule notification for ${employee.firstName} ${employee.lastName} queued until ${nextSendTime.toISOString()}`);
    
    // Format notification message - Convert UTC timestamps to NZ timezone
    const startTimeUTC = new Date(assignment.startTime);
    const endTimeUTC = new Date(assignment.endTime);
    
    // Use formatNZTime utility for proper timezone conversion
    const startTimeFull = formatNZTime(startTimeUTC, 'full');
    const endTime = formatNZTime(endTimeUTC, 'time');
    
    // Format date and time separately for SMS (cleaner format)
    const startDate = formatNZTime(startTimeUTC, 'date');
    const startTime = formatNZTime(startTimeUTC, 'time');

    const emailHtml = `
      <h2>You've been scheduled for a job</h2>
      <p>Hi ${employee.firstName},</p>
      <p>You've been assigned to the following job:</p>
      <ul>
        <li><strong>Job:</strong> ${job?.title || 'Job'}</li>
        <li><strong>Location:</strong> ${job?.address || 'Address TBD'}</li>
        <li><strong>Date & Time:</strong> ${startTimeFull} - ${endTime}</li>
        ${assignment.role ? `<li><strong>Role:</strong> ${assignment.role}</li>` : ''}
        ${assignment.notes ? `<li><strong>Notes:</strong> ${assignment.notes}</li>` : ''}
      </ul>
      <p>Please confirm your availability as soon as possible.</p>
      <p>Thanks,<br>Treemarkables Team</p>
    `;

    const smsMessage = `${employee.firstName}: You're scheduled for ${job?.title || 'a job'} on ${startDate} at ${startTime} at ${job?.address || 'TBD'}.`;
    
    // Check for existing pending notifications for this employee and assignment
    const allPending = await storage.getPendingNotifications(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)); // Check next 7 days
    const existingNotification = allPending.find(n => 
      n.recipientId === employee.id && 
      n.assignmentId === assignment.id && 
      n.status === 'pending'
    );
    
    // If a pending notification exists, cancel it (we'll create a new one with updated details)
    if (existingNotification) {
      console.log(`[Notification Queue] Found existing notification for ${employee.firstName} ${employee.lastName} - cancelling old one`);
      await storage.markNotificationFailed(existingNotification.id, 'Rescheduled - replaced by new notification');
    }
    
    // Store in notification queue
    await storage.createNotificationQueueItem({
      recipientId: employee.id,
      recipientEmail: employee.email,
      recipientPhone: employee.phone,
      notificationType: employee.email && employee.phone ? 'both' : employee.email ? 'email' : 'sms',
      subject: `Job Scheduled: ${job?.title || 'Job'}`,
      message: employee.email ? emailHtml : smsMessage,
      metadata: {
        jobId: job?.id,
        assignmentId: assignment.id,
        startTime: assignment.startTime,
        endTime: assignment.endTime,
        smsMessage: employee.phone ? smsMessage : undefined
      },
      sendAt: nextSendTime,
      status: 'pending',
      jobId: job?.id,
      assignmentId: assignment.id
    });

    console.log(`[Notification Queue] Notification stored in queue for ${employee.firstName} ${employee.lastName}`);
  }
}

// Get next business hour time (next weekday at 7am NZ time, returned as UTC)
function getNextBusinessHourTime(): Date {
  // Get current time in NZ timezone
  const nowUTC = new Date();
  const nowNZ = toZonedTime(nowUTC, 'Pacific/Auckland');
  
  // Set to 7 AM NZ time
  let nextTimeNZ = new Date(nowNZ);
  nextTimeNZ.setHours(7, 0, 0, 0);
  
  // If it's already past 7am today, move to tomorrow
  if (nowNZ.getHours() >= 7) {
    nextTimeNZ.setDate(nextTimeNZ.getDate() + 1);
  }
  
  // Skip weekends
  while (nextTimeNZ.getDay() === 0 || nextTimeNZ.getDay() === 6) {
    nextTimeNZ.setDate(nextTimeNZ.getDate() + 1);
  }
  
  // Convert back to UTC for storage
  return fromZonedTime(nextTimeNZ, 'Pacific/Auckland');
}

// Send schedule notification via email/SMS
async function sendScheduleNotification(employee: any, job: any, assignment: any): Promise<void> {
  try {
    // Convert UTC timestamps to NZ timezone
    console.log(`📅 [SMS DEBUG] Raw assignment.startTime from DB: ${assignment.startTime}`);
    const startTimeUTC = new Date(assignment.startTime);
    const endTimeUTC = new Date(assignment.endTime);
    
    console.log(`📅 [SMS DEBUG] Parsed startTimeUTC: ${startTimeUTC.toISOString()}`);
    
    // Use formatNZTime utility for proper timezone conversion
    const startTimeFull = formatNZTime(startTimeUTC, 'full');
    const endTime = formatNZTime(endTimeUTC, 'time');
    
    // Format date and time separately for SMS (cleaner format)
    const startDate = formatNZTime(startTimeUTC, 'date');
    const startTime = formatNZTime(startTimeUTC, 'time');
    
    console.log(`📅 [SMS DEBUG] Formatted for SMS: "${startDate} at ${startTime}"`);

    // Send email notification
    if (employee.email) {
      await emailService.sendEmail({
        to: employee.email,
        subject: `Job Scheduled: ${job?.title || 'Job'}`,
        html: `
          <h2>You've been scheduled for a job</h2>
          <p>Hi ${employee.firstName},</p>
          <p>You've been assigned to the following job:</p>
          <ul>
            <li><strong>Job:</strong> ${job?.title || 'Job'}</li>
            <li><strong>Location:</strong> ${job?.address || 'Address TBD'}</li>
            <li><strong>Date & Time:</strong> ${startTimeFull} - ${endTime}</li>
            ${assignment.role ? `<li><strong>Role:</strong> ${assignment.role}</li>` : ''}
            ${assignment.notes ? `<li><strong>Notes:</strong> ${assignment.notes}</li>` : ''}
          </ul>
          <p>Please confirm your availability as soon as possible.</p>
          <p>Thanks,<br>Treemarkables Team</p>
        `,
        text: `Hi ${employee.firstName},\n\nYou've been assigned to: ${job?.title || 'Job'}\nLocation: ${job?.address || 'Address TBD'}\nDate & Time: ${startTimeFull} - ${endTime}\n\nPlease confirm your availability.`
      });
    }

    // Send SMS notification if phone number exists
    if (employee.phone) {
      const smsMessage = `${employee.firstName}: You're scheduled for ${job?.title || 'a job'} on ${startDate} at ${startTime} at ${job?.address || 'TBD'}.`;
      await smsService.sendSMS({ to: employee.phone, message: smsMessage });
    }

    console.log(`[Notification] Schedule notification sent to ${employee.firstName} ${employee.lastName}`);
  } catch (error) {
    console.error('Error sending schedule notification:', error);
  }
}

