  // Google Calendar — per-user OAuth + two-way sync (unified calendar Phase C)
  // ─────────────────────────────────────────────────────────────────────────────

  // Status: returns connection info for the logged-in user.
  app.get('/api/google-calendar/status', async (req: Request, res: Response) => {
    try {
      const { getConnectionForUser: gcalGetConn } = await import('./services/googleCalendarSync');
      const conn = await gcalGetConn(req.session.businessId, req.session.employeeId ?? '');
      if (!conn) return res.json({ connected: false });
      return res.json({
        connected: true,
        calendarEmail: conn.googleEmail || 'Connected',
        calendarId: conn.calendarId,
        lastSynced: conn.lastSyncedAt,
        lastError: conn.lastError,
      });
    } catch (error) {
      console.error('Google Calendar status error:', error);
      return res.json({ connected: false, message: 'Error checking status' });
    }
  });

  // Auth start: redirect the user to Google's consent screen.
  app.get('/api/google-calendar/auth', (req: Request, res: Response) => {
    const clientId = process.env.GOOGLE_CALENDAR_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CALENDAR_CLIENT_SECRET;
    if (!clientId || !clientSecret) {
      return res.status(503).json({ success: false, message: 'Google Calendar OAuth not configured' });
    }
    const { google } = require('googleapis');
    const origin = process.env.NODE_ENV === 'production'
      ? 'https://app.treemarkables.co.nz'
      : `${req.protocol}://${req.get('host')}`;
    const redirectUri = `${origin}/api/google-calendar/callback`;
    const oauth2 = new google.auth.OAuth2(clientId, clientSecret, redirectUri);
    // State encodes the current session identifiers so the callback can associate
    // the connection with the right employee without trusting POST body.
    const state = Buffer.from(JSON.stringify({
      businessId: req.session.businessId,
      employeeId: req.session.employeeId,
    })).toString('base64');
    const url = oauth2.generateAuthUrl({
      access_type: 'offline',
      prompt: 'consent',
      scope: [
        'https://www.googleapis.com/auth/calendar.events',
        'https://www.googleapis.com/auth/calendar.readonly',
        'https://www.googleapis.com/auth/userinfo.email',
      ],
      state,
    });
    res.redirect(url);
  });

  // OAuth callback: exchange code, upsert connection, redirect to /integrations.
  app.get('/api/google-calendar/callback', async (req: Request, res: Response) => {
    const origin = process.env.NODE_ENV === 'production'
      ? 'https://app.treemarkables.co.nz'
      : `${req.protocol}://${req.get('host')}`;
    try {
      const code = typeof req.query.code === 'string' ? req.query.code : '';
      const stateRaw = typeof req.query.state === 'string' ? req.query.state : '';
      if (!code || !stateRaw) {
        return res.redirect(`${origin}/integrations?gcal_error=missing_code`);
      }
      let stateParsed: { businessId?: string; employeeId?: string } = {};
      try {
        stateParsed = JSON.parse(Buffer.from(stateRaw, 'base64').toString('utf8'));
      } catch {
        return res.redirect(`${origin}/integrations?gcal_error=bad_state`);
      }
      const { businessId, employeeId } = stateParsed;
      if (!businessId || !employeeId) {
        return res.redirect(`${origin}/integrations?gcal_error=bad_state`);
      }

      const clientId = process.env.GOOGLE_CALENDAR_CLIENT_ID!;
      const clientSecret = process.env.GOOGLE_CALENDAR_CLIENT_SECRET!;
      const redirectUri = `${origin}/api/google-calendar/callback`;
      const { google } = require('googleapis');
      const oauth2 = new google.auth.OAuth2(clientId, clientSecret, redirectUri);
      const { tokens } = await oauth2.getToken(code);
      oauth2.setCredentials(tokens);

      // Fetch the connected email address via userinfo
      let googleEmail: string | null = null;
      try {
        const oauth2Api = google.oauth2({ version: 'v2', auth: oauth2 });
        const { data } = await oauth2Api.userinfo.get();
        googleEmail = data.email ?? null;
      } catch { /* non-fatal */ }

      const { db } = await import('./db');
      const { googleCalendarConnections } = await import('@shared/schema');
      const { eq, and } = await import('drizzle-orm');

      // Upsert — one row per (business, user)
      const existing = await db
        .select()
        .from(googleCalendarConnections)
        .where(and(
          eq(googleCalendarConnections.businessId, businessId),
          eq(googleCalendarConnections.userId, employeeId),
        ));

      const connData = {
        businessId,
        userId: employeeId,
        googleEmail,
        accessToken: tokens.access_token ?? '',
        refreshToken: tokens.refresh_token ?? '',
        expiresAt: tokens.expiry_date ? new Date(tokens.expiry_date) : new Date(Date.now() + 50 * 60 * 1000),
        scope: tokens.scope ?? null,
        isActive: true,
        lastError: null,
        updatedAt: new Date(),
      };

      if (existing.length > 0) {
        await db
          .update(googleCalendarConnections)
          .set(connData)
          .where(eq(googleCalendarConnections.id, existing[0].id));
      } else {
        await db.insert(googleCalendarConnections).values(connData);
      }

      console.log(`✅ Google Calendar connected for employee ${employeeId} (${googleEmail})`);
      res.redirect(`${origin}/integrations?gcal_connected=true`);
    } catch (error) {
      console.error('Google Calendar OAuth callback error:', error);
      res.redirect(`${origin}/integrations?gcal_error=oauth_failed`);
    }
  });

  // Disconnect: revoke token + deactivate the connection row.
  app.delete('/api/google-calendar/connection', async (req: Request, res: Response) => {
    try {
      const { getConnectionForUser: gcalGetConn } = await import('./services/googleCalendarSync');
      const conn = await gcalGetConn(req.session.businessId, req.session.employeeId ?? '');
      if (!conn) return res.json({ success: true });

      // Best-effort token revocation (don't fail if it errors)
      try {
        const clientId = process.env.GOOGLE_CALENDAR_CLIENT_ID;
        const clientSecret = process.env.GOOGLE_CALENDAR_CLIENT_SECRET;
        if (clientId && clientSecret) {
          const { google } = require('googleapis');
          const auth = new google.auth.OAuth2(clientId, clientSecret);
          auth.setCredentials({ refresh_token: conn.refreshToken });
          await auth.revokeCredentials();
        }
      } catch (revokeErr) {
        console.warn('Google token revoke failed (ignored):', revokeErr);
      }

      const { db } = await import('./db');
      const { googleCalendarConnections } = await import('@shared/schema');
      const { eq } = await import('drizzle-orm');
      await db
        .update(googleCalendarConnections)
        .set({ isActive: false, updatedAt: new Date() })
        .where(eq(googleCalendarConnections.id, conn.id));

      console.log(`✅ Google Calendar disconnected for employee ${req.session.employeeId}`);
      return res.json({ success: true });
    } catch (error) {
      console.error('Google Calendar disconnect error:', error);
      return res.status(500).json({ success: false, message: 'Error disconnecting Google Calendar' });
    }
  });

  // Busy events for the calendar UI: returns external Google events as UTC intervals
  // with the owning employee's userId so the calendar can render them in the right row.
  app.get('/api/google-calendar/busy', async (req: Request, res: Response) => {
    try {
      const startStr = typeof req.query.start === 'string' ? req.query.start : '';
      const endStr = typeof req.query.end === 'string' ? req.query.end : '';
      if (!startStr || !endStr) {
        return res.status(400).json({ success: false, message: 'start and end are required' });
      }
      const { db } = await import('./db');
      const { googleBusyEvents, googleCalendarConnections } = await import('@shared/schema');
      const { and, eq, gte, lte } = await import('drizzle-orm');
      const businessId = req.session.businessId;
      if (!businessId) return res.json({ success: true, data: [] });

      const rows = await db
        .select({
          id: googleBusyEvents.id,
          connectionId: googleBusyEvents.connectionId,
          googleEventId: googleBusyEvents.googleEventId,
          summary: googleBusyEvents.summary,
          startTime: googleBusyEvents.startTime,
          endTime: googleBusyEvents.endTime,
          status: googleBusyEvents.status,
          userId: googleCalendarConnections.userId,
        })
        .from(googleBusyEvents)
        .innerJoin(
          googleCalendarConnections,
          eq(googleBusyEvents.connectionId, googleCalendarConnections.id),
        )
        .where(
          and(
            eq(googleBusyEvents.businessId, businessId),
            lte(googleBusyEvents.startTime, new Date(endStr)),
            gte(googleBusyEvents.endTime, new Date(startStr)),
          ),
        );
      return res.json({ success: true, data: rows });
    } catch (error) {
      console.error('Google Calendar busy events error:', error);
      return res.status(500).json({ success: false, message: 'Error fetching busy events' });
    }
  });

  // List events from the operator's primary Google Calendar.
  // Used by the CalendarAvailabilityModal inside email/SMS composers so the
  // user can eyeball their own schedule while drafting a message to a customer.
  app.get('/api/google-calendar/events', async (req: Request, res: Response) => {
    const start = typeof req.query.start === 'string' ? req.query.start : '';
    const end = typeof req.query.end === 'string' ? req.query.end : '';
    const startDate = start ? new Date(start) : null;
    const endDate = end ? new Date(end) : null;

    if (!startDate || !endDate || Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime())) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'start and end must be ISO timestamps' });
    }
    if (endDate.getTime() <= startDate.getTime()) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'end must be after start' });
    }
    const MAX_RANGE_MS = 31 * 24 * 60 * 60 * 1000;
    if (endDate.getTime() - startDate.getTime() > MAX_RANGE_MS) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'range must be 31 days or less' });
    }

    try {
      const events = await googleCalendarService.listEvents(startDate.toISOString(), endDate.toISOString());
      return res.json({ success: true, data: events });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.toLowerCase().includes('not connected')) {
        return res.status(200).json({ success: false, error: 'not_connected' });
      }
      console.error('Google Calendar events fetch error:', error);
      return res.status(502).json({ success: false, error: 'upstream', message });
    }
  });

  // One-off cleanup: remove already-synced job events that should NOT be on the
  // owner's personal calendar (crew/work-order, completed, unsuccessful, mulch).
  // Job events are the ones syncJobToCalendar created — summary starts with the
  // tree icon and ends with " - #<jobNumber>". We keep quote-stage events
  // (lead/quote) and only delete events whose job is a *known* non-quote status;
  // anything we can't positively identify is reported, never deleted.
  // Defaults to a dry run — pass { apply: true } to actually delete.
  app.post('/api/google-calendar/cleanup-job-events', requireAdmin, async (req: Request, res: Response) => {
    const { start, end, apply } = req.body ?? {};
    const startDate = typeof start === 'string' ? new Date(start) : null;
    const endDate = typeof end === 'string' ? new Date(end) : null;
    if (!startDate || !endDate || Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime())) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'start and end must be ISO timestamps' });
    }
    if (endDate.getTime() <= startDate.getTime()) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'end must be after start' });
    }
    const MAX_RANGE_MS = 730 * 24 * 60 * 60 * 1000; // 2 years
    if (endDate.getTime() - startDate.getTime() > MAX_RANGE_MS) {
      return res.status(400).json({ success: false, error: 'invalid_range', message: 'range must be 2 years or less' });
    }

    try {
      const events = await googleCalendarService.listAllEvents(startDate.toISOString(), endDate.toISOString());
      const jobEvents = events.filter(e => e.summary.startsWith('🌳'));

      const toDelete: any[] = [];   // positively a non-quote job → safe to delete
      const skippedQuote: any[] = []; // lead/quote → keep
      const unresolved: any[] = [];   // no job number / job not found → never auto-delete

      for (const ev of jobEvents) {
        const match = ev.summary.match(/#(\S+)\s*$/);
        const jobNumber = match?.[1];
        if (!jobNumber) {
          unresolved.push({ id: ev.id, summary: ev.summary, start: ev.start, reason: 'no_job_number' });
          continue;
        }
        const job = await storage.getJobByJobNumber(jobNumber);
        if (!job) {
          unresolved.push({ id: ev.id, summary: ev.summary, start: ev.start, jobNumber, reason: 'job_not_found' });
          continue;
        }
        if (CALENDAR_SYNCABLE_JOB_STATUSES.has(job.status)) {
          skippedQuote.push({ id: ev.id, summary: ev.summary, start: ev.start, jobNumber, status: job.status });
        } else {
          toDelete.push({ id: ev.id, summary: ev.summary, start: ev.start, jobNumber, status: job.status });
        }
      }

      let deleted = 0;
      const deleteFailures: any[] = [];
      if (apply === true) {
        for (const c of toDelete) {
          const ok = await googleCalendarService.deleteEvent(c.id);
          if (ok) deleted++;
          else deleteFailures.push(c);
        }
      }

      return res.json({
        success: true,
        dryRun: apply !== true,
        range: { start: startDate.toISOString(), end: endDate.toISOString() },
        totals: {
          jobEventsScanned: jobEvents.length,
          toDelete: toDelete.length,
          keptQuoteStage: skippedQuote.length,
          unresolved: unresolved.length,
          deleted,
        },
        toDelete,
        keptQuoteStage: skippedQuote,
        unresolved,
        deleteFailures,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.toLowerCase().includes('not connected')) {
        return res.status(200).json({ success: false, error: 'not_connected' });
      }
      console.error('Google Calendar cleanup error:', error);
      return res.status(502).json({ success: false, error: 'upstream', message });
    }
  });

  // Google Places reviews endpoint (replaces Google Business Profile)
  // Cached for 6h — Places Details (Enterprise+Atmosphere) is ~$25/1000 calls,
  // and reviews change slowly. One bad April we paid $144 uncached.
  const googleReviewsCache: { data: any[] | null; fetchedAt: number; inflight: Promise<any[]> | null } = {
    data: null,
    fetchedAt: 0,
    inflight: null,
  };
  const GOOGLE_REVIEWS_TTL_MS = 6 * 60 * 60 * 1000;

  async function fetchGoogleReviewsFromApi(apiKey: string, placeId: string): Promise<any[]> {
    const v1Url = `https://places.googleapis.com/v1/places/${placeId}`;
    const v1Response = await fetch(v1Url, {
      headers: {
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': 'reviews.text,reviews.rating,reviews.authorAttribution.displayName,reviews.publishTime',
      },
    });

    if (!v1Response.ok) {
      throw new Error(`Places v1 returned ${v1Response.status}`);
    }

    const v1Data = await v1Response.json();
    if (!v1Data.reviews?.length) return [];

    return v1Data.reviews.map((review: any, index: number) => ({
      id: `google-v1-${index}`,
      name: review.authorAttribution?.displayName || 'Google User',
      location: 'Google Reviews',
      rating: review.rating || 5,
      comment: review.text?.text || '',
      service: 'Tree Services',
      source: 'google',
      date: review.publishTime,
    }));
  }

  app.get('/api/reviews/google', async (req: Request, res: Response) => {
    try {
      const apiKey = process.env.GOOGLE_PLACES_API_KEY || process.env.GOOGLE_MY_BUSINESS_API_KEY;
      const placeId = process.env.GOOGLE_PLACE_ID;

      if (!apiKey) {
        return res.status(200).json({
          success: true,
          reviews: [],
          message: 'Google Places API key not configured. Please set GOOGLE_PLACES_API_KEY.',
        });
      }

      if (!placeId) {
        return res.status(200).json({
          success: true,
          reviews: [],
          message: 'Google Place ID not configured. Use /api/reviews/google/discover to find your Place ID.',
        });
      }

      const now = Date.now();
      const cacheAge = now - googleReviewsCache.fetchedAt;
      const cacheFresh = googleReviewsCache.data !== null && cacheAge < GOOGLE_REVIEWS_TTL_MS;

      if (cacheFresh) {
        return res.json({
          success: true,
          reviews: googleReviewsCache.data,
          cached: true,
          ageMs: cacheAge,
        });
      }

      // Coalesce concurrent misses so a stampede of page loads is still one upstream call.
      if (!googleReviewsCache.inflight) {
        googleReviewsCache.inflight = fetchGoogleReviewsFromApi(apiKey, placeId)
          .then((reviews) => {
            googleReviewsCache.data = reviews;
            googleReviewsCache.fetchedAt = Date.now();
            return reviews;
          })
          .catch((err) => {
            console.error('Google Places reviews fetch failed:', err);
            // Serve stale on error if we have any, otherwise empty.
            return googleReviewsCache.data ?? [];
          })
          .finally(() => {
            googleReviewsCache.inflight = null;
          });
      }

      const reviews = await googleReviewsCache.inflight;
      res.json({
        success: true,
        reviews,
        cached: false,
        message: reviews.length > 0 ? `Retrieved ${reviews.length} Google reviews` : 'No reviews found',
      });
    } catch (error) {
      console.error('Google Places reviews error:', error);
      res.status(200).json({
        success: true,
        reviews: googleReviewsCache.data ?? [],
        message: 'Unable to fetch Google reviews at this time',
      });
    }
  });

  // Helper endpoint to discover Google Business Profile Account ID and Location ID
  app.get('/api/reviews/google/discover', async (req: Request, res: Response) => {
    try {
      const apiKey = process.env.GOOGLE_MY_BUSINESS_API_KEY;
      
      if (!apiKey) {
        return res.status(400).json({ 
          success: false, 
          message: 'Google My Business API key not configured' 
        });
      }

      const results: any = {
        success: false,
        attempts: [],
        recommendations: []
      };

      // Discover THIS business's own Google listing from its settings — not a
      // hardcoded Treemarkables query — so any tenant finds their own reviews.
      const __rdSettings = await storage.getBusinessSettings();
      const __rdName = __rdSettings?.businessName || '';
      const __rdLocality = (__rdSettings?.businessAddress || '').split(',').pop()?.trim() || '';
      const __rdQuery = [__rdName, __rdLocality, 'New Zealand'].filter(Boolean).join(' ');

      // Method 1: Try New Google Places API to find Treemarkables business
      try {
        // Try the new Places API (Text Search)
        const newPlacesUrl = `https://places.googleapis.com/v1/places:searchText`;
        
        const placesResponse = await fetch(newPlacesUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Goog-Api-Key': apiKey,
            'X-Goog-FieldMask': 'places.id,places.displayName,places.formattedAddress,places.rating,places.userRatingCount,places.reviews'
          },
          body: JSON.stringify({
            textQuery: __rdQuery,
            maxResultCount: 5
          })
        });

        const placesData = await placesResponse.json();
        
        results.attempts.push({
          method: 'New Google Places API Text Search',
          status: placesResponse.status,
          success: placesResponse.ok,
          data: placesData
        });

        if (placesData.places && placesData.places.length > 0) {
          const business = placesData.places[0];
          results.placesInfo = {
            placeId: business.id,
            name: business.displayName?.text || business.displayName,
            address: business.formattedAddress,
            rating: business.rating,
            userRatingsTotal: business.userRatingCount,
            reviews: business.reviews
          };
        }
      } catch (error) {
        results.attempts.push({
          method: 'New Google Places API',
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Method 1b: Try Legacy Google Places API as fallback
      try {
        const legacyPlacesUrl = `https://maps.googleapis.com/maps/api/place/textsearch/json?query=Treemarkables+Gisborne+tree+removal&key=${apiKey}`;
        
        const legacyResponse = await fetch(legacyPlacesUrl);
        const legacyData = await legacyResponse.json();
        
        results.attempts.push({
          method: 'Legacy Google Places Text Search',
          status: legacyResponse.status,
          success: legacyResponse.ok,
          data: legacyData
        });

        if (legacyData.results && legacyData.results.length > 0 && !results.placesInfo) {
          const business = legacyData.results[0];
          results.placesInfo = {
            placeId: business.place_id,
            name: business.name,
            address: business.formatted_address,
            rating: business.rating,
            userRatingsTotal: business.user_ratings_total
          };
          
          // Try to get detailed place info
          if (business.place_id) {
            const detailsUrl = `https://maps.googleapis.com/maps/api/place/details/json?place_id=${business.place_id}&fields=place_id,name,rating,reviews,formatted_address&key=${apiKey}`;
            const detailsResponse = await fetch(detailsUrl);
            const detailsData = await detailsResponse.json();
            
            results.attempts.push({
              method: 'Legacy Google Places Details',
              status: detailsResponse.status,
              success: detailsResponse.ok,
              data: detailsData
            });

            if (detailsData.result) {
              results.placeDetails = detailsData.result;
            }
          }
        }
      } catch (error) {
        results.attempts.push({
          method: 'Legacy Google Places API',
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Method 2: Try Google Business Profile API with different approaches
      try {
        // Try the newer API endpoint
        const newApiUrl = `https://mybusinessbusinessinformation.googleapis.com/v1/GoogleLocations:search?key=${apiKey}`;
        
        const newApiResponse = await fetch(newApiUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            location: {
              address: {
                locality: __rdLocality || 'New Zealand',
                countryCode: 'NZ'
              }
            },
            query: __rdName
          })
        });

        const newApiData = await newApiResponse.text();
        
        results.attempts.push({
          method: 'Google Business Profile Search',
          status: newApiResponse.status,
          success: newApiResponse.ok,
          data: newApiData
        });
      } catch (error) {
        results.attempts.push({
          method: 'Google Business Profile Search',
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Method 3: Try to find through My Business API without auth (will fail but gives us info)
      try {
        const accountsUrl = `https://mybusinessaccountmanagement.googleapis.com/v1/accounts?key=${apiKey}`;
        const accountsResponse = await fetch(accountsUrl);
        const accountsText = await accountsResponse.text();
        
        results.attempts.push({
          method: 'Direct Business Profile Accounts',
          status: accountsResponse.status,
          success: accountsResponse.ok,
          data: accountsText
        });
      } catch (error) {
        results.attempts.push({
          method: 'Direct Business Profile Accounts',
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Generate recommendations based on what we found
      if (results.placesInfo) {
        results.success = true;
        results.recommendations.push(
          `Found your business on Google Places with ID: ${results.placesInfo.placeId}`
        );
        results.recommendations.push(
          `Business name: ${results.placesInfo.name}`
        );
        results.recommendations.push(
          `Address: ${results.placesInfo.address}`
        );
        if (results.placesInfo.userRatingsTotal > 0) {
          results.recommendations.push(
            `You have ${results.placesInfo.userRatingsTotal} Google reviews with average rating ${results.placesInfo.rating}`
          );
        }
      }

      results.recommendations.push(
        'Google Business Profile API requires OAuth2 authentication, not API keys'
      );
      results.recommendations.push(
        'To get Account ID and Location ID, you need to either:'
      );
      results.recommendations.push(
        '1. Set up OAuth2 flow (complex)'
      );
      results.recommendations.push(
        '2. Find IDs manually from business.google.com dashboard'
      );
      results.recommendations.push(
        '3. Use Google Places API for reviews (simpler, using Place ID)'
      );

      res.json(results);

    } catch (error) {
      console.error('Google Business Profile discovery error:', error);
      res.status(500).json({ 
        success: false, 
        message: 'Error discovering Google Business Profile IDs',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });


  // Public captcha config — tells the marketing-site forms whether to render the
  // Cloudflare Turnstile widget. Enabled by setting BOTH TURNSTILE_SITE_KEY and
  // TURNSTILE_SECRET_KEY (via the DO dashboard); unset = widget hidden and no
  // server-side check, so the forms keep working with zero config.
  app.get('/api/captcha/config', (_req: Request, res: Response) => {
    const siteKey = process.env.TURNSTILE_SITE_KEY?.trim();
    const secretKey = process.env.TURNSTILE_SECRET_KEY?.trim();
    if (siteKey && secretKey) {
      res.json({ provider: 'turnstile', siteKey });
    } else {
      res.json({ provider: null });
    }
  });

  // Per-IP rate limit for the public contact form (in-memory, resets on deploy).
  const contactFormRateLimit = new Map<string, { count: number; resetTime: number }>();
  const CONTACT_FORM_MAX_PER_WINDOW = 5;
  const CONTACT_FORM_WINDOW_MS = 10 * 60 * 1000; // 10 minutes

  // Contact form submission endpoint
  app.post('/api/contact', async (req: Request, res: Response) => {
    try {
      const { name, email, phone, hearAbout, message, captchaToken, leadSource, website } = req.body;

      // Validate contact form data
      const contactValidation = contactFormSchema.safeParse({
        name, email, phone, hearAbout, message
      });

      if (!contactValidation.success) {
        return res.status(400).json({ 
          success: false, 
          message: 'Please provide valid contact information.' 
        });
      }

      // Validate lead source data if provided
      let validatedLeadSource: LeadSource | undefined = undefined;
      if (leadSource) {
        const leadSourceValidation = leadSourceSchema.safeParse(leadSource);
        if (leadSourceValidation.success) {
          validatedLeadSource = leadSourceValidation.data;
        } else {
          console.log('Invalid lead source data received:', leadSourceValidation.error);
        }
      }

      // Capture server-side data
      const clientIp = req.ip || req.connection.remoteAddress || 'unknown';
      const userAgent = req.get('User-Agent') || 'unknown';

      // Honeypot: hidden "website" field real users never see. Bots that fill it
      // get a fake success (so they don't learn to adapt) and nothing is created.
      if (typeof website === 'string' && website.trim() !== '') {
        console.log(`[contact-spam] Honeypot tripped by ${clientIp}`);
        return res.json({
          success: true,
          message: 'Thank you! We will contact you within 24 hours for your free quote.'
        });
      }

      // Per-IP rate limit — a real customer never needs more than a few
      // submissions; a spam blast from one IP gets cut off.
      const rlNow = Date.now();
      const rlEntry = contactFormRateLimit.get(clientIp);
      if (rlEntry && rlNow < rlEntry.resetTime) {
        if (rlEntry.count >= CONTACT_FORM_MAX_PER_WINDOW) {
          console.log(`[contact-spam] Rate limit hit by ${clientIp}`);
          return res.status(429).json({
            success: false,
            message: 'Too many requests. Please wait a few minutes and try again, or call us directly.'
          });
        }
        rlEntry.count++;
      } else {
        contactFormRateLimit.set(clientIp, { count: 1, resetTime: rlNow + CONTACT_FORM_WINDOW_MS });
      }
      if (contactFormRateLimit.size > 10000) contactFormRateLimit.clear(); // memory backstop

      // Cloudflare Turnstile — enforced only when BOTH keys are configured, matching
      // /api/captcha/config so the widget and the server check turn on together
      // (secret-only would 400 every submission while the widget stays hidden).
      const turnstileSecret = process.env.TURNSTILE_SECRET_KEY?.trim();
      const turnstileSiteKey = process.env.TURNSTILE_SITE_KEY?.trim();
      if (turnstileSecret && turnstileSiteKey) {
        if (!captchaToken) {
          return res.status(400).json({
            success: false,
            message: 'Please complete the security check.'
          });
        }
        try {
          const verifyResponse = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
              secret: turnstileSecret,
              response: String(captchaToken),
              remoteip: clientIp,
            }).toString(),
          });
          const verifyData = await verifyResponse.json();
          if (!verifyData.success) {
            console.log(`[contact-spam] Turnstile rejected ${clientIp}:`, verifyData['error-codes']);
            return res.status(400).json({
              success: false,
              message: 'Security check failed. Please try again.'
            });
          }
        } catch (verifyErr) {
          // A siteverify outage must not cost a genuine lead — allow and log loud.
          console.error('[contact-spam] Turnstile siteverify unreachable — allowing submission:', verifyErr);
        }
      }

      // CAPTCHA validation — opt-in. Set REQUIRE_CAPTCHA=1 to enable once
      // the frontend reCAPTCHA integration is wired up. Default is off.
      const requireCaptcha = process.env.REQUIRE_CAPTCHA === '1';

      if (requireCaptcha) {
        if (!captchaToken) {
          return res.status(400).json({ 
            success: false, 
            message: 'Please complete the CAPTCHA verification.' 
          });
        }

        // Verify CAPTCHA with Google
        const captchaVerifyUrl = `https://www.google.com/recaptcha/api/siteverify`;
        const captchaResponse = await fetch(captchaVerifyUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: `secret=${process.env.RECAPTCHA_SECRET_KEY}&response=${captchaToken}`
        });

        const captchaData = await captchaResponse.json();
        
        if (!captchaData.success) {
          console.log('CAPTCHA verification failed:', captchaData);
          return res.status(400).json({ 
            success: false, 
            message: 'CAPTCHA verification failed. Please try again.' 
          });
        }
        
        console.log('CAPTCHA verification successful for contact form submission');
      }

      // Email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ 
          success: false, 
          message: 'Please provide a valid email address.' 
        });
      }

      // Prepare lead submission data
      const leadSubmissionData: InsertLeadSubmission = {
        name: name.trim(),
        email: email.trim().toLowerCase(),
        phone: phone?.trim().replace(/-/g, ''),
        hearAbout,
        message: message.trim(),
        leadSource: validatedLeadSource,
        ip: clientIp,
        userAgent
      };

      // Conversation-first: the inquiry lands in the Inbox/Opportunities pages as an
      // open conversation only — NO auto-created job card or customer record. Too much
      // form spam was polluting the jobs pipeline, so the operator now triages in the
      // conversation view and clicks "Create Job from Lead" (ConversationDetail) to
      // convert a real inquiry; that flow find-or-creates the customer itself.
      const trimmedName = name.trim();
      const lowerEmail = email.trim().toLowerCase();
      const cleanPhone = (phone || '').trim().replace(/-/g, '').replace(/\s/g, '');
      const isMobileNumber = /^(\+?64)?0?2[0-9]/.test(cleanPhone);

      // Step 1: look up an existing customer so a repeat inquiry threads onto their
      // record. Try phone first (indexed), then fall back to email.
      // Resolve the owning business for this public, session-less submission so every
      // write below is tenant-stamped. Inbound contact forms run on the owner
      // (BYPASSRLS) connection with no tenant context; without this stamp the
      // customer/conversation/job/notification rows are written with a NULL
      // business_id and never surface in the owner's RLS-filtered Inbox. Resolving to
      // undefined (settings lookup failed) preserves the prior behaviour, so this is
      // safe by construction. (Group B public-write tenant fix.)
      let contactBusinessId: string | undefined;
      try {
        contactBusinessId = (await storage.getBusinessSettings())?.businessId ?? undefined;
        console.log(`[contact] tenant resolved for submission: businessId=${contactBusinessId ?? '(none)'}`);
      } catch (bizErr) {
        console.error('[contact] Failed to resolve business for tenant stamping:', bizErr);
      }

      // Hoisted above runWithBusiness so the auto-reply block can log its receipt
      // onto the conversation thread once the confirmation email/SMS is sent.
      let contactConversation: any = undefined;

      // Reuse an existing customer to de-duplicate, but ONLY when the submitted name
      // plausibly belongs to the matched record. The business's own advertised number
      // (and other shared/duplicate numbers carried over from imports) can sit on an
      // unrelated customer record; without this guard a brand-new enquiry gets silently
      // filed under that other person's name (observed 2026-06-25: a quote submitted as
      // "Jules" landed on customer "wendy johnson1820" because she held the advertised
      // cell). Repeat customers (same/overlapping name) still merge. Policy: name
      // mismatch → fresh lead.
      const namesLikelyMatch = (a?: string | null, b?: string | null): boolean => {
        const na = (a || '').toLowerCase().replace(/\s+/g, ' ').trim();
        const nb = (b || '').toLowerCase().replace(/\s+/g, ' ').trim();
        if (!na || !nb) return false;
        return na === nb || na.includes(nb) || nb.includes(na);
      };

      await runWithBusiness(contactBusinessId, async () => {
      let customer: any = undefined;
      try {
        let matched: any = undefined;
        if (cleanPhone) {
          matched = await storage.findCustomerByPhone(cleanPhone);
        }
        if (!matched && lowerEmail) {
          matched = await storage.findCustomerByEmail(lowerEmail);
        }
        if (matched && namesLikelyMatch(trimmedName, matched.name)) {
          customer = matched;
        } else if (matched) {
          console.log(`[contact] phone/email matched existing customer "${matched.name}" but submitted name "${trimmedName}" differs — creating a new lead instead of reusing it`);
        }
        // Conversation-first: do NOT create a customer record for unknown senders —
        // spam submissions were polluting the Clients list alongside the jobs
        // pipeline. A matched existing customer is still linked so repeat inquiries
        // thread onto their record; for new leads the "Create Job from Lead" convert
        // flow find-or-creates the customer (POST /api/customers dedupes by name).
      } catch (customerErr) {
        console.error('Error matching existing customer for contact form:', customerErr);
      }

      try {
        // Step 2: find an existing open conversation or create a new one,
        // attached to the customer record above.
        let conversation = await notificationHelper.findExistingOpenConversation(lowerEmail);
        let isNewConversation = !conversation;

        if (!conversation) {
          const conversationTitle = message.trim().length > 0
            ? message.trim().substring(0, 100) + (message.length > 100 ? '...' : '')
            : `New inquiry from ${trimmedName}`;

          conversation = await storage.createConversation({
            customerId: customer?.id,
            title: conversationTitle,
            status: 'open',
            priority: 'medium',
            source: 'web_form',
            tags: ['contact-form', 'website']
          });
          console.log(`✅ Created new conversation for contact form submission: ${conversation.id}`);
        } else {
          console.log(`✅ Found existing open conversation for ${email}, adding message to: ${conversation.id}`);
        }

        // Step 3: append the inbound message to the conversation thread.
        const fullMessage = `Contact Form Submission\n\nName: ${name}\nEmail: ${email}\nPhone: ${phone || 'Not provided'}\nHow they heard about us: ${hearAbout || 'Not specified'}\n\nMessage:\n${message.trim()}`;

        await storage.createConversationMessage({
          conversationId: conversation.id,
          type: 'message',
          content: fullMessage,
          direction: 'inbound',
          fromName: trimmedName,
          fromContact: lowerEmail,
          platform: 'web_form'
        });

        contactConversation = conversation;

        // Step 4: notify operators. Brand new conversation → new-inquiry
        // notification (deep-links to /conversation/:id where the operator can
        // triage and hit "Create Job from Lead"). Repeat submission on an open
        // conversation → follow-up notification so it reads as "they pinged us
        // again" rather than a duplicate inquiry. No job is auto-created here.
        if (isNewConversation) {
          await notificationHelper.createConversationNotification(conversation);
        } else {
          await notificationHelper.notifyConversationReply(
            { id: conversation.id, title: conversation.title, source: 'web_form', customerName: trimmedName },
            message.trim()
          );
        }

      } catch (error) {
        console.error('Error creating conversation from contact form:', error);
        // Continue even if conversation creation fails
      }

      // Send webhook notification to Zapier (non-blocking) - TEMPORARILY DISABLED
      // try {
      //   const zapierWebhookUrl = process.env.ZAPIER_WEBHOOK_URL;
      //   if (zapierWebhookUrl) {
      //     fetch(zapierWebhookUrl, {
      //       method: 'POST',
      //       headers: {
      //         'Content-Type': 'application/json',
      //       },
      //       body: JSON.stringify({
      //         name: contactValidation.data.name,
      //         email: contactValidation.data.email,
      //         phone: contactValidation.data.phone,
      //         hearAbout: contactValidation.data.hearAbout,
      //         message: contactValidation.data.message,
      //         leadSource: validatedLeadSource,
      //         source: 'treemarkables-contact-form',
      //         timestamp: new Date().toISOString(),
      //         ip: clientIp,
      //         userAgent
      //       })
      //     }).catch(error => {
      //       console.error('[webhook] Failed to send to Zapier:', error);
      //     });
      //     console.log('[webhook] Contact form data sent to Zapier');
      //   }
      // } catch (error) {
      //   console.error('[webhook] Error sending to Zapier:', error);
      // }

      // Email notifications disabled - conversations are created in Inbox instead
      // const emailSent = await sendContactEmail(
      //   contactValidation.data,
      //   validatedLeadSource
      // );

      // Customer auto-reply: send the configured "we received your inquiry"
      // confirmation. Non-blocking — log on failure so a downed email/SMS
      // provider never breaks the form submission.
      try {
        const bizSettings = await storage.getBusinessSettings();
        if (bizSettings?.inquiryAutoReplyEnabled) {
          const channel = (bizSettings.inquiryAutoReplyChannel || 'email') as 'email' | 'sms' | 'both';
          // Title-case the submitted name so a lowercase web-form entry ("jules
          // halley") greets as "Jules Halley". Handles spaces, hyphens, apostrophes.
          const titleCaseName = (s: string) =>
            (s || '').toLowerCase().replace(/(^|[\s'’-])([a-z])/g, (_m, sep, ch) => sep + ch.toUpperCase());
          const displayName = titleCaseName(trimmedName) || 'there';
          const firstName = displayName.split(/\s+/)[0] || displayName;
          const subject = bizSettings.inquiryAutoReplyEmailSubject || "We've received your inquiry — {businessName}";
          const emailTemplate = bizSettings.inquiryAutoReplyEmailMessage || '';
          const smsTemplate = bizSettings.inquiryAutoReplySmsMessage || '';

          const fillVars = (s: string) =>
            s
              .replace(/\{customerName\}/g, displayName)
              .replace(/\{firstName\}/g, firstName)
              .replace(/\{businessName\}/g, bizSettings.businessName || '')
              .replace(/\{businessPhone\}/g, bizSettings.businessPhone || '');

          if ((channel === 'email' || channel === 'both') && lowerEmail) {
            const emailBodyText = fillVars(emailTemplate);
            const emailSubject = fillVars(subject);

            // Signature: business name + phone + email + clickable website, pulled
            // from business settings so each tenant signs off with its own details
            // and a real hyperlink (the auto-reply previously had no signature).
            const escSig = (v: string) => (v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
            const sigName = bizSettings.businessName || 'Treemarkables';
            const sigPhone = (bizSettings.businessPhone || '').trim();
            const sigEmail = (bizSettings.businessEmail || '').trim();
            const sigWebsiteRaw = (bizSettings.businessWebsite || '').trim();
            const sigWebsiteHref = sigWebsiteRaw ? (/^https?:\/\//i.test(sigWebsiteRaw) ? sigWebsiteRaw : `https://${sigWebsiteRaw}`) : '';
            const sigWebsiteLabel = sigWebsiteRaw.replace(/^https?:\/\//i, '').replace(/\/$/, '');

            const sigTextLines = [
              '—',
              sigName,
              sigPhone ? `Phone: ${sigPhone}` : '',
              sigEmail ? `Email: ${sigEmail}` : '',
              sigWebsiteHref ? sigWebsiteLabel : '',
            ].filter(Boolean);
            const emailBodyTextWithSig = `${emailBodyText}\n\n${sigTextLines.join('\n')}`;

            const sigHtml = `<div style="margin-top:20px;padding-top:16px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#555;">
              <div style="font-weight:600;color:#111;">${escSig(sigName)}</div>
              ${sigPhone ? `<div>Phone: <a href="tel:${escSig(sigPhone.replace(/\s+/g, ''))}" style="color:#555;text-decoration:none;">${escSig(sigPhone)}</a></div>` : ''}
              ${sigEmail ? `<div>Email: <a href="mailto:${escSig(sigEmail)}" style="color:#1155cc;text-decoration:underline;">${escSig(sigEmail)}</a></div>` : ''}
              ${sigWebsiteHref ? `<div><a href="${escSig(sigWebsiteHref)}" style="color:#1155cc;text-decoration:underline;">${escSig(sigWebsiteLabel)}</a></div>` : ''}
            </div>`;

            const emailBodyHtml = `<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.5;color:#222;">${
              emailBodyText.split('\n').map(line => line ? line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : '').join('<br>')
            }${sigHtml}</div>`;
            emailService.sendEmail({
              to: lowerEmail,
              subject: emailSubject,
              text: emailBodyTextWithSig,
              html: emailBodyHtml,
            })
              .then(async () => {
                if (contactConversation?.id) {
                  try {
                    await storage.createConversationMessage({
                      conversationId: contactConversation.id,
                      type: 'email',
                      content: `Auto-reply email sent to ${lowerEmail}\n\nSubject: ${emailSubject}\n\n${emailBodyText}`,
                      direction: 'outbound',
                      fromName: 'System',
                      toContact: lowerEmail,
                      subject: emailSubject,
                      platform: 'email',
                      metadata: { autoReply: true },
                    });
                  } catch (receiptErr) {
                    console.error('[contact] Failed to record auto-reply email receipt:', receiptErr);
                  }
                }
              })
              .catch(err => console.error('[contact] auto-reply email failed:', err));
          }

          if ((channel === 'sms' || channel === 'both') && cleanPhone && isMobileNumber) {
            const smsBody = fillVars(smsTemplate);
            if (smsBody.trim()) {
              smsService.sendSMS({ to: cleanPhone, message: smsBody })
                .then(async () => {
                  if (contactConversation?.id) {
                    try {
                      await storage.createConversationMessage({
                        conversationId: contactConversation.id,
                        type: 'sms',
                        content: `Auto-reply SMS sent to ${cleanPhone}\n\n${smsBody}`,
                        direction: 'outbound',
                        fromName: 'System',
                        toContact: cleanPhone,
                        platform: 'sms',
                        metadata: { autoReply: true },
                      });
                    } catch (receiptErr) {
                      console.error('[contact] Failed to record auto-reply SMS receipt:', receiptErr);
                    }
                  }
                })
                .catch(err => console.error('[contact] auto-reply SMS failed:', err));
            }
          }
        }
      } catch (autoReplyErr) {
        console.error('[contact] Error sending inquiry auto-reply:', autoReplyErr);
      }
      }); // runWithBusiness(contactBusinessId) — tenant-stamp all contact-form writes

      res.json({
        success: true,
        message: 'Thank you! We will contact you within 24 hours for your free quote.'
      });

    } catch (error) {
      console.error('Contact form error:', error);
      res.status(500).json({ 
        success: false, 
        message: 'Sorry, there was an error processing your request. Please try again.' 
      });
    }
  });

