  // POST /api/leads - Create a job lead (converts conversation to job with 'lead' status)
  app.post('/api/leads', async (req: Request, res: Response) => {
    try {
      const { name, email, phone, address, serviceRequested, notes, status, conversationId } = req.body;
      
      // First, create or find the customer. Try phone (indexed) first, then
      // fall back to email so existing clients aren't duplicated when their
      // phone is missing or has changed.
      let customer;
      if (phone) {
        customer = await storage.findCustomerByPhone(phone);
      }
      if (!customer && email) {
        customer = await storage.findCustomerByEmail(email);
      }

      if (!customer) {
        const customerData = {
          name: name || 'Unknown',
          email: email ? email.toLowerCase() : '',
          phone: phone || '',
          address: address || '',
          contactPreference: 'email' as const,
          notes: notes || ''
        };
        customer = await storage.createCustomer(customerData);
      }
      
      // Detect if phone is a mobile number (NZ mobiles start with 02, +642, etc.)
      const cleanPhone = (phone || '').replace(/\s/g, '');
      const isMobileNumber = /^(\+?64)?0?2[0-9]/.test(cleanPhone);
      
      // Also save mobile to customer record if detected as mobile
      if (isMobileNumber && phone && customer.id) {
        try {
          await storage.updateCustomer(customer.id, { mobile: phone });
        } catch (e) {
          // Non-critical - continue even if mobile update fails
        }
      }
      
      // Create job with 'lead' status
      const jobNumber = await storage.getNextJobNumber();
      const jobData = {
        customerId: customer.id,
        jobNumber: jobNumber,
        title: `Lead from ${name || 'conversation'}`,
        description: serviceRequested || notes || '',
        address: address || 'Address not specified',
        status: status || 'lead',
        priority: 'medium' as const,
        leadSource: 'website' as const,
        totalAmount: '0.00',
        metricsEligible: true,
        metricsStartDate: new Date(),
        jobContactPhone: isMobileNumber ? '' : (phone || ''),
        jobContactMobile: isMobileNumber ? (phone || '') : '',
      };
      
      const job = await storage.createJob(jobData);

      // Mark the source conversation as converted if one was provided
      if (conversationId) {
        try {
          await storage.updateConversation(conversationId, {
            status: 'converted',
            conversionDate: new Date(),
          });
        } catch (e) {
          // Non-critical — continue even if the conversation update fails
        }
      }
      
      res.json({ 
        success: true, 
        data: job,
        message: 'Job lead created successfully'
      });
    } catch (error) {
      console.error('Error creating job lead:', error);
      res.status(500).json({ 
        success: false, 
        message: 'Error creating job lead' 
      });
    }
  });

  // POST /api/leads/extract-from-message - Extract lead details from pasted text message using AI
  app.post('/api/leads/extract-from-message', async (req: Request, res: Response) => {
    try {
      const { message, phone } = req.body;
      
      if (!message) {
        return res.status(400).json({
          success: false,
          message: 'Message text is required'
        });
      }

      const businessId = req.session.businessId;
      if (businessId) {
        const ok = await usageMeter.guard('ai', businessId, 'lead_extract_message');
        if (!ok) return res.status(429).json({ success: false, message: 'Monthly AI limit reached — upgrade your plan or wait for the next billing cycle.' });
      }

      // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
      const extractionResponse = await openai.chat.completions.create({
        model: "gpt-5",
        messages: [
          {
            role: "system",
            content: `You are an expert at extracting customer contact information from messages and emails for a field-service business in New Zealand.

Extract the following information:
- name: The REQUESTER's name — the person or company requesting the service (not your own staff). Check:
  • Email signature block (lines at the end with a person's name, company, and phone)
  • "For access contact" table field (may be a tenant, not the requester — prefer the sender's name)
  • "From" line or opening greeting
  • Property managers often sign off with their name, company, and number at the end
  • Fallback: if no explicit name is found anywhere, derive one from the email address local part (the bit before @): split on dots, underscores, hyphens or digits, drop digits, and Title Case the words. e.g. "debmasters18@gmail.com" → "Deb Masters", "john.smith@…" → "John Smith". Skip this fallback for generic local parts like "info", "admin", "contact", "hello", "sales", "office", "enquiries", "noreply".
- phone: The REQUESTER's phone number (from signature block or "contact" field). Format NZ numbers as 02X XXX XXXX.
- email: The REQUESTER's email address (from signature block or From/Reply-To)
- address: The SERVICE ADDRESS (the property where the work is needed). Look for:
  • Table fields labelled "Address", "Property address", "Location", or "at <address>"
  • "67A Valley Rd", "2/2 Maclean Street" style NZ addresses
  • Do NOT use business addresses from email signatures
- description: Summary of the work requested. Combine:
  • "Quote summary", "Quote details", "Service", or "Message" table fields
  • Any description of the issue, size, or access notes
  • Keep it concise but include the key service requested

Common email formats to handle:
1. Property management table emails — have fields: Address, Due date, For access contact, Quote summary, Quote details. Sender info is in the signature block.
2. Website contact forms — have fields: Name, Email, Phone, Message, How they heard.
3. Plain SMS/email — informal text with embedded address, phone, description.
4. Email signatures — "Crystal Merrilees\\nNew Zealand Property Managers\\n0212440626\\nnzpm@email.propertyme.com"

Return JSON: { "name": string, "phone": string, "email": string, "address": string, "description": string }
Use empty string if a field cannot be determined.`
          },
          {
            role: "user",
            content: message
          }
        ],
        response_format: { type: "json_object" },
        max_completion_tokens: 1024,
      });

      const extracted = JSON.parse(extractionResponse.choices[0].message.content || '{}');
      
      // Use provided phone if not found in message
      if (!extracted.phone && phone) {
        extracted.phone = phone;
      }

      if (businessId) await usageMeter.recordUsage('ai', businessId, { feature: 'lead_extract_message' });

      res.json({
        success: true,
        data: {
          name: extracted.name || '',
          phone: extracted.phone || '',
          email: extracted.email || '',
          address: extracted.address || '',
          description: extracted.description || '',
          rawMessage: message
        }
      });
    } catch (error) {
      console.error('Error extracting from message:', error);
      res.status(500).json({
        success: false,
        message: 'Failed to extract details from message'
      });
    }
  });

