  app.get('/api/quotes', async (req: Request, res: Response) => {
    try {
      const { customerId, leadId, jobId } = req.query;
      let quotes;
      
      if (customerId && typeof customerId === 'string') {
        quotes = await storage.getQuotesByCustomer(customerId);
      } else if (leadId && typeof leadId === 'string') {
        quotes = await storage.getQuotesByLead(leadId);
      } else if (jobId && typeof jobId === 'string') {
        // Look up the job and get its quoteId, or find quotes with leadId matching the jobId
        const job = await storage.getJob(jobId);
        if (job && job.quoteId) {
          const quote = await storage.getQuote(job.quoteId);
          quotes = quote ? [quote] : [];
        } else {
          // Fallback: try to find quotes where leadId matches the jobId
          quotes = await storage.getQuotesByLead(jobId);
        }
      } else {
        quotes = await storage.getAllQuotes();
      }
      
      res.json({ success: true, data: quotes });
    } catch (error) {
      console.error('Error fetching quotes:', error);
      res.status(500).json({ success: false, message: 'Error fetching quotes' });
    }
  });

  // Get proposals needing follow-up (MUST be before /:id route)
  app.get('/api/quotes/follow-up-queue', async (req: Request, res: Response) => {
    try {
      const allProposals = await storage.getAllProposals();
      
      // Filter for proposals needing follow-up: sent status (not accepted/rejected/draft)
      const followUpProposals = allProposals.filter(p => 
        p.status === 'sent'
      );

      // Enrich with customer and job data, calculate days since sent
      const enrichedProposals = await Promise.all(followUpProposals.map(async (proposal) => {
        const job = proposal.jobId ? await storage.getJob(proposal.jobId) : null;
        const customer = job?.customerId ? await storage.getCustomer(job.customerId) : null;
        const daysSinceSent = proposal.sentDate 
          ? Math.floor((Date.now() - new Date(proposal.sentDate).getTime()) / (1000 * 60 * 60 * 24))
          : null;
        
        return {
          ...proposal,
          customer,
          job,
          daysSinceSent,
        };
      }));

      // Filter out proposals where job status has changed (no longer needs follow-up)
      const activeFollowUps = enrichedProposals.filter(p => {
        if (!p.job) return true; // Keep if no job linked
        const jobStatus = p.job.status?.toLowerCase();
        // Remove if job has moved past the quote stage (i.e. the proposal
        // doesn't need following up anymore). 'scheduled' retired 2026-05.
        const completedStatuses = ['work_order', 'work order', 'unsuccessful', 'completed', 'cancelled', 'invoiced', 'archived'];
        return !completedStatuses.includes(jobStatus);
      });

      // Sort by days since sent (oldest first - need follow-up most urgently)
      activeFollowUps.sort((a, b) => {
        return (b.daysSinceSent || 0) - (a.daysSinceSent || 0);
      });

      res.json({ success: true, data: activeFollowUps });
    } catch (error) {
      console.error('Error fetching follow-up queue:', error);
      res.status(500).json({ success: false, message: 'Error fetching follow-up queue' });
    }
  });

