  // ──────────────────────────────────────────────────────────────────────────
  // Supplier invoices — bills FROM suppliers/subcontractors attached to a job.
  // Flow: snap a photo or attach a PDF → /extract uploads it to GCS and runs
  // GPT-5 over it to pre-fill the fields → tradie confirms → POST persists the
  // record. Costs surface in the gross-margin breakdown; rebillable lines get
  // pushed onto the job's lineItems (which flow to the customer invoice).
  // ──────────────────────────────────────────────────────────────────────────

  const SUPPLIER_COST_CATEGORIES = ['materials', 'subcontractor', 'equipment', 'disposal', 'other'];
  const normaliseSupplierCategory = (v: any): string =>
    SUPPLIER_COST_CATEGORIES.includes(String(v)) ? String(v) : 'materials';
  const toNum = (v: any): number | undefined => {
    if (v === null || v === undefined || v === '') return undefined;
    const n = typeof v === 'number' ? v : parseFloat(String(v));
    return Number.isFinite(n) ? n : undefined;
  };
  const toDate = (v: any): Date | undefined => {
    if (!v) return undefined;
    const d = new Date(v);
    return isNaN(d.getTime()) ? undefined : d;
  };

  // Distinct supplier names for autocomplete. Registered before the parameterised
  // routes so "supplier-names" isn't captured as an :id.
  app.get('/api/supplier-invoices/supplier-names', async (_req: Request, res: Response) => {
    try {
      const names = await storage.getSupplierNames();
      res.json({ success: true, data: names });
    } catch (error) {
      console.error('Error fetching supplier names:', error);
      res.status(500).json({ success: false, message: 'Error fetching supplier names' });
    }
  });

  // Upload a supplier invoice (image or PDF), store it in GCS, and run GPT-5
  // over it to extract the fields. Returns the extracted data + stored document
  // reference — nothing is persisted to supplier_invoices until the user
  // confirms via POST below.
  app.post('/api/jobs/:jobId/supplier-invoices/extract', imageUpload.single('file'), async (req: Request, res: Response) => {
    try {
      if (!req.session.employeeId) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
      }
      const file = req.file as Express.Multer.File | undefined;
      if (!file) {
        return res.status(400).json({ success: false, message: 'No file provided' });
      }

      const businessId = req.session.businessId;
      if (businessId) {
        const ok = await usageMeter.guard('ai', businessId, 'supplier_invoice_extract');
        if (!ok) return res.status(429).json({ success: false, message: 'Monthly AI limit reached — upgrade your plan or wait for the next billing cycle.' });
      }

      const { extracted, document, storageError } = await extractSupplierInvoiceFile(
        file.buffer,
        file.originalname,
        file.mimetype,
      );

      if (businessId) await usageMeter.recordUsage('ai', businessId, { feature: 'supplier_invoice_extract' });

      res.json({
        success: true,
        data: { extracted, document, storageError },
      });
    } catch (error) {
      console.error('Error extracting supplier invoice:', error);
      res.status(500).json({ success: false, message: error instanceof Error ? error.message : 'Error extracting supplier invoice' });
    }
  });

  // List supplier invoices for a job.
  app.get('/api/jobs/:jobId/supplier-invoices', async (req: Request, res: Response) => {
    try {
      const invoices = await storage.getSupplierInvoicesByJob(req.params.jobId);
      res.json({ success: true, data: invoices });
    } catch (error) {
      console.error('Error fetching supplier invoices:', error);
      res.status(500).json({ success: false, message: 'Error fetching supplier invoices' });
    }
  });

  // Persist a confirmed supplier invoice.
  app.post('/api/jobs/:jobId/supplier-invoices', async (req: Request, res: Response) => {
    try {
      const { jobId } = req.params;
      const b = req.body || {};
      if (!b.supplierName || !String(b.supplierName).trim()) {
        return res.status(400).json({ success: false, message: 'Supplier name is required' });
      }

      const lineItems = Array.isArray(b.lineItems) ? b.lineItems.map((li: any) => ({
        description: String(li.description || ''),
        quantity: toNum(li.quantity),
        unitCost: toNum(li.unitCost),
        totalCost: toNum(li.totalCost) ?? 0,
        rebill: !!li.rebill,
        markupPercent: toNum(li.markupPercent),
        category: li.category ? String(li.category) : undefined,
      })) : [];

      const created = await storage.createSupplierInvoice({
        jobId,
        supplierName: String(b.supplierName).trim(),
        invoiceNumber: b.invoiceNumber ? String(b.invoiceNumber) : null,
        invoiceDate: toDate(b.invoiceDate) ?? null,
        dueDate: toDate(b.dueDate) ?? null,
        subtotal: toNum(b.subtotal)?.toString() ?? null,
        gst: toNum(b.gst)?.toString() ?? null,
        total: (toNum(b.total) ?? 0).toString(),
        currency: b.currency ? String(b.currency) : 'NZD',
        costCategory: normaliseSupplierCategory(b.costCategory),
        documentUrl: b.documentUrl || null,
        thumbnailUrl: b.thumbnailUrl || null,
        originalFilename: b.originalFilename || null,
        mimeType: b.mimeType || null,
        fileSize: toNum(b.fileSize) ?? null,
        lineItems,
        rebill: !!b.rebill,
        markupPercent: (toNum(b.markupPercent) ?? 0).toString(),
        status: b.status === 'pending_review' ? 'pending_review' : 'confirmed',
        notes: b.notes ? String(b.notes) : null,
        rawExtraction: b.rawExtraction ?? null,
        createdBy: (req as any).user?.id || null,
      } as any);

      res.json({ success: true, data: created });
    } catch (error) {
      console.error('Error creating supplier invoice:', error);
      res.status(500).json({ success: false, message: error instanceof Error ? error.message : 'Error creating supplier invoice' });
    }
  });

  // Update a supplier invoice.
  app.patch('/api/supplier-invoices/:id', async (req: Request, res: Response) => {
    try {
      const b = req.body || {};
      const updates: any = {};
      if (b.supplierName !== undefined) updates.supplierName = String(b.supplierName).trim();
      if (b.invoiceNumber !== undefined) updates.invoiceNumber = b.invoiceNumber ? String(b.invoiceNumber) : null;
      if (b.invoiceDate !== undefined) updates.invoiceDate = toDate(b.invoiceDate) ?? null;
      if (b.dueDate !== undefined) updates.dueDate = toDate(b.dueDate) ?? null;
      if (b.subtotal !== undefined) updates.subtotal = toNum(b.subtotal)?.toString() ?? null;
      if (b.gst !== undefined) updates.gst = toNum(b.gst)?.toString() ?? null;
      if (b.total !== undefined) updates.total = (toNum(b.total) ?? 0).toString();
      if (b.currency !== undefined) updates.currency = String(b.currency);
      if (b.costCategory !== undefined) updates.costCategory = normaliseSupplierCategory(b.costCategory);
      if (b.notes !== undefined) updates.notes = b.notes ? String(b.notes) : null;
      if (b.rebill !== undefined) updates.rebill = !!b.rebill;
      if (b.markupPercent !== undefined) updates.markupPercent = (toNum(b.markupPercent) ?? 0).toString();
      if (b.status !== undefined) updates.status = b.status === 'pending_review' ? 'pending_review' : 'confirmed';
      if (Array.isArray(b.lineItems)) {
        updates.lineItems = b.lineItems.map((li: any) => ({
          description: String(li.description || ''),
          quantity: toNum(li.quantity),
          unitCost: toNum(li.unitCost),
          totalCost: toNum(li.totalCost) ?? 0,
          rebill: !!li.rebill,
          markupPercent: toNum(li.markupPercent),
          category: li.category ? String(li.category) : undefined,
        }));
      }

      const updated = await storage.updateSupplierInvoice(req.params.id, updates);
      res.json({ success: true, data: updated });
    } catch (error) {
      console.error('Error updating supplier invoice:', error);
      res.status(500).json({ success: false, message: 'Error updating supplier invoice' });
    }
  });

  // Delete a supplier invoice.
  app.delete('/api/supplier-invoices/:id', async (req: Request, res: Response) => {
    try {
      await storage.deleteSupplierInvoice(req.params.id);
      res.json({ success: true });
    } catch (error) {
      console.error('Error deleting supplier invoice:', error);
      res.status(500).json({ success: false, message: 'Error deleting supplier invoice' });
    }
  });

  // Rebill a supplier invoice's flagged lines onto the job's line items, marking
  // them up. The appended job line items are revenue and flow into the customer
  // invoice through the existing convert-to-invoice path. Idempotent-ish: sets
  // rebilledAt so the UI can show it's already been rebilled.
  app.post('/api/supplier-invoices/:id/rebill', async (req: Request, res: Response) => {
    try {
      const supplierInvoice = await storage.getSupplierInvoice(req.params.id);
      if (!supplierInvoice) {
        return res.status(404).json({ success: false, message: 'Supplier invoice not found' });
      }
      const job = await storage.getJob(supplierInvoice.jobId);
      if (!job) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      const headerMarkup = toNum(supplierInvoice.markupPercent) ?? 0;
      const lines = (Array.isArray(supplierInvoice.lineItems) ? supplierInvoice.lineItems : []) as any[];
      // If specific lines are flagged, rebill those; otherwise (header rebill)
      // rebill every line. Fall back to a single line for the whole total when
      // there are no extracted line items.
      const flagged = lines.filter(li => li.rebill);
      const toRebill = flagged.length > 0 ? flagged : (supplierInvoice.rebill ? lines : []);

      const newJobLineItems: any[] = [];
      // The rebilled line carries REVENUE only (unitPrice). The underlying cost
      // is already counted once via the supplier-invoice cost ledger, so we
      // deliberately omit unitCost/totalCost here to avoid double-counting it in
      // the gross-margin calculation.
      const pushLine = (description: string, cost: number, markup: number) => {
        const price = +(cost * (1 + (markup || 0) / 100)).toFixed(2);
        newJobLineItems.push({
          id: randomUUID(),
          description,
          quantity: 1,
          unitPrice: price,
          priceIncludesTax: false,
          taxRate: 15,
          rebilledFromSupplierInvoiceId: supplierInvoice.id,
        });
      };

      if (toRebill.length > 0) {
        for (const li of toRebill) {
          const cost = toNum(li.totalCost) ?? ((toNum(li.unitCost) ?? 0) * (toNum(li.quantity) ?? 1));
          const markup = toNum(li.markupPercent) ?? headerMarkup;
          pushLine(`${supplierInvoice.supplierName}: ${li.description || 'Supplied item'}`, cost, markup);
        }
      } else {
        // No itemised lines — rebill the whole ex-GST cost as one line.
        const cost = toNum(supplierInvoice.subtotal) ?? ((toNum(supplierInvoice.total) ?? 0) / 1.15);
        pushLine(`${supplierInvoice.supplierName}${supplierInvoice.invoiceNumber ? ` (inv ${supplierInvoice.invoiceNumber})` : ''}`, cost, headerMarkup);
      }

      if (newJobLineItems.length === 0) {
        return res.status(400).json({ success: false, message: 'No rebillable lines on this supplier invoice' });
      }

      const existingLineItems = Array.isArray((job as any).lineItems) ? (job as any).lineItems : [];
      const updatedJob = await storage.updateJob(job.id, { lineItems: [...existingLineItems, ...newJobLineItems] } as any);
      await storage.updateSupplierInvoice(supplierInvoice.id, { rebilledAt: new Date() } as any);

      res.json({ success: true, data: { job: updatedJob, addedLineItems: newJobLineItems } });
    } catch (error) {
      console.error('Error rebilling supplier invoice:', error);
      res.status(500).json({ success: false, message: error instanceof Error ? error.message : 'Error rebilling supplier invoice' });
    }
  });

  // Check invoice eligibility
  app.get('/api/jobs/:id/invoice-eligibility', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const updatedJob = await storage.updateInvoiceEligibility(id);
      res.json({ 
        success: true, 
        data: { 
          invoiceEligible: updatedJob.invoiceEligible,
          invoiceBlocked: updatedJob.invoiceBlocked,
          allExpensesComplete: updatedJob.allExpensesComplete,
          marginMeetsThreshold: updatedJob.marginMeetsThreshold,
          grossMargin: updatedJob.grossMargin
        } 
      });
    } catch (error) {
      console.error('Error checking invoice eligibility:', error);
      if (error instanceof Error && error.message.includes('not found')) {
        res.status(404).json({ success: false, message: 'Job not found' });
      } else {
        res.status(500).json({ success: false, message: 'Error checking invoice eligibility' });
      }
    }
  });

  // Consolidated back-costing rollup: revenue, labor, all cost categories,
  // completion state and gross margin in one payload. Reads only — every
  // mutation goes through the existing /expenses and /expense-completion
  // endpoints. Backs the Back Costing tab in the job card.
  app.get('/api/jobs/:id/back-costing', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const job = await storage.getJob(id);
      if (!job) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      const num = (v: unknown): number => {
        if (v === null || v === undefined || v === '') return 0;
        const n = typeof v === 'string' ? parseFloat(v) : (v as number);
        return Number.isFinite(n) ? n : 0;
      };

      const [staffEntries, invoices, supplierInvoices] = await Promise.all([
        storage.getJobStaffTimeEntries(id).catch(() => [] as any[]),
        storage.getInvoicesByJob(id).catch(() => [] as any[]),
        storage.getSupplierInvoicesByJob(id).catch(() => [] as any[]),
      ]);

      const laborTotalHours = (staffEntries as any[]).reduce(
        (sum, e: any) => sum + num(e.hours),
        0,
      );

      // Replicates the labor-cost rollup used by POST /api/jobs/:id/staff-time:
      // each entry's costRate, falling back to the employee's hourlyRate.
      let laborCalculatedCost = 0;
      for (const e of staffEntries as any[]) {
        let costRate: number = num(e.costRate);
        if (!costRate && e.employeeId) {
          const employee = await storage.getEmployee(e.employeeId).catch(() => null as any);
          costRate = num(employee?.hourlyRate);
        }
        laborCalculatedCost += num(e.hours) * costRate;
      }

      // actualLaborCosts is auto-synced from staff time on every entry change,
      // but owners can override via PUT /expenses. Trust the stored value;
      // fall back to the calculated cost when nothing has been stored yet.
      const storedLaborCost = num(job.actualLaborCosts);
      const laborCost = storedLaborCost > 0 ? storedLaborCost : laborCalculatedCost;

      const costs = {
        actualLaborCosts: laborCost,
        actualMaterialsCosts: num(job.actualMaterialsCosts),
        equipmentCosts: num(job.equipmentCosts),
        subcontractorCosts: num(job.subcontractorCosts),
        permitCosts: num(job.permitCosts),
        travelCosts: num(job.travelCosts),
        disposalCosts: num(job.disposalCosts),
        miscExpenses: num(job.miscExpenses),
      };
      const manualCostsTotal =
        costs.actualLaborCosts +
        costs.actualMaterialsCosts +
        costs.equipmentCosts +
        costs.subcontractorCosts +
        costs.permitCosts +
        costs.travelCosts +
        costs.disposalCosts +
        costs.miscExpenses;

      // Supplier invoices are a cost ledger of their own: snapped/forwarded
      // bills auto-count toward job costing without re-keying. Each one's
      // ex-GST amount folds into the back-costing field its costCategory maps
      // to, so the tradie sees one consolidated set of costs. (Rebilling a
      // supplier invoice adds REVENUE on the job line items; the cost is still
      // counted here either way — see POST /supplier-invoices/:id/rebill.)
      const SUPPLIER_CATEGORY_TO_FIELD: Record<string, string> = {
        materials: 'actualMaterialsCosts',
        subcontractor: 'subcontractorCosts',
        equipment: 'equipmentCosts',
        disposal: 'disposalCosts',
        other: 'miscExpenses',
      };
      const supplierByField: Record<string, number> = {};
      const supplierCountByField: Record<string, number> = {};
      let supplierInvoiceTotal = 0;
      let supplierPendingCount = 0;
      for (const inv of supplierInvoices as any[]) {
        // Bills forwarded in by email arrive as pending_review — don't let an
        // unconfirmed (possibly mis-read) bill move the margin until the owner
        // confirms it. Surface the count so the UI can prompt a review.
        if (inv.status === 'pending_review') {
          supplierPendingCount += 1;
          continue;
        }
        const sub = num(inv.subtotal);
        const exGst = sub > 0 ? sub : num(inv.total) / 1.15;
        if (exGst <= 0) continue;
        const field = SUPPLIER_CATEGORY_TO_FIELD[inv.costCategory] || 'miscExpenses';
        supplierByField[field] = (supplierByField[field] || 0) + exGst;
        supplierCountByField[field] = (supplierCountByField[field] || 0) + 1;
        supplierInvoiceTotal += exGst;
      }

      const costsTotal = manualCostsTotal + supplierInvoiceTotal;

      const primaryInvoice = (invoices as any[])[0];
      const invoiceTotal = primaryInvoice ? num(primaryInvoice.totalAmount) : null;
      // Back-costing revenue must be GST-exclusive to match the costs (which carry
      // no GST) and the job header value. Mirror the header's hierarchy:
      // explicit subtotal, else strip GST off the inc-GST totals (NZ GST = 15%).
      const subtotalExGst = num(job.subtotal);
      const totalIncGst = num(job.totalIncludingGst);
      const totalAmountIncGst = num(job.totalAmount);
      const quoteTotal =
        subtotalExGst > 0
          ? subtotalExGst
          : totalIncGst > 0
            ? totalIncGst / 1.15
            : totalAmountIncGst / 1.15;
      const revenueSource: 'invoice' | 'quote' | 'none' =
        invoiceTotal !== null && invoiceTotal > 0
          ? 'invoice'
          : quoteTotal > 0
            ? 'quote'
            : 'none';
      const revenueAmount =
        revenueSource === 'invoice' ? (invoiceTotal as number) : quoteTotal;

      const grossProfit = revenueAmount - costsTotal;
      const grossMarginPercent =
        revenueAmount > 0 ? (grossProfit / revenueAmount) * 100 : null;

      res.json({
        success: true,
        data: {
          job: {
            id: job.id,
            jobNumber: (job as any).jobNumber ?? null,
            status: job.status,
            customerName: (job as any).customerName ?? null,
          },
          revenue: {
            amount: revenueAmount,
            invoiceTotal,
            quoteTotal,
            source: revenueSource,
            invoiceId: primaryInvoice?.id ?? null,
            xeroStatus: (job as any).xeroStatus ?? null,
          },
          labor: {
            totalHours: laborTotalHours,
            totalCost: laborCost,
            calculatedCost: laborCalculatedCost,
            hasOverride: storedLaborCost > 0 && Math.abs(storedLaborCost - laborCalculatedCost) > 0.01,
            entryCount: (staffEntries as any[]).length,
          },
          costs: {
            ...costs,
            manualTotal: manualCostsTotal,
            total: costsTotal,
          },
          supplierInvoices: {
            total: supplierInvoiceTotal,
            byField: supplierByField,
            countByField: supplierCountByField,
            count: (supplierInvoices as any[]).length,
            pendingReview: supplierPendingCount,
          },
          completion: {
            labor: !!job.laborCostsComplete,
            materials: !!job.materialsCostsComplete,
            equipment: !!job.equipmentCostsComplete,
            subcontractor: !!job.subcontractorCostsComplete,
            other: !!job.otherExpensesComplete,
            allComplete: !!job.allExpensesComplete,
            invoiceBlocked: job.invoiceBlocked !== false,
          },
          margin: {
            grossProfit,
            grossMarginPercent,
          },
        },
      });
    } catch (error) {
      console.error('Error building back-costing rollup:', error);
      res.status(500).json({ success: false, message: 'Error building back-costing rollup' });
    }
  });

  // Convert job to invoice
  app.post('/api/jobs/:id/convert-to-invoice', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { invoiceType = 'full', customData = {} } = req.body;
      
      // Get the job
      const job = await storage.getJob(id);
      if (!job) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      // Check if job is eligible for invoicing  
      // Allow invoicing for most job types except 'cancelled' and 'lead' (leads should become quotes first)
      if (job.status === 'cancelled') {
        return res.status(400).json({ 
          success: false, 
          message: 'Cannot create invoices for cancelled jobs' 
        });
      }

      // Check if invoice already exists for this job
      const existingInvoices = await storage.getInvoicesByJob(job.id);
      if (existingInvoices && existingInvoices.length > 0) {
        const existing = existingInvoices[0];
        return res.status(409).json({ 
          success: false, 
          message: `Invoice already exists for this job (${existing.invoiceNumber}). Please edit the existing invoice instead of creating a duplicate.`,
          existingInvoice: {
            id: existing.id,
            invoiceNumber: existing.invoiceNumber,
            amount: existing.amount,
            status: existing.status
          }
        });
      }

      // Get default invoice template
      const defaultTemplate = await storage.getDefaultDocumentTemplate('invoice');

      // Generate invoice number using job number
      const invoiceNumber = job?.jobNumber ? String(job.jobNumber) : `INV-${Date.now().toString().slice(-6)}`;

      // Calculate due date - use custom date if provided, otherwise read from business settings
      const issueDate = new Date();
      let dueDate: Date;
      if (customData.dueDate) {
        dueDate = new Date(customData.dueDate);
      } else {
        const bizSettings = await storage.getBusinessSettings();
        const defaultDueDays = bizSettings?.invoicePaymentDays ?? 7;
        dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + defaultDueDays);
      }

      // Transform line items - use custom line items if provided, otherwise use job line items
      let transformedLineItems;
      if (customData.lineItems && customData.lineItems.length > 0) {
        transformedLineItems = customData.lineItems;
      } else {
        transformedLineItems = job.lineItems ? job.lineItems.map((item: any) => ({
          description: item.description,
          quantity: item.quantity,
          rate: item.unitPrice || item.rate || 0,
          amount: item.total || item.amount || (item.quantity * (item.unitPrice || item.rate || 0))
        })) : [];
      }

      // Calculate amount from line items (sum of all line item amounts)
      let amount = 0;
      if (transformedLineItems && transformedLineItems.length > 0) {
        amount = transformedLineItems.reduce((sum: number, item: any) => {
          const itemAmount = typeof item.amount === 'string' ? parseFloat(item.amount) : (item.amount || 0);
          return sum + itemAmount;
        }, 0);
      } else {
        // Fallback to job total amount if no line items
        amount = job.totalAmount ? parseFloat(job.totalAmount) : 0;
      }

      // Apply partial percentage if specified
      if (invoiceType === 'partial' && customData.percentage) {
        amount = amount * (parseFloat(customData.percentage) / 100);
      }

      // Build contact name from job if not provided
      const contactName = customData.contactName || 
        (job.jobContactFirstName && job.jobContactLastName 
          ? `${job.jobContactFirstName} ${job.jobContactLastName}`
          : job.jobContactFirstName || job.jobContactLastName || null);

      // Create invoice data with custom or default values
      const invoiceData = {
        customerId: job.customerId!,
        jobId: job.id,
        invoiceNumber,
        jobTitle: job.title || 'Unnamed Job',
        address: customData.address || job.billingAddress || job.address || '', // Use billing address first
        contactName: contactName || null, // Store contact person name
        issueDate,
        dueDate,
        amount: amount.toString(),
        status: 'draft' as const,
        description: customData.description || job.description || `Invoice for ${job.title || 'service'}`,
        items: transformedLineItems,
        notes: customData.notes || '',
        templateId: defaultTemplate?.id || null,
        paymentTerms: defaultTemplate?.paymentTerms || 'Payment due within 7 days'
      };

      // Create the invoice
      const invoice = await storage.createInvoice(invoiceData);

      // Update job to store invoice reference AND sync total amount for revenue metrics
      const jobUpdate: Record<string, unknown> = {
        invoiceId: invoice.id,
        invoiceBlocked: false,
        totalAmount: amount.toString() // Sync invoice amount to job for revenue tracking
      };
      // Backfill the job description from the invoice when the job has none yet,
      // so a description typed straight into the invoice surfaces on the job card.
      // Only fill when empty — never clobber an existing job description.
      const invoiceDescription = (customData.description || '').trim();
      if (invoiceDescription && !(job.description || '').trim()) {
        jobUpdate.description = invoiceDescription;
      }
      await storage.updateJob(id, jobUpdate);

      // Compute exc-GST and inc-GST totals per line item so the diary entry
      // can show both, clearly labelled. Without this, the diary dumped the
      // raw `amount` sum (whose GST basis depends on each item's
      // priceIncludesTax flag) while the job-card header always shows
      // exc-GST — producing confusing "$9,145 vs $7,952" discrepancies.
      type DiaryLineItem = {
        total?: number | string;
        amount?: number | string;
        quantity?: number | string;
        unitPrice?: number | string;
        rate?: number | string;
        priceIncludesTax?: boolean;
      };
      const taxRate = parseFloat(job.taxRate ?? '15') / 100 || 0.15;
      let exGstTotal = 0;
      let incGstTotal = 0;
      const sourceItems: DiaryLineItem[] =
        (customData.lineItems && customData.lineItems.length > 0)
          ? (customData.lineItems as DiaryLineItem[])
          : ((job.lineItems as DiaryLineItem[] | null) ?? []);
      if (sourceItems.length > 0) {
        for (const item of sourceItems) {
          const rawTotal = item.total ?? item.amount;
          const qty = Number(item.quantity) || 0;
          const unit = Number(item.unitPrice ?? item.rate) || 0;
          const raw = rawTotal ?? qty * unit;
          const v = typeof raw === 'string' ? parseFloat(raw) : Number(raw) || 0;
          if (item.priceIncludesTax) {
            incGstTotal += v;
            exGstTotal += v / (1 + taxRate);
          } else {
            exGstTotal += v;
            incGstTotal += v * (1 + taxRate);
          }
        }
      } else {
        // No line items — fall back to job.totalAmount with the job's tax mode.
        if (job.taxMode === 'tax_inclusive') {
          incGstTotal = amount;
          exGstTotal = amount / (1 + taxRate);
        } else {
          exGstTotal = amount;
          incGstTotal = amount * (1 + taxRate);
        }
      }
      if (invoiceType === 'partial' && customData.percentage) {
        const pct = parseFloat(customData.percentage) / 100;
        exGstTotal *= pct;
        incGstTotal *= pct;
      }
      const partialSuffix = invoiceType === 'partial' ? ' (partial)' : '';
      const diaryText = `Invoice ${invoiceNumber} created for $${exGstTotal.toFixed(2)} + GST — $${incGstTotal.toFixed(2)} total${partialSuffix}`;

      // Create diary entry for invoice creation with invoice-specific metadata
      try {
        const diaryEntry = await storage.createJobDiaryEntry({
          jobId: id,
          entryType: 'email', // Use 'email' type so it can display with invoice icon
          title: 'Invoice Created',
          description: diaryText, // Database requires description field
          content: diaryText,
          authorName: req.user?.name || 'System',
          authorRole: req.user?.role || 'system',
          metadata: {
            invoiceId: invoice.id,
            invoiceNumber: invoiceNumber,
            amount: amount.toString(),
            amountExGst: exGstTotal.toFixed(2),
            amountIncGst: incGstTotal.toFixed(2),
            action: 'invoice_created',
            documentType: 'invoice', // Mark this as an invoice document
            documentNumber: invoiceNumber
          }
        });
        
        console.log(`💰 Job ${job.jobNumber} converted to invoice ${invoiceNumber}`);
        console.log(`📝 Diary entry created: ${diaryEntry.id}`);
      } catch (diaryError) {
        console.error('❌ Failed to create diary entry for invoice:', diaryError);
        // Don't fail the whole invoice creation if diary entry fails
      }

      res.json({ 
        success: true, 
        data: invoice,
        message: `${invoiceType === 'partial' ? 'Partial invoice' : 'Invoice'} created successfully`
      });
    } catch (error) {
      console.error('Error converting job to invoice:', error);
      res.status(500).json({ success: false, message: 'Error creating invoice' });
    }
  });

  // Convert job to quote
  app.post('/api/jobs/:id/convert-to-quote', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { customData = {} } = req.body;
      
      // Get the job
      const job = await storage.getJob(id);
      if (!job) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      // Check if job is eligible for quoting  
      if (job.status === 'cancelled') {
        return res.status(400).json({ 
          success: false, 
          message: 'Cannot create quotes for cancelled jobs' 
        });
      }

      // Get default quote template
      const defaultTemplate = await storage.getDefaultDocumentTemplate('quote');

      // Generate quote number
      const today = new Date();
      const quoteNumber = `Q-${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${Date.now().toString().slice(-6)}`;

      // Calculate amount from job
      let amount = job.totalAmount ? parseFloat(job.totalAmount) : 0;

      // Calculate expiry date (default 30 days from now)
      const issueDate = new Date();
      const expiryDate = new Date();
      expiryDate.setDate(expiryDate.getDate() + 30);

      // Transform job line items to quote format (consistent with jobs schema)
      const transformedLineItems = job.lineItems ? job.lineItems.map((item: any) => ({
        id: item.id,
        description: item.description,
        quantity: item.quantity,
        unitPrice: item.unitPrice || item.rate || 0, // Handle both formats
        total: item.total || item.amount || (item.quantity * (item.unitPrice || item.rate || 0))
      })) : [];

      // Create quote data using job description and template properties
      const quoteData = {
        customerId: job.customerId!,
        quoteNumber,
        status: 'draft' as const,
        description: job.description || `Quote for ${job.title || 'service'}`, // Use job description
        amount: (amount * 1.15).toString(), // Total amount as string (required field)
        lineItems: transformedLineItems, // Include transformed line items
        terms: defaultTemplate?.paymentTerms || 'Quote valid for 30 days. GST included.',
        templateId: defaultTemplate?.id || null
      };

      // Create the quote
      const quote = await storage.createQuote(quoteData);

      // Update job to store quote reference
      await storage.updateJob(id, { 
        quoteId: quote.id
      });

      console.log(`📋 Job ${job.jobNumber} converted to quote ${quoteNumber}`);

      res.json({
        success: true,
        data: quote,
        message: 'Quote created successfully'
      });
    } catch (error) {
      console.error('Error converting job to quote:', error);
      res.status(500).json({ success: false, message: 'Error creating quote' });
    }
  });

  // Duplicate a job — copy the scoping/billing/line-item shape into a fresh
  // quote-status job. The intent is "same kind of work, new instance": same
  // customer + address + description + line items + contacts + checklists,
  // but new jobNumber, no scheduling, no assignments, no completion state,
  // no payments, no Xero/proposal sent flags. Used by the More-menu
  // "Duplicate Job" tile on JobCardMobile.
  app.post('/api/jobs/:id/duplicate', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const source = await storage.getJob(id);
      if (!source) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      // Reset checklist/equipmentChecklist completion state — the structure
      // (item text + ids) carries over, but every "completed/checked" flag
      // resets so the duplicate starts fresh.
      const resetChecklist = Array.isArray(source.checklist)
        ? (source.checklist as any[]).map((it) => ({
            ...it,
            completed: false,
            completedAt: undefined,
            completedBy: undefined,
            completedByEmployeeId: undefined,
          }))
        : [];
      const resetEquipmentChecklist = Array.isArray(source.equipmentChecklist)
        ? (source.equipmentChecklist as any[]).map((it) => ({
            ...it,
            checked: false,
            checkedAt: undefined,
            checkedBy: undefined,
          }))
        : [];

      const jobNumber = await storage.getNextJobNumber();
      const now = new Date();

      // Build the new job. Whitelist what carries — anything not listed below
      // intentionally resets to its column default. Don't spread `source`
      // wholesale; that would carry payment state, completion timestamps,
      // Xero IDs, etc. into the duplicate.
      const newJob: any = {
        // identity
        jobNumber,
        // scoping
        customerId: source.customerId,
        customerContactId: source.customerContactId,
        title: source.title,
        description: source.description,
        includeDescriptionInQuotesProposals: source.includeDescriptionInQuotesProposals,
        leadSource: source.leadSource,
        address: source.address,
        // workflow
        status: 'quote',
        priority: source.priority,
        // assignment/scheduling intentionally cleared — re-decide on the dup
        // crew, equipment templates
        equipment: source.equipment,
        specialInstructions: source.specialInstructions,
        // estimates carry, actuals do not
        estimatedDuration: source.estimatedDuration,
        estimatedManHours: source.estimatedManHours,
        hourlyRate: source.hourlyRate,
        totalAmount: source.totalAmount,
        costOfGoods: source.costOfGoods,
        laborCosts: source.laborCosts,
        materialsCosts: source.materialsCosts,
        otherCosts: source.otherCosts,
        minimumMarginThreshold: source.minimumMarginThreshold,
        // job-card content
        checklist: resetChecklist,
        equipmentChecklist: resetEquipmentChecklist,
        notes: source.notes,
        internalNotes: source.internalNotes,
        lineItems: source.lineItems,
        // proposal structure carries; sent state does not
        proposalTitle: source.proposalTitle,
        proposalSections: source.proposalSections,
        quotePresentationMethod: source.quotePresentationMethod,
        // job attributes
        weatherDependent: source.weatherDependent,
        permitRequired: source.permitRequired,
        insuranceClaim: source.insuranceClaim,
        // billing
        billingAddress: source.billingAddress,
        billingNameOverride: source.billingNameOverride,
        city: source.city,
        region: source.region,
        invoiceDescription: source.invoiceDescription,
        billingContactEmail: source.billingContactEmail,
        billingContactPhone: source.billingContactPhone,
        billingContactMobile: source.billingContactMobile,
        sameAsJobAddress: source.sameAsJobAddress,
        // contacts
        jobContactFirstName: source.jobContactFirstName,
        jobContactLastName: source.jobContactLastName,
        jobContactEmail: source.jobContactEmail,
        jobContactPhone: source.jobContactPhone,
        jobContactMobile: source.jobContactMobile,
        tenantContactFirstName: source.tenantContactFirstName,
        tenantContactLastName: source.tenantContactLastName,
        tenantContactEmail: source.tenantContactEmail,
        tenantContactPhone: source.tenantContactPhone,
        tenantContactMobile: source.tenantContactMobile,
        // GST shape carries; totals will be recalculated on edit
        taxMode: source.taxMode,
        taxRate: source.taxRate,
        // metrics — duplicates count as fresh metrics-eligible jobs
        metricsEligible: true,
        metricsStartDate: now,
        // dispatch sort signal
        lastActivityAt: now,
      };

      const created = await storage.createJob(newJob);
      console.log(`🧬 Duplicated job ${source.jobNumber} → ${created.jobNumber} (${created.id})`);

      res.json({
        success: true,
        data: created,
        sourceJobNumber: source.jobNumber,
        message: `Created job ${created.jobNumber} from ${source.jobNumber}`,
      });
    } catch (error) {
      console.error('Error duplicating job:', error);
      res.status(500).json({ success: false, message: 'Failed to duplicate job' });
    }
  });

  // Send proposal email
  app.post('/api/proposals/:proposalId/send-email', async (req: Request, res: Response) => {
    try {
      const { proposalId } = req.params;
      const { to, subject, message, cc, includeProposalPDF = true } = req.body;

      // Validate required fields
      if (!to || !subject) {
        return res.status(400).json({
          success: false,
          message: 'Recipient email and subject are required'
        });
      }

      // Get proposal details
      const proposal = await storage.getProposal(proposalId);
      if (!proposal) {
        return res.status(404).json({
          success: false,
          message: 'Proposal not found'
        });
      }

      // Get job details
      let job;
      if (proposal.jobId) {
        job = await storage.getJob(proposal.jobId);
      }
      // Reply-To is handled by emailService default (info@treemarkables.nz)

      // Get customer details
      let customer;
      if (proposal.customerId) {
        customer = await storage.getCustomer(proposal.customerId);
      }

      // Get proposal sections and line items
      const sections = await storage.getProposalSectionsByProposal(proposalId);
      const lineItems = await storage.getProposalLineItemsByProposal(proposalId);
      
      console.log(`📧 Preparing email for proposal ${proposalId}`);
      console.log(`📋 Found ${sections.length} sections with ${lineItems.length} line items`);
      
      // Group line items by section
      const sectionLineItems = new Map<string, any[]>();
      for (const item of lineItems) {
        if (item.sectionId) {
          if (!sectionLineItems.has(item.sectionId)) {
            sectionLineItems.set(item.sectionId, []);
          }
          sectionLineItems.get(item.sectionId)!.push(item);
        }
      }

      // Calculate totals
      let subtotal = 0;
      for (const item of lineItems) {
        if (item.selected) {
          subtotal += parseFloat(item.totalPrice || '0');
        }
      }
      // Apply the proposal-level discount so the emailed headline total matches
      // the discounted total shown on the customer-facing proposal page. Without
      // this the email advertised the pre-discount total. discountAmount is
      // stored as a dollar amount (see the CREATE/PUT/accept handlers).
      const emailDiscountAmt = parseFloat(proposal.discountAmount?.toString() || '0') || 0;
      const subtotalAfterDiscount = Math.max(0, subtotal - emailDiscountAmt);
      const gst = subtotalAfterDiscount * 0.15;
      const total = subtotalAfterDiscount + gst;

      // Pre-send validation — block silent rendering failures from reaching the customer.
      // Mirrors what buildProposalRenderContext (BlockRenderedProposal.tsx) reads:
      // description = proposal.introduction OR concatenated content of any non-photos /
      // non-line-items section. Keep this in sync if the renderer's logic changes.
      const validationErrors: string[] = [];

      if (!customer?.name?.trim()) {
        validationErrors.push('customer name is missing');
      }

      const hasIntroduction = !!proposal.introduction && proposal.introduction.trim().length > 0;
      const hasDescriptionSection = sections.some(s =>
        s.sectionType !== 'photos'
        && (!s.images || s.images.length === 0)
        && !sectionLineItems.has(s.id)
        && !!s.content
        && s.content.trim().length > 0,
      );
      if (!hasIntroduction && !hasDescriptionSection) {
        validationErrors.push('proposal has no description text — the customer would see an empty job description');
      }

      const selectedLineItems = lineItems.filter(li => li.selected);
      if (selectedLineItems.length === 0) {
        validationErrors.push('proposal has no selected line items');
      }

      if (subtotal <= 0) {
        validationErrors.push('proposal total is $0');
      }

      if (validationErrors.length > 0) {
        console.warn(`⚠️  Blocked send for proposal ${proposalId}: ${validationErrors.join('; ')}`);
        return res.status(400).json({
          success: false,
          code: 'PROPOSAL_INCOMPLETE',
          message: `This proposal isn't ready to send: ${validationErrors.join('; ')}.`,
          errors: validationErrors,
        });
      }

      // Always use the production domain for customer-facing links
      // to prevent dev/preview URLs from leaking into customer emails/SMS
      const baseUrl = APP_URL;
      
      // Prepare email content
      const customerName = customer?.name || 'Valued Customer';
      
      // Check if proposal still has a DRAFT number - if so, convert to proper PROP number
      let proposalNumber = proposal.proposalNumber || 'N/A';
      if (proposalNumber.startsWith('DRAFT-')) {
        // Simply replace DRAFT- prefix with PROP- to preserve the original identifier
        proposalNumber = proposalNumber.replace('DRAFT-', 'PROP-');
        // Update the proposal with the new number
        await storage.updateProposal(proposalId, {
          proposalNumber: proposalNumber
        });
        console.log(`📋 Converted DRAFT number to ${proposalNumber}`);
      }
      
      // Simple email - just a notification with link to view proposal online

      // Get customer contact details for header
      const customerEmail = customer?.email || job?.jobContactEmail || '';
      const customerPhone = customer?.phone || job?.jobContactPhone || '';
      
      // Generate proposal acceptance URL - goes directly to acceptance page
      const proposalAcceptUrl = `${baseUrl}/proposal/${proposalId}/accept`;
      
      const __emailIdentity = getBusinessIdentity(await storage.getBusinessSettings());
      const htmlContent = renderBrandedEmail({
        company: { name: __emailIdentity.name, tagline: __emailIdentity.tagline, address: __emailIdentity.address, phone: __emailIdentity.phone, email: __emailIdentity.email, gstNumber: __emailIdentity.gstNumber },
        customerName,
        intro: message || 'Thank you for your enquiry — we\'re pleased to provide the following proposal. Tap the button below to review the full scope, pricing, and accept online.',
        documentLabel: `Proposal #${proposalNumber}`,
        totalAmount: total,
        totalLabel: 'incl. GST',
        ctaText: 'View Proposal',
        ctaUrl: proposalAcceptUrl,
        ctaHint: 'Opens the proposal in your browser — no login required.',
      });

      console.log('📧 EMAIL HTML CONTENT:', htmlContent);
      console.log('📧 EMAIL TEXT CONTENT:', `Proposal ${proposalNumber} for ${customerName}. Total Amount: $${total.toFixed(2)} NZD. ${message || 'Thank you for your interest in our services.'}`);

      // Send email using EmailService (photos are hosted URLs, no attachments needed)
      // Pass jobNumber so Cloudflare Email Routing forwards replies to job-specific address
      const emailResult = await emailService.sendEmail({
        to,
        cc,
        fromName: __emailIdentity.name || undefined, // From shows the tenant's business name; blank → platform default
        subject,
        html: htmlContent,
        text: `Proposal ${proposalNumber} for ${customerName}. Total Amount: $${total.toFixed(2)} NZD. ${message || 'Thank you for your interest in our services.'}`,
        jobNumber: job?.jobNumber // Reply-to will be job-{number}@jobs.treemarkables.co.nz
      });

      if (!emailResult.success) {
        return res.status(500).json({
          success: false,
          message: emailResult.error || 'Failed to send proposal email'
        });
      }

      console.log(`📧 Proposal ${proposalNumber} email sent to ${to}${emailResult.messageId ? ` (Message ID: ${emailResult.messageId})` : ''}`);

      // Update proposal status to 'sent' and record sent date
      await storage.updateProposal(proposalId, {
        status: 'sent',
        sentDate: new Date()
      });
      console.log(`📋 Updated proposal ${proposalNumber} status to 'sent'`);

      // Create diary entry for sent proposal email
      if (proposal.jobId) {
        try {
          const diaryEntry = await storage.createJobDiaryEntry({
            jobId: proposal.jobId,
            entryType: 'email',
            title: `Proposal Sent: ${proposalNumber}`,
            description: `Proposal "${proposal.title || 'Treemarkables Quote'}" sent to ${to}${cc ? ` (CC: ${cc})` : ''}\n\nTotal: $${subtotal.toFixed(2)} NZD excl. GST`,
            authorName: 'System',
            metadata: {
              proposalId,
              proposalNumber,
              recipient: to,
              cc: cc || null,
              total: total.toFixed(2),
              sendgridMessageId: emailResult.messageId
            }
          });

          await notificationHelper.createJobActivityNotification({
            jobId: proposal.jobId,
            type: 'proposal_sent',
            title: 'Proposal Sent',
            message: `Proposal ${proposalNumber} sent to ${customer?.name || to}`,
            priority: 'high',
            authorName: 'System',
            diaryEntryId: diaryEntry.id,
            proposalId,
            userId: (req as any).user?.id,
            metadata: {
              proposalNumber,
              recipient: to,
              total: total.toFixed(2),
            },
          });

          // Update job's lastActivityAt and status to 'quote' when proposal is sent
          // Only upgrade status if it's currently 'lead' (don't downgrade work_order, scheduled, etc.)
          const job = await storage.getJob(proposal.jobId);
          const updateData: any = { 
            lastActivityAt: new Date(),
            quotePresentedDate: new Date() // Track when quote was presented
          };
          
          // Auto-upgrade status from Lead to Quote when proposal is sent
          if (job && job.status === 'lead') {
            updateData.status = 'quote';
            console.log(`📊 Auto-upgraded job ${job.jobNumber} status from 'lead' to 'quote'`);
          }
          
          await storage.updateJob(proposal.jobId, updateData);

          // Lanes: if a lane is set to auto-receive jobs when a quote is sent, move it now.
          onQuoteSentToLane(proposal.jobId).catch(err => console.error('[Lanes] quote-sent auto-entry error:', err));

          console.log(`📝 Created diary entry for proposal ${proposalNumber} email`);
        } catch (diaryError) {
          console.error('Error creating diary entry for proposal email:', diaryError);
        }
      }

      res.json({
        success: true,
        message: 'Proposal email sent successfully',
        data: {
          proposalId,
          proposalNumber,
          recipient: to,
          sentAt: new Date().toISOString()
        }
      });

    } catch (error) {
      // Surface the real cause: the previous generic message hid the failing
      // step (DB write, render, identity lookup) from both the user and logs,
      // making "Email Failed" impossible to diagnose.
      const detail = error instanceof Error ? error.message : String(error);
      console.error(`Error sending proposal email (proposal ${req.params.proposalId}, to ${req.body?.to}):`, error);
      res.status(500).json({
        success: false,
        message: `Error sending proposal email: ${detail}`
      });
    }
  });

  // Send quote email — "View Quote" CTA opens the online accept page; the quote
  // PDF is attached. Replying "I accept quote Q-*" still auto-accepts via the
  // email webhook as a fallback.
  app.post('/api/proposals/:proposalId/send-quote-email', async (req: Request, res: Response) => {
    try {
      const { proposalId } = req.params;
      const { to, subject, message, cc } = req.body;

      if (!to || !subject) {
        return res.status(400).json({
          success: false,
          message: 'Recipient email and subject are required'
        });
      }

      const proposal = await storage.getProposal(proposalId);
      if (!proposal) {
        return res.status(404).json({ success: false, message: 'Quote not found' });
      }

      const job = proposal.jobId ? await storage.getJob(proposal.jobId) : null;
      const customer = proposal.customerId ? await storage.getCustomer(proposal.customerId) : null;

      // Mark this record as a quote on first send (templateUsed drives PDF + acceptance behaviour).
      if (proposal.templateUsed !== 'quote') {
        await storage.updateProposal(proposalId, { templateUsed: 'quote' });
      }

      // Promote draft number Q-DRAFT-* → Q-* so the customer-facing number is stable.
      let quoteNumber = proposal.proposalNumber || 'N/A';
      if (quoteNumber.startsWith('Q-DRAFT-')) {
        quoteNumber = quoteNumber.replace('Q-DRAFT-', 'Q-');
        await storage.updateProposal(proposalId, { proposalNumber: quoteNumber });
      } else if (quoteNumber.startsWith('DRAFT-')) {
        quoteNumber = quoteNumber.replace('DRAFT-', 'Q-');
        await storage.updateProposal(proposalId, { proposalNumber: quoteNumber });
      }

      // Recompute totals from the live line items for the email body.
      const lineItems = await storage.getProposalLineItemsByProposal(proposalId);
      let subtotal = 0;
      for (const item of lineItems) {
        if (item.selected !== false) subtotal += parseFloat(item.totalPrice || '0');
      }
      // Apply the proposal-level discount so the emailed total matches the
      // discounted total on the proposal page (discountAmount is in dollars).
      const quoteDiscountAmt = parseFloat(proposal.discountAmount?.toString() || '0') || 0;
      const subtotalAfterDiscount = Math.max(0, subtotal - quoteDiscountAmt);
      const gst = subtotalAfterDiscount * 0.15;
      const total = subtotalAfterDiscount + gst;

      // Pre-send validation — block silent rendering failures from reaching the customer.
      // Same checks as /send-email; the failure modes (missing description, no line items,
      // $0 total) all produce broken PDFs that the customer will only flag after the fact.
      const sectionsForValidation = await storage.getProposalSectionsByProposal(proposalId);
      const sectionLineItemIds = new Set(
        lineItems.filter(li => li.sectionId).map(li => li.sectionId as string),
      );
      const validationErrors: string[] = [];

      if (!customer?.name?.trim()) {
        validationErrors.push('customer name is missing');
      }

      const hasIntroduction = !!proposal.introduction && proposal.introduction.trim().length > 0;
      const hasDescriptionSection = sectionsForValidation.some(s =>
        s.sectionType !== 'photos'
        && (!s.images || s.images.length === 0)
        && !sectionLineItemIds.has(s.id)
        && !!s.content
        && s.content.trim().length > 0,
      );
      if (!hasIntroduction && !hasDescriptionSection) {
        validationErrors.push('quote has no description text — the PDF would have an empty job description');
      }

      const selectedLineItems = lineItems.filter(li => li.selected !== false);
      if (selectedLineItems.length === 0) {
        validationErrors.push('quote has no selected line items');
      }

      if (subtotal <= 0) {
        validationErrors.push('quote total is $0');
      }

      if (validationErrors.length > 0) {
        console.warn(`⚠️  Blocked send for quote ${proposalId}: ${validationErrors.join('; ')}`);
        return res.status(400).json({
          success: false,
          code: 'PROPOSAL_INCOMPLETE',
          message: `This quote isn't ready to send: ${validationErrors.join('; ')}.`,
          errors: validationErrors,
        });
      }

      // Generate PDF buffer for the attachment.
      const { buffer: pdfBuffer } = await generateProposalPDFBuffer(proposalId);
      const pdfBase64 = pdfBuffer.toString('base64');

      // "View Quote" opens the online accept page (same page proposals use; the
      // ?type=quote hint labels it as a quote before data loads). Replies still
      // land in the job inbox via emailService's reply-to, so the
      // "I accept quote Q-*" webhook fallback keeps working.
      const quoteAcceptUrl = `${APP_URL}/proposal/${proposalId}/accept?type=quote`;

      const customerName = customer?.name || 'Valued Customer';
      const bodyLead = message && message.trim().length > 0
        ? message
        : `Thank you for your enquiry.`;

      const __emailIdentity = getBusinessIdentity(await storage.getBusinessSettings());
      const htmlContent = renderBrandedEmail({
        company: { name: __emailIdentity.name, tagline: __emailIdentity.tagline, address: __emailIdentity.address, phone: __emailIdentity.phone, email: __emailIdentity.email, gstNumber: __emailIdentity.gstNumber },
        customerName,
        intro: `${bodyLead}\n\nTap the button below to review your quote and accept it online. The full quote is also attached as a PDF.`,
        documentLabel: `Quote #${quoteNumber}`,
        totalAmount: total,
        totalLabel: 'incl. GST',
        ctaText: 'View Quote',
        ctaUrl: quoteAcceptUrl,
        ctaHint: 'Opens your quote in the browser — review and accept online. No login required.',
        fineprint: `Prefer email? Just reply to this email with: "I accept quote ${quoteNumber}".`,
      });

      const textContent = [
        `Quote ${quoteNumber} for ${customerName}.`,
        `Total (inc. GST): $${total.toFixed(2)} NZD.`,
        `${bodyLead}`,
        `View and accept your quote online: ${quoteAcceptUrl}`,
        `The quote is attached as a PDF. Or reply to this email with: I accept quote ${quoteNumber}`,
      ].join('\n\n');

      const emailResult = await emailService.sendEmail({
        to,
        cc,
        fromName: __emailIdentity.name || undefined, // From shows the tenant's business name; blank → platform default
        subject,
        html: htmlContent,
        text: textContent,
        jobNumber: job?.jobNumber,
        attachments: [
          {
            filename: `Quote-${quoteNumber}.pdf`,
            content: pdfBase64,
            type: 'application/pdf',
          },
        ],
      });

      if (!emailResult.success) {
        return res.status(500).json({
          success: false,
          message: emailResult.error || 'Failed to send quote email',
        });
      }

      // Update proposal to sent status.
      await storage.updateProposal(proposalId, {
        status: 'sent',
        sentDate: new Date(),
        deliveryMethod: 'email',
      });

      // Diary entry + job activity (mirrors proposal email flow, minus the viewer link).
      if (proposal.jobId) {
        try {
          const diaryEntry = await storage.createJobDiaryEntry({
            jobId: proposal.jobId,
            entryType: 'email',
            title: `Quote ${quoteNumber} emailed`,
            description: `Quote ${quoteNumber} sent to ${to} (total $${total.toFixed(2)} NZD)`,
            content: `Quote ${quoteNumber} sent to ${to}`,
            authorName: (req as any).user?.name || 'System',
            authorRole: (req as any).user?.role || 'system',
            metadata: {
              proposalId,
              quoteNumber,
              recipient: to,
              cc: cc || null,
              total: total.toFixed(2),
              documentType: 'quote',
              documentNumber: quoteNumber,
              sendgridMessageId: emailResult.messageId,
            },
          });

          await notificationHelper.createJobActivityNotification({
            jobId: proposal.jobId,
            type: 'quote_sent',
            title: 'Quote Sent',
            message: `Quote ${quoteNumber} sent to ${to}`,
            priority: 'high',
            authorName: (req as any).user?.name || 'System',
            diaryEntryId: diaryEntry.id,
            proposalId,
            userId: (req as any).user?.id,
            metadata: {
              quoteNumber,
              recipient: to,
              total: total.toFixed(2),
            },
          });

          const jobForUpdate = await storage.getJob(proposal.jobId);
          const updateData: any = {
            lastActivityAt: new Date(),
            quotePresentedDate: new Date(),
          };
          if (jobForUpdate && jobForUpdate.status === 'lead') {
            updateData.status = 'quote';
          }
          await storage.updateJob(proposal.jobId, updateData);

          // Lanes: if a lane is set to auto-receive jobs when a quote is sent, move it now.
          onQuoteSentToLane(proposal.jobId).catch(err => console.error('[Lanes] quote-sent auto-entry error:', err));
        } catch (diaryError) {
          console.error('Error creating diary entry for quote email:', diaryError);
        }
      }

      res.json({
        success: true,
        message: 'Quote email sent successfully',
        data: {
          proposalId,
          quoteNumber,
          recipient: to,
          sentAt: new Date().toISOString(),
        },
      });
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      console.error(`Error sending quote email (proposal ${req.params.proposalId}, to ${req.body?.to}):`, error);
      res.status(500).json({
        success: false,
        message: `Error sending quote email: ${detail}`,
      });
    }
  });

  // Send invoice email
  app.post('/api/emails/send', async (req: Request, res: Response) => {
    try {
      const { to, cc, subject, body, attachments, selectedPhotos = [], jobId, customerId, invoiceId, quoteId, invoiceData } = req.body;
      
      console.log('📧 Email send request received:');
      console.log('   - To:', to);
      console.log('   - Subject:', subject);
      console.log('   - JobId:', jobId);
      console.log('   - CustomerId:', customerId);
      console.log('   - InvoiceId:', invoiceId);
      console.log('   - InvoiceData id:', invoiceData?.id, 'number:', invoiceData?.invoiceNumber);
      console.log('   - Selected photos count:', selectedPhotos?.length || 0);
      console.log('   - Client attachments:', JSON.stringify((attachments || []).map((a: any) => ({type: a.type, id: a.id}))));
      
      // DEFENSIVE FIX: Validate invoiceData is a proper object with required properties
      // The frontend may sometimes serialize it incorrectly as a boolean
      let validatedInvoiceData = invoiceData;
      if (invoiceData && typeof invoiceData !== 'object') {
        console.warn('⚠️ invoiceData is not an object (type:', typeof invoiceData, ') - clearing it');
        validatedInvoiceData = null;
      } else if (invoiceData && (!invoiceData.invoiceNumber || !invoiceData.id)) {
        console.warn('⚠️ invoiceData missing required properties (invoiceNumber or id) - checking...');
        // If invoiceData has an id but is missing other fields, we'll fetch from DB later
        if (!invoiceData.id && !invoiceData.invoiceNumber) {
          console.warn('⚠️ invoiceData has no id or invoiceNumber - clearing it');
          validatedInvoiceData = null;
        }
      }
      
      // Validate required fields
      if (!to || !subject || !body) {
        return res.status(400).json({
          success: false,
          message: 'Missing required email fields: to, subject, body'
        });
      }

      // Microsoft-hosted addresses silently strip PDFs when inline CID images are present.
      // We skip both the photo and logo CID attachments for these recipients so the PDF lands.
      const recipientIsMicrosoft = typeof to === 'string' && isMicrosoftEmailDomain(to);

      // Get related data for email context
      let job, customer, invoice, quote;
      if (jobId) {
        job = await storage.getJob(jobId);
      }
      if (customerId) {
        customer = await storage.getCustomer(customerId);
      }
      
      // If invoice data is provided but no invoiceId, create or find the invoice
      let emailBody = body; // Create mutable copy of body
      const effectiveInvoiceId = invoiceId || validatedInvoiceData?.id;
      
      if (validatedInvoiceData && !effectiveInvoiceId) {
        try {
          const newInvoice = await storage.createInvoice({
            jobId: validatedInvoiceData.jobId || jobId,
            customerId: validatedInvoiceData.customerId || customerId,
            invoiceNumber: validatedInvoiceData.invoiceNumber,
            amount: validatedInvoiceData.totalAmount,
            dueDate: validatedInvoiceData.dueDate ? new Date(validatedInvoiceData.dueDate) : undefined,
            issueDate: validatedInvoiceData.issueDate ? new Date(validatedInvoiceData.issueDate) : undefined,
            status: 'sent', // Mark as sent since we're sending it now
            items: validatedInvoiceData.lineItems || [],
            description: validatedInvoiceData.description,
            notes: validatedInvoiceData.notes || '',
            jobTitle: job?.title || job?.description || 'Service'
          });
          invoice = newInvoice;
          console.log('✅ Invoice created with ID:', invoice.id);
          
          // Sync invoice amount to job's totalAmount for revenue tracking
          if (jobId && validatedInvoiceData.totalAmount) {
            await storage.updateJob(jobId, {
              totalAmount: validatedInvoiceData.totalAmount.toString()
            });
            console.log('💰 Synced invoice amount to job total_amount:', validatedInvoiceData.totalAmount);
          }
        } catch (error: any) {
          // If duplicate invoice number, this invoice was already created - fetch it by number
          if (error.code === '23505' && error.constraint === 'invoices_invoice_number_unique') {
            console.log('📋 Invoice already exists with number:', validatedInvoiceData.invoiceNumber, '- fetching existing invoice');
            // Query the database directly to find the invoice by invoice number
            const result = await db.select()
              .from(invoices)
              .where(eq(invoices.invoiceNumber, validatedInvoiceData.invoiceNumber))
              .limit(1);
            
            if (result.length > 0) {
              invoice = result[0];
              console.log('✅ Found existing invoice with ID:', invoice.id);
            } else {
              console.warn('⚠️ Could not find existing invoice with number:', validatedInvoiceData.invoiceNumber);
              invoice = null;
            }
          } else {
            throw error; // Re-throw other errors
          }
        }
        
        // Replace temporary invoice ID in email body with real invoice ID
        // The frontend uses the job ID as a placeholder, so we replace any invoice links
        if (invoice) {
          const tempInvoiceId = validatedInvoiceData.jobId || jobId;
          if (tempInvoiceId && emailBody.includes(`/invoice/${tempInvoiceId}`)) {
            emailBody = emailBody.replace(new RegExp(`/invoice/${tempInvoiceId}`, 'g'), `/invoice/${invoice.id}`);
            console.log('✅ Updated invoice link in email body from', tempInvoiceId, 'to', invoice.id);
          }
        }
      } else if (effectiveInvoiceId) {
        invoice = await storage.getInvoice(effectiveInvoiceId);
        if (invoice) {
          console.log(`📄 Fetched invoice from DB: #${invoice.invoiceNumber} (${invoice.id}), items: ${(invoice.items || []).length}`);
        } else {
          console.warn(`⚠️ Invoice not found in DB for effectiveInvoiceId: ${effectiveInvoiceId}`);
        }
      }
      
      if (quoteId) {
        quote = await storage.getQuote(quoteId);
      }

      // Persist sender-selected photos onto the invoice itself so they show up
      // on every downstream surface — the customer's online invoice view
      // (/invoice/:id reads invoice_sections.images), the PDF served by
      // /api/invoices/:id/pdf (the Microsoft download-link fallback), and any
      // future re-send of the same invoice. Without this, the photos only ever
      // exist as transient CID attachments on the outgoing email.
      const photosToPersist: string[] = Array.isArray(selectedPhotos)
        ? selectedPhotos.filter(isSupportedPhotoUrl)
        : [];
      if (invoice && photosToPersist.length > 0) {
        try {
          const existingSections = await storage.getInvoiceSectionsByInvoice(invoice.id);
          const existingPhotoSection = existingSections.find(s => s.sectionType === 'photos');
          if (existingPhotoSection) {
            // Merge new photos with existing, dedup, preserve insertion order
            const merged = Array.from(new Set([...(existingPhotoSection.images || []), ...photosToPersist]));
            await storage.updateInvoiceSection(existingPhotoSection.id, { images: merged });
            console.log(`📎 Updated invoice photo section ${existingPhotoSection.id} → ${merged.length} photo(s)`);
          } else {
            const nextSortOrder = existingSections.reduce((max, s) => Math.max(max, s.sortOrder ?? 0), -1) + 1;
            const created = await storage.createInvoiceSection({
              invoiceId: invoice.id,
              sectionType: 'photos',
              title: 'Job Photos',
              content: '',
              images: photosToPersist,
              sortOrder: nextSortOrder,
              isVisible: true,
            });
            console.log(`📎 Created invoice photo section ${created.id} with ${photosToPersist.length} photo(s)`);
          }
        } catch (sectionErr) {
          console.error('Error persisting selected photos to invoice sections:', sectionErr);
        }
      }

      // Reply-To is handled by emailService default (info@treemarkables.nz)

      // Generate invoice HTML if invoice data is available
      let invoiceHtml = '';
      
      // Helper functions - defined outside blocks so accessible to both HTML and PDF generation
      const formatCurrency = (num: number) => {
        return new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(num);
      };
      
      const formatDate = (date: any) => {
        if (!date) return '';
        return new Date(date).toLocaleDateString('en-NZ', { day: '2-digit', month: '2-digit', year: 'numeric' });
      };
      
      if (invoice || validatedInvoiceData) {
        const invoiceDetails = invoice || validatedInvoiceData;
        const lineItems = invoiceDetails.items || validatedInvoiceData?.lineItems || [];
        
        // Calculate totals
        const gstRate = 0.15;
        let subtotal = 0;
        let gstAmount = 0;
        let totalAmount = 0;
        
        if (lineItems && lineItems.length > 0) {
          // Calculate from line items (ex-GST)
          subtotal = lineItems.reduce((sum: number, item: any) => {
            // Check both 'total' and 'amount' fields for backwards compatibility
            const itemTotal = item.total || item.amount;
            const total = typeof itemTotal === 'string' ? parseFloat(itemTotal) : (itemTotal || 0);
            return sum + total;
          }, 0);
          gstAmount = subtotal * gstRate;
          totalAmount = subtotal + gstAmount;
        } else {
          // Use invoice amount as ex-GST
          const amount = typeof invoiceDetails.amount === 'string' ? parseFloat(invoiceDetails.amount) : (invoiceDetails.amount || 0);
          subtotal = amount;
          gstAmount = subtotal * gstRate;
          totalAmount = subtotal + gstAmount;
        }
        
        // Build the branded invoice email (per-business identity + brand colours +
        // bank details). Replaces the old Treemarkables-only markup. The composed
        // message is rendered as the intro, with the structured invoice below it —
        // see renderInvoiceEmail in server/emailTemplates.ts.
        const invBizSettings = await storage.getBusinessSettings();
        const invIdentity = getBusinessIdentity(invBizSettings);
        const invBrand = getBrandColors(invBizSettings);

        const templateLineItems = (lineItems && lineItems.length > 0)
          ? lineItems.map((item: any) => {
              const itemTotal = item.total || item.amount;
              const total = typeof itemTotal === 'string' ? parseFloat(itemTotal) : (itemTotal || 0);
              return { description: item.description || '', quantity: item.quantity || 1, price: total };
            })
          : [{ description: invoiceDetails.notes || invoiceDetails.jobTitle || job?.title || 'Service', quantity: 1, price: subtotal }];

        const dueDateText = invoiceDetails.dueDate
          ? new Date(invoiceDetails.dueDate).toLocaleDateString('en-NZ', { day: '2-digit', month: 'short', year: 'numeric' })
          : new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toLocaleDateString('en-NZ', { day: '2-digit', month: 'short', year: 'numeric' });

        // Customer-facing link is always the app domain (CLAUDE.md), regardless of tenant.
        const onlineInvoiceUrl = invoiceDetails?.id
          ? `${APP_URL}/invoice/${invoiceDetails.id}/view`
          : APP_URL;

        // Per-invoice billing-name override (saved on the invoice) beats the job-level
        // billingNameOverride so "edit for this invoice only" sticks in the email too.
        const invCustomerName = invoiceDetails?.contactName || job?.billingNameOverride || customer?.name || 'there';

        // Review ask riding along with the invoice. Reuses the job's existing
        // review-request token (re-sent invoices don't mint new ones); otherwise
        // creates one marked sent-via-email. Failure here never blocks the invoice.
        let invoiceReviewUrl: string | undefined;
        try {
          if (job?.id && job?.customerId) {
            let reviewReq = await storage.getLatestReviewRequestForJob(job.id);
            if (!reviewReq) {
              const reviewToken = require('crypto').randomBytes(32).toString('hex');
              reviewReq = await storage.createReviewRequest({
                jobId: job.id,
                customerId: job.customerId,
                token: reviewToken,
                status: 'sent',
                sentAt: new Date(),
                sentBy: req.session.employeeId || 'System',
                sentVia: 'email',
                customerName: invCustomerName,
                customerEmail: to || customer?.email || null,
                jobNumber: job.jobNumber ? String(job.jobNumber) : null,
                jobAddress: job.address || null,
              });
            }
            if (reviewReq?.token) invoiceReviewUrl = `${APP_URL}/review/${reviewReq.token}`;
          }
        } catch (reviewErr) {
          console.warn('Invoice review link skipped:', reviewErr);
        }

        invoiceHtml = renderInvoiceEmail({
          customerName: invCustomerName,
          intro: emailBody,
          invoiceLabel: invoiceDetails.invoiceNumber ? `Invoice #${invoiceDetails.invoiceNumber}` : 'Invoice',
          dueDateText,
          workAddress: invoiceDetails.address || job?.address || undefined,
          lineItems: templateLineItems,
          subtotal,
          gst: gstAmount,
          total: totalAmount,
          paidAmount: 0,
          balanceDue: totalAmount,
          ctaUrl: onlineInvoiceUrl,
          ctaText: 'View & pay invoice online',
          bank: {
            accountName: invBizSettings?.bankAccountName || undefined,
            accountNumber: invBizSettings?.bankAccountNumber || undefined,
            reference: invoiceDetails.invoiceNumber ? `Invoice ${invoiceDetails.invoiceNumber}` : undefined,
          },
          company: {
            name: invIdentity.name,
            tagline: invIdentity.tagline,
            address: invIdentity.address,
            phone: invIdentity.phone,
            email: invIdentity.email,
            website: invBizSettings?.businessWebsite || undefined,
            gstNumber: invIdentity.gstNumber,
          },
          brand: invBrand,
          reviewUrl: invoiceReviewUrl,
        });
      }
      
      // Prepare email content with any necessary formatting
      // When an invoice is present, renderInvoiceEmail already wraps the composed
      // message (intro) + the structured invoice in one branded layout, so use it as
      // the whole body. Otherwise fall back to the plain formatted message.
      let emailHtml = (invoice || validatedInvoiceData)
        ? invoiceHtml
        : emailBody.replace(/\n/g, '<br>').replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\*(.*?)\*/g, '<em>$1</em>');
      
      // If no invoice was found via invoiceId but the client explicitly attached an invoice,
      // fetch it from storage so the PDF gets generated
      if (!invoice && !validatedInvoiceData && Array.isArray(attachments)) {
        const invoiceAttachment = attachments.find((a: any) => a.type === 'invoice' && a.id);
        if (invoiceAttachment) {
          try {
            invoice = await storage.getInvoice(invoiceAttachment.id);
            console.log(`📄 Resolved invoice from client attachments array: ${invoiceAttachment.id}`);
          } catch (err) {
            console.warn('Could not fetch invoice from client attachments array:', err);
          }
        }
      }

      // Process attachments (logo + photos + invoice PDF)
      const emailAttachments = [];
      
      // Generate and attach invoice PDF using the shared helper.
      // Microsoft recipients: skip the attachment entirely — Microsoft's filters strip PDFs from
      // this sender's reputation profile even when no inline CIDs are present. The HTML body below
      // injects a "Download Invoice (PDF)" button pointing at the public PDF endpoint instead.
      if ((invoice || validatedInvoiceData) && !recipientIsMicrosoft) {
        try {
          const invoiceForPdf = invoice || validatedInvoiceData;
          console.log(`📄 Generating invoice PDF for email (invoice #${invoiceForPdf.invoiceNumber}, lineItems: ${(invoiceForPdf.items || invoiceForPdf.lineItems || []).length})`);
          // Fetch invoice template for block-config-aware PDF rendering
          const invoiceTemplateRows = await db.select().from(documentTemplates)
            .where(eq(documentTemplates.type, 'invoice')).limit(1);
          const invoiceTemplate = invoiceTemplateRows[0] || null;
          const pdfPhotos = Array.isArray(selectedPhotos)
            ? selectedPhotos.filter(isSupportedPhotoUrl)
            : [];
          const pdfBuffer = await generateInvoicePDFBuffer(invoiceForPdf, job, customer, invoiceTemplate, pdfPhotos);
          emailAttachments.push({
            content: pdfBuffer.toString('base64'),
            filename: `Invoice-${invoiceForPdf.invoiceNumber || 'unknown'}.pdf`,
            type: 'application/pdf',
            disposition: 'attachment'
          });
          console.log(`📄 Invoice PDF attached: Invoice-${invoiceForPdf.invoiceNumber}.pdf (${Math.round(pdfBuffer.length / 1024)}KB)`);
        } catch (pdfError) {
          console.error('Error generating invoice PDF for email:', pdfError);
        }
      } else if ((invoice || validatedInvoiceData) && recipientIsMicrosoft) {
        const invNum = (invoice || validatedInvoiceData)?.invoiceNumber;
        console.log(`📄 Skipped PDF attachment for Microsoft-hosted recipient ${to} (Invoice #${invNum}) — delivering via download link`);
      }


      // The branded invoice email uses a text wordmark in the per-business brand
      // colour (renderInvoiceEmail), not an inline logo image — so no logo CID
      // attachment is needed here. The PDF (above) renders its own logo.

      // Embed photos as true inline CID attachments — no external URL dependency.
      // Photos are fetched from object storage server-side and embedded directly in the
      // email body, so they display in every email client regardless of auth or server state.
      //
      // EXCEPTION — Microsoft-hosted addresses (Hotmail / Outlook.com / Live / MSN):
      // Microsoft's spam filters silently strip PDF attachments from emails that contain
      // many CID-embedded images. To ensure the PDF lands in the inbox, we skip the photo
      // CID loop for these recipients and show a text link to the invoice page instead.
      // Gmail and all other providers are unaffected.
      let photoGalleryHtml = '';
      let embeddedPhotoCount = 0;

      if (selectedPhotos && selectedPhotos.length > 0) {
        if (recipientIsMicrosoft) {
          // Skip CID embedding for Microsoft recipients so the PDF is not stripped.
          // No fallback text needed — the pdfDownloadBanner above already links the
          // customer to the online invoice page where the photos render in-browser.
          const photoCount = selectedPhotos.filter(isSupportedPhotoUrl).length;
          console.log(`📸 Skipped ${photoCount} photo CID attachment(s) for Microsoft-hosted recipient ${to} — using single online-view banner`);
        } else {
          const photoStorage = new PhotoStorageService();
          const photoHtmlParts: string[] = [];

          console.log(`📸 Embedding ${selectedPhotos.length} photo(s) as inline CID attachments...`);

          for (let i = 0; i < selectedPhotos.length; i++) {
            const photoUrl = selectedPhotos[i];
            if (!isSupportedPhotoUrl(photoUrl)) continue;

            const fileName = path.basename(photoUrl);
            const cid = `job-photo-${i}`;

            // For GCS-backed photos, try the thumbnail first (small, fast); fall
            // back to the original if missing. For local /photos/ paths, just
            // load the file directly.
            let photoData: { buffer: Buffer; contentType: string } | null = null;
            if (photoUrl.startsWith('/objects/photos/')) {
              const thumbFileName = `thumb_${fileName.replace(/\.(jpg|jpeg|png|heic|heif)$/i, '.webp')}`;
              const thumbPath = `/objects/photos/${thumbFileName}`;
              const thumb = await photoStorage.downloadPhotoBuffer(thumbPath);
              if (thumb?.buffer) {
                photoData = { buffer: thumb.buffer, contentType: thumb.contentType || 'image/webp' };
              }
            }
            if (!photoData) {
              photoData = await loadPhotoBytesForAttachment(photoUrl, photoStorage);
            }

            if (photoData && photoData.buffer) {
              // Attach as inline CID image — email client renders it directly in the body
              emailAttachments.push({
                content: photoData.buffer.toString('base64'),
                filename: fileName,
                type: photoData.contentType || 'image/jpeg',
                content_id: cid
              });
              photoHtmlParts.push(`
                <div style="display: inline-block; margin: 5px; vertical-align: top;">
                  <img src="cid:${cid}" alt="Job Photo ${i + 1}"
                    style="max-width: 200px; max-height: 200px; border-radius: 8px;
                           border: 1px solid #ddd; display: block;" />
                </div>
              `);
              embeddedPhotoCount++;
              console.log(`📷 Photo ${i + 1} embedded as CID "${cid}" (${Math.round(photoData.buffer.length / 1024)}KB, ${photoData.contentType})`);
            } else {
              console.warn(`⚠️ Could not fetch photo buffer for ${photoUrl} — skipping`);
            }
          }

          if (photoHtmlParts.length > 0) {
            photoGalleryHtml = `
              <div style="margin-top: 20px; padding: 15px; background-color: #f9f9f9;
                          border-radius: 8px; font-family: Arial, sans-serif;">
                <p style="margin: 0 0 10px 0; font-weight: bold; color: #333;">
                  Photos (${embeddedPhotoCount}):
                </p>
                <div>
                  ${photoHtmlParts.join('')}
                </div>
              </div>
            `;
          }
        }
      }
      
      // Append photo gallery to email HTML if we have photos
      if (photoGalleryHtml) {
        emailHtml = emailHtml + photoGalleryHtml;
      }
      
      // Log final attachment summary before sending
      console.log(`📧 Preparing to send email with ${emailAttachments.length} server-side attachment(s):`, 
        emailAttachments.map(a => ({ filename: (a as any).filename, type: (a as any).type, contentKB: Math.round(((a as any).content?.length || 0) / 1024 * 0.75) })));

      // Send email using the emailService
      // Pass jobNumber so Cloudflare Email Routing forwards replies to job-specific address
      const emailResult = await emailService.sendEmail({
        to: to,
        subject: subject,
        text: emailBody,
        html: emailHtml,
        jobNumber: job?.jobNumber, // Reply-to will be job-{number}@jobs.treemarkables.co.nz
        ...(emailAttachments.length > 0 && { attachments: emailAttachments })
      });

      if (emailResult.success) {
        // Log email activity (you could store this in database for audit trail)
        console.log(`📧 Email sent to ${to} for job ${job?.jobNumber || jobId}${
          embeddedPhotoCount > 0 ? ` with ${embeddedPhotoCount} embedded photo(s)` : ''
        }${emailResult.messageId ? ` (Message ID: ${emailResult.messageId})` : ''}`);

        // Create job diary entry for the email
        if (jobId) {
          try {
            // Custom email endpoint NEVER creates "Quote Sent" or "Proposal Sent" entries
            // Those are only created by dedicated /api/proposals/:id/send-email endpoint
            const diaryDescription = `Email sent to ${to}${cc ? ` (CC: ${cc})` : ''}${
              embeddedPhotoCount > 0 ? `\n\nPhotos: ${embeddedPhotoCount} photo(s) embedded` : ''
            }\n\nMessage:\n${emailBody}`;
            
            await storage.createJobDiaryEntry({
              jobId: jobId,
              entryType: 'email',
              title: `Email sent: ${subject}`,
              description: diaryDescription,
              authorName: 'System',
              authorRole: 'system',
              tags: ['communication', 'email', invoiceId ? 'invoice' : '', quoteId ? 'quote' : ''].filter(Boolean),
              isPrivate: false,
              metadata: {
                emailAddress: to,
                quoteId: quoteId || undefined,
                sendgridMessageId: emailResult.messageId
              }
            });
            
            // Update job's lastActivityAt to trigger activity indicator and sorting
            await storage.updateJob(jobId, { lastActivityAt: new Date() });
            console.log(`📝 Email logged to job diary for job ${job?.jobNumber || jobId}`);
          } catch (diaryError) {
            console.error('Error creating job diary entry for email:', diaryError);
          }
        }
        
        res.json({ 
          success: true, 
          message: `Email sent successfully${
            embeddedPhotoCount > 0 ? ` with ${embeddedPhotoCount} photo(s)` : ''
          }` 
        });
      } else {
        console.error('📧 Email send failed:', emailResult.error || 'Unknown error');
        res.status(500).json({ 
          success: false, 
          message: emailResult.error || 'Failed to send email' 
        });
      }

    } catch (error: any) {
      console.error('❌ Error sending invoice email:', error);
      console.error('❌ Error details:', {
        message: error.message,
        stack: error.stack,
        code: error.code,
        response: error.response?.body || error.response
      });
      res.status(500).json({ 
        success: false, 
        message: error.message || 'Error sending email'
      });
    }
  });

  // Send SMS invoice
  app.post('/api/sms/send', async (req: Request, res: Response) => {
    try {
      const { phone, message, jobId, customerId, invoiceId } = req.body;
      
      console.log(`📱 Processing SMS to ${phone}`);
      
      // Validate required fields
      if (!phone || !message) {
        return res.status(400).json({ 
          success: false, 
          message: 'Phone number and message are required' 
        });
      }

      // Validate message length (multi-part SMS supported, max 459 chars = 3 segments)
      if (message.length > 459) {
        return res.status(400).json({ 
          success: false, 
          message: 'SMS message must be 459 characters or less (3 SMS segments)' 
        });
      }

      // Get related data for SMS context
      let job, customer, invoice;
      if (jobId) {
        job = await storage.getJob(jobId);
      }
      if (customerId) {
        customer = await storage.getCustomer(customerId);
      }
      if (invoiceId) {
        invoice = await storage.getInvoice(invoiceId);
      }

      // Send SMS using SMS service
      const success = await smsService.sendSMS({
        to: phone,
        message: message
      });

      if (!success) {
        throw new Error('SMS service failed to send message');
      }

      // Log successful SMS for audit trail
      console.log(`📱 SMS sent successfully to ${phone}`);
      console.log(`📱 Message: ${message}`);
      
      // Save phone number to job contact and customer so reply matching works
      if (jobId && job && !job.jobContactPhone) {
        try {
          await storage.updateJob(jobId, { jobContactPhone: phone });
          console.log(`📱 Saved phone ${phone} to job ${jobId} contact`);
        } catch (e) { console.warn('Failed to save phone to job:', e); }
      }
      if (customerId && customer && !customer.phone && !customer.mobile) {
        try {
          await storage.updateCustomer(customerId, { phone: phone });
          console.log(`📱 Saved phone ${phone} to customer ${customerId}`);
        } catch (e) { console.warn('Failed to save phone to customer:', e); }
      }
      
      // Store communication record if customer/job context available
      if (customerId || jobId) {
        try {
          await storage.createCommunication({
            customerId: customerId || job?.customerId,
            jobId: jobId,
            type: 'sms',
            direction: 'outbound',
            subject: 'Invoice SMS',
            content: message,
            phoneNumber: phone,
            timestamp: new Date().toISOString(),
            status: 'sent'
          });
        } catch (commError) {
          console.warn('Failed to log SMS communication:', commError);
          // Don't fail the SMS send if logging fails
        }

        // Also add to job diary if jobId exists
        if (jobId) {
          try {
            await storage.createJobDiaryEntry({
              jobId: jobId,
              entryType: 'sms',
              title: '📱 SMS Sent',
              description: `SMS sent to ${customer?.name || phone}\n\nMessage: ${message}`,
              authorName: 'System',
              authorRole: 'system',
              tags: ['sms', 'communication'],
              metadata: { phoneNumber: phone }
            });
            console.log(`✅ SMS diary entry created for job ${jobId}`);
            
            // Update job's lastActivityAt to trigger activity indicator and sorting
            console.log(`📌 Updating lastActivityAt for job ${jobId}...`);
            await storage.updateJob(jobId, { lastActivityAt: new Date() });
            console.log(`✅ Job ${jobId} lastActivityAt updated - should move to top with activity indicator`);
          } catch (diaryError) {
            console.error('❌ Failed to log SMS to job diary:', diaryError);
          }
        }
      }
      
      res.json({ 
        success: true, 
        message: 'SMS sent successfully',
        phone: phone
      });
      
    } catch (error: any) {
      console.error('❌ SMS sending failed:', error);
      res.status(500).json({ 
        success: false, 
        message: error.message || 'Failed to send SMS' 
      });
    }
  });

  // Manual test endpoint to check SMS replies (for debugging)
  app.get('/api/sms/test-replies', async (req: Request, res: Response) => {
    try {
      const { retrieveSMSReplies } = await import('./services/smsEveryoneClient');
      const replies = await retrieveSMSReplies();
      
      res.json({
        success: true,
        count: replies.length,
        replies: replies,
        message: replies.length > 0 ? `Found ${replies.length} replies` : 'No SMS replies found'
      });
    } catch (error: any) {
      console.error('Error testing SMS replies:', error);
      res.status(500).json({
        success: false,
        message: error.message || 'Failed to fetch SMS replies',
        error: error.toString()
      });
    }
  });

  // Twilio webhook for incoming SMS replies
  app.post('/api/webhooks/sms', async (req: Request, res: Response) => {
    try {
      // Validate Twilio signature
      if (!validateTwilioSignature(req)) {
        console.error('❌ Invalid Twilio signature for SMS webhook');
        return res.status(403).send('Forbidden');
      }

      const { From, To, Body, MessageSid } = req.body;
      
      console.log(`📱 Incoming SMS from ${From}: ${Body}`);
      
      // Normalize incoming phone number for comparison
      const normalizePhone = (phone: string): string => {
        const cleaned = phone.replace(/\D/g, '');
        if (cleaned.startsWith('64')) return `+${cleaned}`;
        if (cleaned.startsWith('0')) return `+64${cleaned.substring(1)}`;
        if (cleaned.length === 9 || cleaned.length === 10) return `+64${cleaned}`;
        return phone;
      };
      
      const normalizedFrom = normalizePhone(From);
      console.log(`📱 Normalized incoming phone: ${From} -> ${normalizedFrom}`);
      
      // Resolve which tenant owns the number that RECEIVED this SMS (To). Without it
      // the lookup below scans EVERY tenant's customers and would attach an inbound SMS
      // to another business's job whenever two tenants have a customer sharing a phone
      // number. Unmapped number → undefined → unchanged single-tenant behaviour.
      // Mirrors the twilio-voice webhook + smsReplyPoller tenant scoping.
      const inboundBizId = await resolveBusinessIdByChannel('phone', String(To || ''));
      if (inboundBizId) console.log(`🏢 Inbound SMS line ${To} resolved to business ${inboundBizId}`);

      // Find customer by phone number — scoped to the receiving tenant when known.
      const allCustomers = await storage.getAllCustomers();
      const customers = inboundBizId
        ? allCustomers.filter(c => c.businessId === inboundBizId)
        : allCustomers;
      const customer = customers.find(c => {
        if (!c.phone) return false;
        const normalizedCustomerPhone = normalizePhone(c.phone);
        console.log(`📱 Comparing: ${normalizedFrom} === ${normalizedCustomerPhone} (customer: ${c.name})`);
        return normalizedCustomerPhone === normalizedFrom;
      });
      
      if (customer) {
        console.log(`✅ Found customer: ${customer.name} (${customer.id})`);
        
        // Get most recent job for this customer
        const jobs = await storage.getJobsByCustomer(customer.id);
        const recentJob = jobs[0]; // Most recent job

        // Stamp every write below (diary, job/customer updates, notifications) to the
        // resolved tenant. runWithBusiness doesn't scope READS (the customer match above
        // is already tenant-filtered) — it pins the write-path businessId so these rows
        // land under the right tenant instead of the column default (Treemarkables).
        await runWithBusiness(inboundBizId ?? customer.businessId ?? undefined, async () => {
        // Log to job diary if job exists
        if (recentJob) {
          console.log(`📝 Logging to job #${recentJob.jobNumber} diary...`);
          await storage.createJobDiaryEntry({
            jobId: recentJob.id,
            entryType: 'sms',
            title: '📱 Customer SMS Reply',
            description: `SMS received from ${customer.name} (${From})\n\nMessage: ${Body}`,
            authorName: customer.name,
            authorRole: 'customer',
            tags: ['sms', 'communication', 'customer-reply']
          });
          
          // Extract email address from SMS body if present
          const emailMatch = Body.match(/\b[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Z|a-z]{2,}\b/);
          if (emailMatch) {
            const extractedEmail = emailMatch[0].toLowerCase();
            console.log(`📧 Extracted email from SMS: ${extractedEmail}`);
            const jobUpdates: any = {};
            if (!recentJob.jobContactEmail) {
              jobUpdates.jobContactEmail = extractedEmail;
            }
            // Also update customer email if not set
            if (!customer.email) {
              await storage.updateCustomer(customer.id, { email: extractedEmail });
              console.log(`📧 Updated customer ${customer.name} email to ${extractedEmail}`);
            }
            if (Object.keys(jobUpdates).length > 0) {
              await storage.updateJob(recentJob.id, jobUpdates);
              console.log(`📧 Updated job #${recentJob.jobNumber} contact email to ${extractedEmail}`);
            }
          }
          
          // Extract full name from SMS body if present (e.g. "Full name is Christopher Garry Bone")
          const nameMatch = Body.match(/(?:full\s*name\s*(?:is|:)\s*)([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)/i);
          if (nameMatch) {
            const fullName = nameMatch[1].trim();
            const nameParts = fullName.split(/\s+/);
            const firstName = nameParts[0];
            const lastName = nameParts.slice(1).join(' ');
            console.log(`👤 Extracted name from SMS: ${firstName} ${lastName}`);
            const jobNameUpdates: any = {};
            if (!recentJob.jobContactFirstName && firstName) {
              jobNameUpdates.jobContactFirstName = firstName;
            }
            if (!recentJob.jobContactLastName && lastName) {
              jobNameUpdates.jobContactLastName = lastName;
            }
            if (Object.keys(jobNameUpdates).length > 0) {
              await storage.updateJob(recentJob.id, jobNameUpdates);
              console.log(`👤 Updated job #${recentJob.jobNumber} contact name to ${firstName} ${lastName}`);
            }
          }
          
          // Update job's lastActivityAt to trigger activity indicator and sorting
          await storage.updateJob(recentJob.id, { lastActivityAt: new Date() });
          console.log(`✅ SMS logged to job #${recentJob.jobNumber} diary`);

          // Push notification to admins about SMS reply
          try {
            await notificationHelper.notifyCustomerSmsReply(
              customer.name,
              Body,
              recentJob.jobNumber?.toString()
            );
          } catch (pushErr) {
            console.error('Error sending SMS reply push notification:', pushErr);
          }

          // Detect reschedule intent → alert dispatcher to re-propose a time slot
          const rescheduleKeywords = /can.?t make|not available|doesn.?t suit|time doesn.?t|different time|reschedule|can we change|change the time|won.?t work|another time|change appointment/i;
          const isReschedule = rescheduleKeywords.test(Body);
          if (isReschedule) {
            await storage.createNotification({
              title: `Reschedule requested — Job #${recentJob.jobNumber}`,
              message: `Customer ${customer.name} may be requesting a new time slot for Job #${recentJob.jobNumber} via SMS.`,
              type: 'reschedule_request',
              priority: 'high',
              isRead: false,
              actionUrl: '/dispatch',
              jobId: recentJob.id,
            }).catch(() => { /* non-critical */ });
          }

          // Detect confirmation intent. Only auto-flip customerConfirmed when we have
          // reasonable proof we actually asked: a pending_outbound_messages row was
          // created for this job within the last 14 days. Otherwise raise a notification
          // for manual review.
          const confirmKeywords = /\b(yes|yep|yeah|yup|confirm(ed|ing)?|all good|sounds good|that works|works for me|sg|ok(ay)?|thanks(\s|!|$)|thank you|perfect|great|cheers|sweet|awesome)\b/i;
          const isConfirmation = !isReschedule && confirmKeywords.test(Body);
          if (
            isConfirmation &&
            recentJob.status === 'work_order' &&
            !recentJob.customerConfirmed
          ) {
            try {
              const fourteenDaysAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;
              const allPending = await storage.getPendingOutboundMessages();
              const hasRecentOutbound = allPending.some(
                (m) =>
                  m.jobId === recentJob.id &&
                  m.createdAt &&
                  new Date(m.createdAt).getTime() >= fourteenDaysAgo,
              );
              if (hasRecentOutbound) {
                await storage.updateJob(recentJob.id, {
                  customerConfirmed: true,
                  customerConfirmedAt: new Date(),
                  customerConfirmationMethod: 'sms',
                } as any);
                await storage.createJobDiaryEntry({
                  jobId: recentJob.id,
                  entryType: 'milestone',
                  title: 'Customer confirmed scheduled date',
                  description: `Customer ${customer.name} confirmed the scheduled date/time via SMS reply: "${Body}"`,
                  authorName: customer.name,
                  authorRole: 'customer',
                  tags: ['customer-confirmation', 'sms'],
                  metadata: { source: 'sms', from: From },
                });
                await storage.createNotification({
                  title: `Customer confirmed Job #${recentJob.jobNumber}`,
                  message: `${customer.name} confirmed the scheduled date for Job #${recentJob.jobNumber} via SMS.`,
                  type: 'customer_confirmation',
                  priority: 'medium',
                  isRead: false,
                  jobId: recentJob.id,
                }).catch(() => { /* non-critical */ });
                console.log(`✅ Auto-confirmed Job #${recentJob.jobNumber} from SMS reply`);
              } else {
                await storage.createNotification({
                  title: `Possible confirmation — Job #${recentJob.jobNumber}`,
                  message: `${customer.name} replied with confirmation-style wording but no recent booking request was on file. Review and tick manually if appropriate.`,
                  type: 'customer_confirmation_review',
                  priority: 'low',
                  isRead: false,
                  jobId: recentJob.id,
                }).catch(() => { /* non-critical */ });
              }
            } catch (confirmErr) {
              console.error('Error processing SMS confirmation:', confirmErr);
            }
          }
        } else {
          console.log(`⚠️ No jobs found for customer ${customer.name}`);
        }
        }); // runWithBusiness(inboundBizId)
      } else {
        console.warn(`📱 Received SMS from unknown number: ${From}`);
      }
      
      // Respond to Twilio with TwiML (required)
      broadcast(['/api/jobs', '/api/conversations', '/api/notifications/summary']);
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
      
    } catch (error: any) {
      console.error('❌ SMS webhook error:', error);
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
    }
  });

  // ----------------------------------------
  // TWILIO LIVE CALL RECORDING
  // Caller rings owner's personal mobile → carrier unconditionally forwards here →
  // Twilio dials OWNER_PHONE_NUMBER while recording → on no-answer, takes voicemail.
  // Configure in Twilio console: "A CALL COMES IN" → Webhook → /api/webhooks/twilio-answer
  // ----------------------------------------

  // Serve recordings from persistent Object Storage
  app.get('/api/recordings/:filename', async (req: Request, res: Response) => {
    try {
      const privateDir = (process.env.PRIVATE_OBJECT_DIR || '').trim();
      if (!privateDir) {
        return res.status(500).json({ error: 'Object storage not configured' });
      }
      const filename = req.params.filename;
      if (!filename || filename.includes('..')) {
        return res.status(400).json({ error: 'Invalid filename' });
      }
      const objectPath = `${privateDir}/recordings/${filename}`;
      const parts = objectPath.replace(/^\//, '').split('/');
      const bucketName = parts[0];
      const objectName = parts.slice(1).join('/');
      const [content] = await objectStorageClient.bucket(bucketName).file(objectName).download();
      res.setHeader('Content-Type', 'audio/mpeg');
      res.setHeader('Accept-Ranges', 'bytes');
      res.send(content);
    } catch (error: any) {
      console.error('❌ Error serving recording:', error);
      res.status(404).json({ error: 'Recording not found' });
    }
  });

  // Generate a Twilio Access Token for the iOS Capacitor app (Twilio Voice SDK)
  // Requires TWILIO_API_KEY (SK...) and TWILIO_API_SECRET to be set as secrets.
  // Create them at: Twilio Console → Account → API Keys & Tokens → Create API Key (Standard).
  app.post('/api/twilio/token', async (req: Request, res: Response) => {
    try {
      if (!req.session.employeeId) {
        return res.status(401).json({ success: false, message: 'Not authenticated' });
      }
      const accountSid = process.env.TWILIO_ACCOUNT_SID;
      const apiKey = process.env.TWILIO_API_KEY;
      const apiSecret = process.env.TWILIO_API_SECRET;
      if (!accountSid || !apiKey || !apiSecret) {
        return res.status(503).json({
          success: false,
          message: 'Twilio API Key not configured. Set TWILIO_API_KEY and TWILIO_API_SECRET secrets.',
        });
      }
      // Identity isolation: only admins (the owner) get the shared inbound
      // identity that the answer webhook dials. Other employees get a
      // per-employee identity so their devices don't ring on inbound customer
      // calls — twilio-answer only <Dial>s the owner identity.
      const requestingEmployee = await storage.getEmployee(req.session.employeeId);
      const ownerIdentity = process.env.TWILIO_CLIENT_IDENTITY || 'treemarkables-owner';
      const isAdmin = requestingEmployee?.role === 'admin';
      const clientIdentity = isAdmin
        ? ownerIdentity
        : `treemarkables-emp-${req.session.employeeId}`;
      const twimlAppSid = process.env.TWILIO_TWIML_APP_SID;
      // Platform-aware push credential. iOS uses an APNs VoIP push credential;
      // Android uses an FCM push credential (a different SID registered in the
      // Twilio Console). The client tells us which platform it is via the body;
      // default to iOS for backward compatibility with older app builds.
      const platform = (typeof req.body?.platform === 'string'
        ? req.body.platform.toLowerCase()
        : 'ios');
      const pushCredentialSid = platform === 'android'
        ? (process.env.TWILIO_PUSH_CREDENTIAL_SID_ANDROID || process.env.TWILIO_PUSH_CREDENTIAL_SID)
        : process.env.TWILIO_PUSH_CREDENTIAL_SID;
      const { AccessToken } = twilio.jwt;
      const { VoiceGrant } = AccessToken;
      const voiceGrant = new VoiceGrant({
        incomingAllow: true,
        ...(twimlAppSid ? { outgoingApplicationSid: twimlAppSid } : {}),
        ...(pushCredentialSid ? { pushCredentialSid } : {}),
      });
      const accessToken = new AccessToken(accountSid, apiKey, apiSecret, {
        identity: clientIdentity,
        ttl: 3600,
      });
      accessToken.addGrant(voiceGrant);
      if (!twimlAppSid) {
        console.warn('⚠️  TWILIO_TWIML_APP_SID not set — outgoing calls from the iOS app will not work. Create a TwiML App in the Twilio Console and set this secret.');
      }
      if (!pushCredentialSid) {
        const credEnv = platform === 'android' ? 'TWILIO_PUSH_CREDENTIAL_SID_ANDROID' : 'TWILIO_PUSH_CREDENTIAL_SID';
        console.warn(`⚠️  ${credEnv} not set — incoming call push notifications to the ${platform} app will not work. Create a Push Credential at Twilio Console → Voice → Push Credentials (${platform === 'android' ? 'FCM' : 'APNs'}) and set this secret.`);
      }
      console.log(`🔑 Twilio access token issued for identity: ${clientIdentity} (platform: ${platform}, outgoing: ${twimlAppSid ? 'enabled' : 'disabled'}, push: ${pushCredentialSid ? 'enabled' : 'disabled'})`);
      return res.json({ success: true, token: accessToken.toJwt(), identity: clientIdentity, platform, outgoingEnabled: !!twimlAppSid, pushEnabled: !!pushCredentialSid });
    } catch (error: any) {
      console.error('❌ Error generating Twilio token:', error);
      return res.status(500).json({ success: false, message: 'Failed to generate token' });
    }
  });

  // Shared XML-text escaper for TwiML built in the answer/IVR webhooks.
  const escapeTwimlXml = (s: string) =>
    s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');

  // Builds the inner TwiML verbs (everything between <Response> and </Response>)
  // for the original "ring the iOS app + owner's phone simultaneously, record,
  // voicemail on no-answer" flow. Extracted verbatim from the answer webhook so
  // the IVR menu can fall through to the exact same behaviour on timeout /
  // press-2, and so the voice-agent failure fallback (?mode=dial) reproduces
  // today's flow byte-for-byte.
  const buildDialJulesTwimlBody = async (req: Request): Promise<string> => {
    const ownerPhone = process.env.OWNER_PHONE_NUMBER || process.env.HERO_PHONE_NUMBER;
    const clientIdentity = process.env.TWILIO_CLIENT_IDENTITY || 'treemarkables-owner';
    const hasClient = !!(process.env.TWILIO_API_KEY && process.env.TWILIO_API_SECRET);

    // Must have at least one destination — Client app OR phone number
    if (!hasClient && !ownerPhone) {
      console.error('❌ No call destination configured (set TWILIO_API_KEY+TWILIO_API_SECRET or OWNER_PHONE_NUMBER)');
      return `  <Say voice="alice">Sorry, we are unable to take your call right now. Please try again later.</Say>
`;
    }

    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const baseUrl = `${protocol}://${host}`;

    // Twilio's recording-status callback (fired when the call's recording
    // completes) does NOT include From / ForwardedFrom / To — only the initial
    // call webhook does. We need the caller's number to attribute the recording
    // to the right call record in our DB, so capture it here and pass it
    // through as a query param on the recordingStatusCallback URL.
    //
    // From = the original caller (CLI is preserved through carrier diversion).
    // ForwardedFrom = the line that DID the forwarding — i.e. the owner's own
    // mobile when a customer dials the advertised number and the carrier
    // diverts here. Preferring ForwardedFrom made every forwarded call look
    // like the owner's number (and caller-ID matched whichever customer record
    // happened to hold it). Only fall back to it when From is withheld.
    const inboundFrom = String(req.body?.From || req.body?.ForwardedFrom || '');
    const inboundTo = String(req.body?.To || '');
    // The URL is embedded in an XML attribute, so any `&` between query params
    // must be escaped as `&amp;` or Twilio fails to parse the TwiML.
    const recordingCallbackUrl =
      `${baseUrl}/api/webhooks/twilio-voice?callerFrom=${encodeURIComponent(inboundFrom)}&amp;calledTo=${encodeURIComponent(inboundTo)}`;

    // Shared XML-attribute escaper (used for caller name + disclosure below).
    const escapeXml = (s: string) =>
      s
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');

    // Caller ID enrichment: look up the inbound number against our customers
    // so CallKit can show the customer's name instead of a raw number. The
    // name is passed to the iOS Voice SDK as a <Parameter> on <Client>, which
    // the app reads from callInvite.customParameters["callerName"].
    //
    // When there's no customer match, fall through to showing the actual
    // phone number (with an " · Inflow" suffix so it's clear which app rang).
    // The iOS plugin's generic "Inflow Customer" fallback hid the number
    // behind a tap — sending the number as the caller name surfaces it on
    // the lock screen directly.
    const formatCallerNumber = (raw: string): string => {
      const digits = raw.replace(/\D/g, '');
      // NZ mobile in E.164: +64 2X XXX XXXX(X)
      if (digits.startsWith('64') && digits.length >= 11 && digits[2] === '2') {
        const rest = digits.slice(2);
        return `+64 ${rest.slice(0, 2)} ${rest.slice(2, 5)} ${rest.slice(5)}`;
      }
      // NZ landline in E.164: +64 X XXX XXXX
      if (digits.startsWith('64') && digits.length === 10) {
        const rest = digits.slice(2);
        return `+64 ${rest.slice(0, 1)} ${rest.slice(1, 4)} ${rest.slice(4)}`;
      }
      // Local NZ mobile: 02X XXX XXXX(X)
      if (digits.startsWith('02') && digits.length >= 10) {
        return `${digits.slice(0, 3)} ${digits.slice(3, 6)} ${digits.slice(6)}`;
      }
      // Local NZ landline: 0X XXX XXXX
      if (digits.startsWith('0') && digits.length === 9) {
        return `${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5)}`;
      }
      // Unknown shape — show whatever Twilio gave us verbatim.
      return raw;
    };

    let callerName = '';
    if (inboundFrom) {
      try {
        const key = inboundFrom.replace(/\D/g, '').slice(-8);
        if (key) {
          // Indexed/DB-side lookup rather than loading the entire customer
          // table on every inbound call — keeps the answer webhook fast so
          // the caller reaches the greeting sooner (less pre-answer ringback).
          // Owner-context path: scope the lookup to the tenant that owns the
          // dialled line, so a last-8 collision can't surface another tenant's
          // customer NAME on the caller ID. Unmapped line → undefined → prior
          // single-tenant behaviour. findCustomerByPhoneLast8 self-scopes to
          // the ambient businessId set here.
          const inboundBizId = await resolveBusinessIdByChannel('phone', inboundTo);
          const match = await runWithBusiness(inboundBizId, () => storage.findCustomerByPhoneLast8(key));
          if (match?.name) callerName = String(match.name);
        }
      } catch (lookupErr) {
        console.error('Caller-name lookup failed:', lookupErr);
      }
      if (!callerName) {
        callerName = `${formatCallerNumber(inboundFrom)} · Inflow`;
      }
    }

    // Build the list of Dial targets. When we have a caller name, the <Client>
    // must use the <Identity> noun form so we can attach a <Parameter>.
    const clientTarget = hasClient
      ? callerName
        ? `    <Client>\n      <Identity>${clientIdentity}</Identity>\n      <Parameter name="callerName" value="${escapeXml(callerName)}"/>\n    </Client>`
        : `    <Client>${clientIdentity}</Client>`
      : '';
    const phoneTarget = ownerPhone ? `    <Number>${ownerPhone}</Number>` : '';

    // Optional recorded-call disclosure played to the CALLER before we ring
    // through. OFF by default — playing any audio before the agent picks up
    // forces Twilio to answer the line, which means the caller hears the
    // greeting instead of ringing, mistakes it for voicemail, and hangs up.
    // NZ Privacy Act is one-party consent, so the owner recording their own
    // calls doesn't legally need to disclose to the caller. To re-enable, set
    // TWILIO_RECORDING_DISCLOSURE_URL (preferred — a recorded file) or
    // TWILIO_RECORDING_DISCLOSURE (TTS text). Either env var set to "off"
    // disables disclosure even if the other is configured.
    const disclosureUrl = (process.env.TWILIO_RECORDING_DISCLOSURE_URL || '').trim();
    const disclosureTextRaw = (process.env.TWILIO_RECORDING_DISCLOSURE || '').trim();
    let disclosureTwiml = '';
    const disclosureForcedOff =
      disclosureTextRaw.toLowerCase() === 'off' ||
      disclosureUrl.toLowerCase() === 'off';
    if (disclosureForcedOff) {
      disclosureTwiml = '';
    } else if (disclosureUrl) {
      disclosureTwiml = `  <Play>${escapeXml(disclosureUrl)}</Play>\n`;
    } else if (disclosureTextRaw) {
      disclosureTwiml = `  <Say voice="alice">${escapeXml(disclosureTextRaw)}</Say>\n`;
    }
    // If neither var is set, no leading audio — combined with answerOnBridge
    // on <Dial> below, the caller hears real phone ringback immediately, like
    // calling any normal phone, until the agent actually picks up.

    // Optional brief "we're connecting you" cue played to the CALLER *before*
    // the recorded-call disclosure. OFF by default — the owner's own recorded
    // greeting/disclosure already frames the call, and the robotic TTS line
    // ahead of it sounded jarring. To re-enable, set TWILIO_CONNECTING_PROMPT
    // to the text you want spoken (set it to "off" or leave it unset to keep
    // it silent).
    const connectingPromptRaw = (process.env.TWILIO_CONNECTING_PROMPT || '').trim();
    let connectingTwiml = '';
    if (connectingPromptRaw && connectingPromptRaw.toLowerCase() !== 'off') {
      connectingTwiml = `  <Say voice="alice">${escapeXml(connectingPromptRaw)}</Say>\n`;
    }

    console.log(`📞 Twilio answer webhook — client=${hasClient ? clientIdentity : 'off'}, phone=${ownerPhone || 'off'}, callerFrom=${inboundFrom || 'unknown'}, callerName=${callerName || '(unknown)'}, connecting=${connectingTwiml ? 'on' : 'off'}, disclosure=${disclosureTwiml ? 'on' : 'off'}`);

    return `${connectingTwiml}${disclosureTwiml}  <Dial
    record="record-from-answer"
    answerOnBridge="true"
    recordingStatusCallback="${recordingCallbackUrl}"
    recordingStatusCallbackEvent="completed"
    timeout="20"
    action="${baseUrl}/api/webhooks/twilio-no-answer"
  >
${clientTarget}
${phoneTarget}
  </Dial>
`;
  };

  // TwiML App Voice URL — fires when a logged-in Voice-SDK client (the web
  // dialer, or a future native outgoing flow) places an OUTGOING call via
  // device.connect({ params: { To } }). The TwiML App (TWILIO_TWIML_APP_SID)
  // must have "A CALL COMES IN" pointed at this URL — one-click setup via
  // POST /api/twilio/admin/configure-outgoing, verified by the diagnostic.
  app.post('/api/webhooks/twilio-outgoing', async (req: Request, res: Response) => {
    if (!validateTwilioSignature(req)) {
      console.error('❌ Invalid Twilio signature for outgoing webhook');
      return res.status(403).send('Forbidden');
    }
    res.type('text/xml');
    const say = (msg: string) =>
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="alice">${escapeTwimlXml(msg)}</Say>
</Response>`);

    // Only Voice-SDK clients (From=client:<identity>, minted by our own token
    // endpoint) may dial out. A PSTN leg that reaches this URL through a
    // console misconfiguration must not turn it into an open relay.
    const from = String(req.body?.From || '');
    if (!from.startsWith('client:')) {
      console.error(`❌ twilio-outgoing rejected non-client From: ${from || '(empty)'}`);
      return say('Outgoing calls are only available from the app.');
    }

    const twilioLine = process.env.TWILIO_PHONE_NUMBER;
    if (!twilioLine) {
      console.error('❌ twilio-outgoing: TWILIO_PHONE_NUMBER not set — no caller ID to dial out with');
      return say('Outgoing calling is not configured.');
    }
    // Displayed caller ID: TWILIO_OUTBOUND_CALLER_ID (e.g. the owner's own
    // mobile, so customers see and return calls to a familiar number) with the
    // Twilio line as fallback. ⚠️ A non-Twilio number here MUST be added as a
    // Verified Caller ID in the Twilio Console (error 13214 otherwise). Only
    // the DISPLAY uses it — tenant resolution below stays on the Twilio line.
    const callerId = (process.env.TWILIO_OUTBOUND_CALLER_ID || '').trim() || twilioLine;

    // The dial target arrives via the client's connect() params. Accept phone
    // numbers only (no client:/sip: targets) and normalize NZ local formats to
    // E.164, matching the normalizePhone convention in the voice webhook.
    const rawTo = String(req.body?.To || '').trim();
    const bare = rawTo.replace(/\D/g, '');
    let dialTo = '';
    if (rawTo.startsWith('+') && bare.length >= 7 && bare.length <= 15) {
      dialTo = `+${bare}`;
    } else if (bare.startsWith('64') && bare.length >= 9) {
      dialTo = `+${bare}`;
    } else if (bare.startsWith('0') && bare.length >= 8) {
      dialTo = `+64${bare.slice(1)}`;
    }
    if (!dialTo) {
      console.error(`❌ twilio-outgoing could not parse dial target: "${rawTo}"`);
      return say('Sorry, that phone number could not be dialled.');
    }

    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const baseUrl = `${protocol}://${host}`;
    // Reuse the inbound recording pipeline for logging: callerFrom = the OTHER
    // party (the customer we dialled) so the Calls page shows their number,
    // calledTo = our own line for tenant resolution, direction=outbound flips
    // the stored direction and skips inbound-lead extraction. `&` between
    // query params must be `&amp;` inside an XML attribute.
    const recordingCallbackUrl =
      `${baseUrl}/api/webhooks/twilio-voice?callerFrom=${encodeURIComponent(dialTo)}&amp;calledTo=${encodeURIComponent(twilioLine)}&amp;direction=outbound`;

    console.log(`📞 Outgoing web call: ${from} → ${dialTo} (callerId ${callerId})`);
    return res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial
    callerId="${escapeTwimlXml(callerId)}"
    record="record-from-answer"
    recordingStatusCallback="${recordingCallbackUrl}"
    recordingStatusCallbackEvent="completed"
    timeout="30"
  >
    <Number>${dialTo}</Number>
  </Dial>
</Response>`);
  });

  // TwiML: answer the call. With the AI voice agent enabled, play an IVR menu
  // ("press 1 for an AI quote, press 2 for Jules") — press 2, a wrong digit or
  // no input all fall through to ringing the iOS app + owner's phone exactly
  // as before (record, voicemail on no-answer). With the agent disabled — and
  // on the ?mode=dial fallback re-entry used when the AI bridge fails — the
  // response is byte-identical to the original behaviour.
  app.post('/api/webhooks/twilio-answer', async (req: Request, res: Response) => {
    // Validate Twilio signature to prevent spoofed requests
    if (!validateTwilioSignature(req)) {
      console.error('❌ Invalid Twilio signature for answer webhook');
      return res.status(403).send('Forbidden');
    }

    let answerSettings: schema.BusinessSettings | null = null;
    try {
      answerSettings = await storage.getBusinessSettings();
    } catch (settingsErr) {
      // Settings unreadable → treat the agent as disabled; never block the call.
      console.error('Voice-agent settings load failed — answering with dial flow:', settingsErr);
    }

    const dialBody = await buildDialJulesTwimlBody(req);
    res.type('text/xml');

    const voiceAgentOn = !!answerSettings?.voiceAgentEnabled && !!process.env.OPENAI_API_KEY;
    if (!voiceAgentOn || req.query.mode === 'dial') {
      return res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
${dialBody}</Response>`);
    }

    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const baseUrl = `${protocol}://${host}`;
    const inboundFrom = String(req.body?.ForwardedFrom || req.body?.From || '');
    const inboundTo = String(req.body?.To || '');
    const identity = getBusinessIdentity(answerSettings);
    const greeting = (answerSettings?.voiceAgentGreeting ||
      'Thanks for calling {businessName}. For a quick quote with our A.I. assistant, press 1. To speak to {ownerName}, press 2.')
      .replace(/\{businessName\}/g, identity.name)
      .replace(/\{ownerName\}/g, identity.ownerName);
    // `&` between query params must be `&amp;` inside an XML attribute.
    const ivrActionUrl =
      `${baseUrl}/api/webhooks/twilio-ivr?callerFrom=${encodeURIComponent(inboundFrom)}&amp;calledTo=${encodeURIComponent(inboundTo)}`;

    console.log(`📞 Twilio answer webhook — IVR menu (voice agent on), callerFrom=${inboundFrom || 'unknown'}`);
    return res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Gather input="dtmf" numDigits="1" timeout="5" action="${ivrActionUrl}" method="POST">
    <Say voice="alice">${escapeTwimlXml(greeting)}</Say>
  </Gather>
${dialBody}</Response>`);
  });

  // IVR digit handler: 1 → bridge the caller to the AI voice agent over a
  // Twilio Media Stream; anything else (press 2, wrong digit) → dial Jules as
  // before. Timeout/no-input never reaches here — the menu TwiML falls through
  // to the dial verbs inline after </Gather>.
  app.post('/api/webhooks/twilio-ivr', async (req: Request, res: Response) => {
    if (!validateTwilioSignature(req)) {
      console.error('❌ Invalid Twilio signature for IVR webhook');
      return res.status(403).send('Forbidden');
    }

    res.type('text/xml');
    const digit = String(req.body?.Digits || '');
    const callSid = String(req.body?.CallSid || '');
    if (digit !== '1' || !callSid) {
      const dialBody = await buildDialJulesTwimlBody(req);
      return res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
${dialBody}</Response>`);
    }

    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const baseUrl = `${protocol}://${host}`;
    const callerPhone = String(req.query.callerFrom || req.body?.From || '');
    // WS upgrades can't go through validateTwilioSignature, so the stream URL
    // carries a short-lived HMAC token bound to this CallSid instead.
    const streamToken = mintStreamToken(callSid);

    // The verbs after </Connect> run whenever the stream ends with the call
    // still alive — i.e. the OpenAI bridge failed to start or died mid-call.
    // They route the caller to the normal dial-Jules flow via ?mode=dial. On a
    // successful conversation the agent hangs up via the REST API, so the
    // redirect never fires.
    console.log(`📞 IVR: caller pressed 1 — bridging ${callerPhone || 'unknown'} to voice agent (call ${callSid})`);
    return res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Connect>
    <Stream url="wss://${host}/api/voice-agent/stream?token=${streamToken}">
      <Parameter name="callerPhone" value="${escapeTwimlXml(callerPhone)}"/>
    </Stream>
  </Connect>
  <Say voice="alice">Sorry, our assistant is unavailable right now. Connecting you through.</Say>
  <Redirect method="POST">${baseUrl}/api/webhooks/twilio-answer?mode=dial</Redirect>
</Response>`);
  });

  // Streams a public audio file out of the private GCS bucket. Twilio's <Play>
  // needs a publicly-reachable URL, but we don't want to expose the whole
  // bucket (private customer photos live there). Accepts mp3 or wav (macOS
  // afconvert produces wav, ffmpeg produces mp3 — whichever was uploaded).
  //   folder=voicemail  baseName=greeting   → voicemail/greeting.{mp3,wav}
  //   folder=recording-disclosure baseName=disclosure → .../disclosure.{mp3,wav}
  const serveBucketAudio = async (
    req: Request,
    res: Response,
    folder: string,
    baseName: string,
    notFoundMsg: string,
  ) => {
    try {
      const privateDir = (process.env.PRIVATE_OBJECT_DIR || '').trim();
      if (!privateDir) {
        return res.status(503).send('Object storage not configured');
      }
      const parts = privateDir.replace(/^\//, '').split('/');
      const bucketName = parts[0];
      const prefix = parts.slice(1).join('/');
      const candidates: Array<{ name: string; type: string }> = [
        { name: `${prefix}/${folder}/${baseName}.mp3`, type: 'audio/mpeg' },
        { name: `${prefix}/${folder}/${baseName}.wav`, type: 'audio/wav' },
      ];
      for (const candidate of candidates) {
        const file = objectStorageClient.bucket(bucketName).file(candidate.name);
        const [exists] = await file.exists();
        if (!exists) continue;
        const [metadata] = await file.getMetadata();
        const total = Number(metadata.size) || 0;
        res.set('Content-Type', (metadata.contentType as string) || candidate.type);
        res.set('Cache-Control', 'public, max-age=300');
        // WebKit (<audio> in Safari and the iOS webview) refuses to play media
        // unless the server advertises and honours byte-range requests — it
        // sends `Range: bytes=0-` and expects a 206 Partial Content reply. Plain
        // 200 full-body responses show as "Error" in the player. Honour ranges
        // so the in-app preview works. (Twilio's <Play> uses a plain GET and is
        // unaffected either way.)
        res.set('Accept-Ranges', 'bytes');

        const onErr = (err: Error) => {
          console.error(`Error streaming ${folder}/${baseName}:`, err);
          if (!res.headersSent) res.status(500).send('Stream error');
        };

        const rangeHeader = req.headers.range;
        const match =
          total > 0 && typeof rangeHeader === 'string'
            ? /^bytes=(\d*)-(\d*)$/.exec(rangeHeader.trim())
            : null;
        if (match) {
          const start = match[1] ? parseInt(match[1], 10) : 0;
          let end = match[2] ? parseInt(match[2], 10) : total - 1;
          if (Number.isNaN(start) || Number.isNaN(end) || start > end || start >= total) {
            res.set('Content-Range', `bytes */${total}`);
            return res.status(416).end();
          }
          if (end >= total) end = total - 1;
          res.status(206);
          res.set('Content-Range', `bytes ${start}-${end}/${total}`);
          res.set('Content-Length', String(end - start + 1));
          return file.createReadStream({ start, end }).on('error', onErr).pipe(res);
        }

        if (total > 0) res.set('Content-Length', String(total));
        return file.createReadStream().on('error', onErr).pipe(res);
      }
      return res.status(404).send(notFoundMsg);
    } catch (err) {
      console.error(`Error serving ${folder}/${baseName}:`, err);
      if (!res.headersSent) res.status(500).send('Internal error');
    }
  };

  // Voicemail greeting — upload to voicemail/greeting.{mp3,wav}; point
  // TWILIO_VOICEMAIL_GREETING_URL at this.
  app.get('/api/public/voicemail-greeting', async (req: Request, res: Response) => {
    await serveBucketAudio(
      req,
      res,
      'voicemail',
      'greeting',
      'Voicemail greeting not uploaded. Place greeting.mp3 or greeting.wav in voicemail/ under the private GCS bucket.',
    );
  });

  // Recorded-call disclosure — upload to recording-disclosure/disclosure.{mp3,wav};
  // point TWILIO_RECORDING_DISCLOSURE_URL at this.
  app.get('/api/public/recording-disclosure', async (req: Request, res: Response) => {
    await serveBucketAudio(
      req,
      res,
      'recording-disclosure',
      'disclosure',
      'Recording disclosure not uploaded. Place disclosure.mp3 or disclosure.wav in recording-disclosure/ under the private GCS bucket.',
    );
  });

  // ── Voicemail greeting management (admin) ──────────────────────────────────
  // Lets the owner record/upload their own voicemail greeting from the app
  // instead of hand-uploading to GCS or editing env vars. The file lands at
  // voicemail/greeting.{mp3,wav}; the public /api/public/voicemail-greeting
  // route above serves it to Twilio, and the no-answer handler below
  // auto-detects it — so no TWILIO_VOICEMAIL_GREETING_URL env var is required.
  const parsePrivateBucket = (): { bucketName: string; prefix: string } | null => {
    const privateDir = (process.env.PRIVATE_OBJECT_DIR || '').trim();
    if (!privateDir) return null;
    const parts = privateDir.replace(/^\//, '').split('/');
    return { bucketName: parts[0], prefix: parts.slice(1).join('/') };
  };

  // Returns the format of an uploaded greeting if one is present, else null.
  const findUploadedGreeting = async (): Promise<'mp3' | 'wav' | null> => {
    const bucket = parsePrivateBucket();
    if (!bucket) return null;
    for (const ext of ['mp3', 'wav'] as const) {
      try {
        const [exists] = await objectStorageClient
          .bucket(bucket.bucketName)
          .file(`${bucket.prefix}/voicemail/greeting.${ext}`)
          .exists();
        if (exists) return ext;
      } catch {
        /* try next candidate */
      }
    }
    return null;
  };

  // Admin UI status: is a custom greeting in use right now?
  app.get('/api/twilio/voicemail-greeting/status', requireAdmin, async (_req: Request, res: Response) => {
    const format = await findUploadedGreeting();
    res.json({ success: true, exists: !!format, format });
  });

  // Upload a recorded/selected greeting. Only mp3/wav — the formats Twilio
  // <Play> accepts. Writes greeting.<ext> and removes the sibling format so
  // serveBucketAudio (which checks mp3 before wav) resolves deterministically.
  app.post('/api/twilio/voicemail-greeting', requireAdmin, imageUpload.single('audio'), async (req: Request, res: Response) => {
    try {
      const file = req.file;
      if (!file) {
        return res.status(400).json({ success: false, message: 'No audio file provided' });
      }
      const mime = (file.mimetype || '').toLowerCase();
      const name = file.originalname.toLowerCase();
      const isMp3 = mime === 'audio/mpeg' || mime === 'audio/mp3' || name.endsWith('.mp3');
      const isWav = mime === 'audio/wav' || mime === 'audio/wave' || mime === 'audio/x-wav' || name.endsWith('.wav');
      if (!isMp3 && !isWav) {
        return res.status(400).json({ success: false, message: 'Greeting must be an MP3 or WAV file' });
      }
      const bucket = parsePrivateBucket();
      if (!bucket) {
        return res.status(503).json({ success: false, message: 'Object storage not configured' });
      }
      const ext = isMp3 ? 'mp3' : 'wav';
      const siblingExt = isMp3 ? 'wav' : 'mp3';
      const contentType = isMp3 ? 'audio/mpeg' : 'audio/wav';
      await objectStorageClient
        .bucket(bucket.bucketName)
        .file(`${bucket.prefix}/voicemail/greeting.${ext}`)
        .save(file.buffer, { contentType });
      try {
        await objectStorageClient
          .bucket(bucket.bucketName)
          .file(`${bucket.prefix}/voicemail/greeting.${siblingExt}`)
          .delete({ ignoreNotFound: true });
      } catch (delErr) {
        console.error('Voicemail greeting: failed clearing sibling format:', delErr);
      }
      console.log(`📞 Voicemail greeting uploaded (${ext}, ${file.buffer.length} bytes)`);
      res.json({ success: true, format: ext });
    } catch (err) {
      console.error('❌ Voicemail greeting upload failed:', err);
      res.status(500).json({ success: false, message: 'Failed to save greeting' });
    }
  });

  // Revert to the default spoken greeting by removing any uploaded file.
  app.delete('/api/twilio/voicemail-greeting', requireAdmin, async (_req: Request, res: Response) => {
    try {
      const bucket = parsePrivateBucket();
      if (!bucket) {
        return res.status(503).json({ success: false, message: 'Object storage not configured' });
      }
      for (const ext of ['mp3', 'wav'] as const) {
        try {
          await objectStorageClient
            .bucket(bucket.bucketName)
            .file(`${bucket.prefix}/voicemail/greeting.${ext}`)
            .delete({ ignoreNotFound: true });
        } catch (delErr) {
          console.error(`Voicemail greeting: failed deleting ${ext}:`, delErr);
        }
      }
      res.json({ success: true });
    } catch (err) {
      console.error('❌ Voicemail greeting delete failed:', err);
      res.status(500).json({ success: false, message: 'Failed to remove greeting' });
    }
  });

  // TwiML: owner didn't answer → take a voicemail (still records and processes)
  app.post('/api/webhooks/twilio-no-answer', async (req: Request, res: Response) => {
    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const baseUrl = `${protocol}://${host}`;

    // Twilio's <Dial action> fires when the Dial verb finishes for ANY reason —
    // including a successfully connected call where one side hung up. We only
    // want to fall through to voicemail when the dial actually failed to
    // connect, not after a normal completed conversation. DialCallStatus is
    // one of: completed, answered, busy, no-answer, failed, canceled.
    const dialStatus = String(req.body?.DialCallStatus || '').toLowerCase();
    if (dialStatus === 'completed' || dialStatus === 'answered') {
      console.log(`📞 Dial completed (status=${dialStatus}) — call ended naturally, skipping voicemail`);
      res.type('text/xml');
      return res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Hangup/></Response>');
    }

    console.log(`📞 Twilio no-answer (DialCallStatus=${dialStatus || 'unknown'}) — switching to voicemail`);

    // Voicemail recording's status callback also needs callerFrom in the URL
    // (same reason as the answer webhook — recording callbacks don't include
    // From / ForwardedFrom natively). The action callback DOES include From
    // and To from the original call, so we can capture them here.
    // From = original caller; ForwardedFrom = the diverting line (owner's
    // mobile on forwarded calls) — fallback only.
    const inboundFrom = String(req.body?.From || req.body?.ForwardedFrom || '');
    const inboundTo = String(req.body?.To || '');
    const recordingCallbackUrl =
      `${baseUrl}/api/webhooks/twilio-voice?callerFrom=${encodeURIComponent(inboundFrom)}&amp;calledTo=${encodeURIComponent(inboundTo)}&amp;source=voicemail`;

    // Voicemail greeting prefers a pre-recorded audio file (TwiML <Play>) if
    // TWILIO_VOICEMAIL_GREETING_URL is set — that gives the user control of
    // tone of voice and branding. Falls back to TTS via <Say> reading
    // TWILIO_VOICEMAIL_GREETING, or finally to a hardcoded default.
    const escapeXml = (s: string) =>
      s
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');

    const greetingAudioUrl = (process.env.TWILIO_VOICEMAIL_GREETING_URL || '').trim();
    let greetingTwiml: string;
    if (greetingAudioUrl) {
      // Explicit override via env var — audio URL must be publicly reachable.
      greetingTwiml = `<Play>${escapeXml(greetingAudioUrl)}</Play>`;
    } else if (await findUploadedGreeting()) {
      // Owner recorded/uploaded a greeting in the app — serve it via the public
      // endpoint (no env var needed). Cache-bust so Twilio re-fetches after a
      // re-record instead of replaying a stale cached file.
      greetingTwiml = `<Play>${escapeXml(`${baseUrl}/api/public/voicemail-greeting?t=${Date.now()}`)}</Play>`;
    } else {
      const defaultGreeting =
        "Hi, you have reached Treemarkables. We are unable to take your call right now. " +
        "Please leave your name, address, and details of the work you need done, and we will call you back as soon as possible.";
      const greeting = process.env.TWILIO_VOICEMAIL_GREETING || defaultGreeting;
      greetingTwiml = `<Say voice="alice">${escapeXml(greeting)}</Say>`;
    }

    res.type('text/xml');
    res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  ${greetingTwiml}
  <Record
    maxLength="300"
    transcribe="false"
    recordingStatusCallback="${recordingCallbackUrl}"
    recordingStatusCallbackEvent="completed"
  />
</Response>`);
  });

  // Twilio webhook for voice call status updates
  app.post('/api/webhooks/twilio-voice', async (req: Request, res: Response) => {
    try {
      // Validate Twilio signature
      if (!validateTwilioSignature(req)) {
        console.error('❌ Invalid Twilio signature for voice webhook');
        return res.status(403).send('Forbidden');
      }

      // From = the original caller (preserved through carrier diversion).
      // ForwardedFrom = the line that forwarded the call — the owner's own
      // mobile when a customer dials the advertised number. Use From for the
      // customer's number; ForwardedFrom is a last-resort fallback only.
      const { CallSid, CallStatus, RecordingStatus, From, ForwardedFrom, To, RecordingUrl, RecordingSid, RecordingDuration } = req.body;
      
      console.log(`📞 Twilio voice webhook - CallSid: ${CallSid}, Status: ${CallStatus}, RecordingStatus: ${RecordingStatus}, From: ${From}, ForwardedFrom: ${ForwardedFrom}`);
      
      // Handle call completed with recording.
      // Twilio recording status callbacks send RecordingStatus='completed', NOT CallStatus='completed',
      // so we must match on either field to handle both call-status and recording-status payloads.
      if ((CallStatus === 'completed' || RecordingStatus === 'completed') && RecordingUrl) {
        console.log(`🎙️ Call ${CallSid} completed with recording: ${RecordingUrl}`);
        
        // Normalize phone number (NZ format)
        const normalizePhone = (phone: string): string => {
          if (!phone) return phone;
          const cleaned = phone.replace(/\D/g, '');
          if (cleaned.startsWith('64')) return `+${cleaned}`;
          if (cleaned.startsWith('0')) return `+64${cleaned.substring(1)}`;
          if (cleaned.length === 9 || cleaned.length === 10) return `+64${cleaned}`;
          return phone;
        };

        // Twilio's recording-status callback doesn't include From / ForwardedFrom —
        // those parameters are only present on the original call webhook. We
        // captured them on the answer webhook and passed them through as a
        // ?callerFrom=... query param on the recordingStatusCallback URL.
        const callerFromQuery = String(req.query.callerFrom || '');
        const rawCallerPhone = callerFromQuery || From || ForwardedFrom || '';
        const callerPhone = normalizePhone(rawCallerPhone) || 'unknown';
        const callerSource = callerFromQuery ? 'query' : From ? 'From' : ForwardedFrom ? 'ForwardedFrom' : 'none';
        // The no-answer route tags its recording callback with &source=voicemail.
        // A voicemail recording means nobody answered the dial — record it as a
        // missed call, not 'answered', so the Calls page (and anyone debugging
        // "why isn't my phone ringing") can tell the two apart.
        const isVoicemail = String(req.query.source || '') === 'voicemail';
        // The outgoing webhook tags its recording callback with &direction=outbound:
        // callerFrom is then the number WE dialled (the customer), and the call
        // must be logged as outbound + skip inbound-lead extraction below.
        const isOutbound = String(req.query.direction || '') === 'outbound';
        console.log(`📞 Caller identified as: ${callerPhone} (raw: ${rawCallerPhone}, source: ${callerSource}, voicemail: ${isVoicemail}, outbound: ${isOutbound})`);

        // Resolve which tenant owns the dialed line (the answer/no-answer routes
        // pass it through as ?calledTo=...; recording-status callbacks omit To).
        // Binds the call record + caller match to the right business instead of
        // defaulting to Treemarkables and matching customers across all tenants.
        // Unmapped number → undefined → unchanged prior (single-tenant) behaviour.
        const calledToRaw = String(req.query.calledTo || To || '');
        const inboundBizId = await resolveBusinessIdByChannel('phone', calledToRaw);
        if (inboundBizId) {
          console.log(`🏢 Inbound line ${calledToRaw} resolved to business ${inboundBizId}`);
        }

        // Download recording from Twilio and store in Object Storage (persistent across restarts)
        const recordingFilename = `twilio-${CallSid}-${Date.now()}.mp3`;
        const recordingUrlWithAuth = `${RecordingUrl}.mp3?Download=true`;
        const authHeader = 'Basic ' + Buffer.from(`${process.env.TWILIO_ACCOUNT_SID}:${process.env.TWILIO_AUTH_TOKEN}`).toString('base64');

        // Download as buffer then upload to Object Storage
        let recordingBuffer: Buffer;
        try {
          const dlResponse = await fetch(recordingUrlWithAuth, { headers: { 'Authorization': authHeader } });
          if (!dlResponse.ok) throw new Error(`Twilio download failed: ${dlResponse.status}`);
          recordingBuffer = Buffer.from(await dlResponse.arrayBuffer());
          console.log(`✅ Recording downloaded (${recordingBuffer.length} bytes)`);
        } catch (dlErr) {
          console.error('❌ Failed to download recording:', dlErr);
          return;
        }

        // Upload to persistent Object Storage
        const privateDir = (process.env.PRIVATE_OBJECT_DIR || '').trim();
        let servingUrl = `/api/recordings/${recordingFilename}`;
        if (privateDir) {
          try {
            const objectPath = `${privateDir}/recordings/${recordingFilename}`;
            const parts = objectPath.replace(/^\//, '').split('/');
            const bucketName = parts[0];
            const objectName = parts.slice(1).join('/');
            await objectStorageClient.bucket(bucketName).file(objectName).save(recordingBuffer, { contentType: 'audio/mpeg' });
            console.log(`✅ Recording uploaded to Object Storage: ${objectName}`);
          } catch (storageErr) {
            console.error('❌ Object Storage upload failed, falling back to local:', storageErr);
            // Fallback: save locally (ephemeral but better than nothing)
            const recordingPath = path.join(recordingsDir, recordingFilename);
            fs.writeFileSync(recordingPath, recordingBuffer);
            servingUrl = `/uploads/recordings/${recordingFilename}`;
          }
        } else {
          // No Object Storage configured — save locally
          const recordingPath = path.join(recordingsDir, recordingFilename);
          fs.writeFileSync(recordingPath, recordingBuffer);
          servingUrl = `/uploads/recordings/${recordingFilename}`;
          console.warn('⚠️ PRIVATE_OBJECT_DIR not set — recording saved locally (not persistent)');
        }

        // Create call record in DB
        {
            
            // Create call record — stamped to the resolved tenant when the dialed
            // line is mapped (else falls to the column default, as before).
            const call = await runWithBusiness(inboundBizId, () => storage.createCall({
              phoneNumber: callerPhone,
              direction: isOutbound ? 'outbound' : 'inbound',
              status: isVoicemail ? 'missed' : 'answered',
              duration: parseInt(RecordingDuration || '0'),
              recordingUrl: servingUrl,
              twilioCallSid: CallSid
            }));
            
            console.log(`📝 Call record created: ${call.id}`);
            
            // Transcribe and extract job data (async — buffer already in memory)
            setTimeout(async () => {
              try {
                // Transcribe with Whisper using the in-memory buffer
                const audioFile = await toFile(recordingBuffer, recordingFilename, { type: 'audio/mpeg' });
                const transcription = await openai.audio.transcriptions.create({
                  file: audioFile,
                  model: 'whisper-1',
                  language: 'en',
                  response_format: 'text'
                });
                
                const rawTranscript = typeof transcription === 'string' ? transcription : (transcription as any).text || String(transcription);
                
                // Capitalize names in transcript using GPT
                let transcript = rawTranscript;
                try {
                  const capitalizationResponse = await openai.chat.completions.create({
                    model: 'gpt-4o',
                    messages: [
                      {
                        role: 'system',
                        content: 'You are a text formatter. Your only job is to take transcribed text and properly capitalize all proper nouns (names of people, places, companies) while keeping everything else exactly as it is. Return ONLY the corrected text with no explanations or formatting.'
                      },
                      {
                        role: 'user',
                        content: rawTranscript
                      }
                    ],
                    temperature: 0.1
                  });
                  
                  transcript = capitalizationResponse.choices[0].message.content?.trim() || rawTranscript;
                  console.log(`✅ Names capitalized in transcript`);
                } catch (capError) {
                  console.warn('⚠️ Could not capitalize names, using raw transcript:', capError);
                  transcript = rawTranscript;
                }
                
                // Update call with transcript
                await storage.updateCall(call.id, { transcriptText: transcript });
                
                console.log(`✅ Call transcribed: ${transcript.substring(0, 100)}...`);

                // Outbound calls the owner placed are not inbound leads — keep
                // the transcript but skip job extraction + customer creation.
                if (isOutbound) {
                  console.log('📞 Outbound call — skipping lead extraction');
                  return;
                }

                // Extract job data with GPT-4
                const extraction = await openai.chat.completions.create({
                  model: 'gpt-4o',
                  messages: [
                    {
                      role: 'system',
                      content: `You are a data extraction assistant for a field-service business in New Zealand. 
Extract structured job information from customer call transcripts.

Extract:
- customerName: Full name if mentioned
- customerPhone: Use "${callerPhone}" 
- serviceType: One of [tree-removal, tree-pruning, stump-grinding, hedge-trimming, emergency, other]
- address: Full address if mentioned
- urgency: One of [emergency, urgent, normal, low]
- estimatedPrice: Number only if quoted (no $ sign)
- notes: Key details about the job

Return ONLY valid JSON, no markdown. If a field isn't mentioned, use null.`
                    },
                    {
                      role: 'user',
                      content: transcript
                    }
                  ],
                  response_format: { type: 'json_object' }
                });
                
                const jobData = JSON.parse(extraction.choices[0].message.content || '{}');
                console.log(`🤖 Extracted job data:`, jobData);
                
                // Create or find customer
                let customer;
                const customers = await storage.getAllCustomers();
                // Check both phone and mobile fields to avoid creating duplicate
                // customers. When the dialed line resolved to a tenant, scope the
                // match to it so a phone-number collision can't link the call to
                // another tenant's customer (the getAllCustomers read is owner-path).
                customer = customers.find(c =>
                  (!inboundBizId || c.businessId === inboundBizId) &&
                  ((c.phone && normalizePhone(c.phone) === callerPhone) ||
                   (c.mobile && normalizePhone(c.mobile) === callerPhone))
                );

                if (!customer && jobData.customerName) {
                  customer = await runWithBusiness(inboundBizId, () => storage.createCustomer({
                    name: jobData.customerName,
                    phone: callerPhone,
                    address: jobData.address || undefined,
                    source: 'phone_call'
                  }));
                  console.log(`✅ New customer created: ${customer.name}`);
                }

                // Link the call record to the customer now that we know who it is.
                if (customer) {
                  // Re-stamp the call to the matched customer's tenant. The call row was
                  // created before we knew the caller (this webhook is owner-pathed, and
                  // there's no inbound-number→business map yet), so it defaulted to the
                  // Treemarkables tenant; correct it now that the owning business is known.
                  await storage.updateCall(call.id, {
                    customerId: customer.id,
                    businessId: customer.businessId ?? undefined,
                  });
                  console.log(`🔗 Call record linked to customer: ${customer.id}`);
                }

                // If the customer already has an active job, append this call
                // to that job's diary automatically. The user wants new-job
                // creation to stay manual, but existing-customer follow-up
                // calls should land on the right job card without intervention.
                if (customer) {
                  try {
                    const ARCHIVED_STATUSES = new Set([
                      'completed', 'archived', 'unsuccessful', 'cancelled', 'canceled', 'lost',
                    ]);
                    const customerJobs = await storage.getJobsByCustomer(customer.id);
                    const activeJobs = customerJobs.filter(
                      (j: any) => !ARCHIVED_STATUSES.has(String(j.status || '').toLowerCase()),
                    );
                    if (activeJobs.length > 0) {
                      const mostRecentActive = activeJobs.reduce((latest: any, current: any) => {
                        const latestTime = new Date(latest.lastActivityAt || latest.createdAt || 0).getTime();
                        const currentTime = new Date(current.lastActivityAt || current.createdAt || 0).getTime();
                        return currentTime > latestTime ? current : latest;
                      });
                      await storage.updateCall(call.id, { jobId: mostRecentActive.id });
                      // Stamp the diary entry with the matched job's tenant (owner-pathed
                      // webhook → no session) so it lands on the job owner, not the default.
                      await runWithBusiness(mostRecentActive.businessId ?? undefined, () => storage.createJobDiaryEntry({
                        jobId: mostRecentActive.id,
                        entryType: 'call',
                        title: `📞 Inbound call from ${customer.name}`,
                        description: `Call from ${customer.name} (${callerPhone})\n\nTranscript:\n${transcript}`,
                        authorName: 'System',
                        authorRole: 'system',
                        tags: ['call', 'auto-linked'],
                        metadata: {
                          recordingUrl: servingUrl,
                          transcription: transcript,
                          callSid: CallSid,
                        },
                      }));
                      await storage.updateJob(mostRecentActive.id, { lastActivityAt: new Date() });
                      console.log(`📎 Call auto-linked to existing active job #${mostRecentActive.jobNumber}`);
                    } else {
                      console.log(`ℹ️ Customer has no active jobs — call available for manual conversion`);
                    }
                  } catch (linkErr) {
                    console.error('❌ Error auto-linking call to active job:', linkErr);
                  }
                } else {
                  console.log(`ℹ️ No customer match — call available for manual conversion`);
                }
                
              } catch (error) {
                console.error('❌ Error processing call recording:', error);
              }
            }, 500);
        }
      }
      
      // Respond to Twilio
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
      
    } catch (error: any) {
      console.error('❌ Twilio voice webhook error:', error);
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
    }
  });

  // Diagnostic: verify Twilio is wired up end-to-end.
  // Accepts either HERO_WEBHOOK_SECRET (for curl) or an authenticated admin session
  // (so the Communications page can render it without exposing the secret to the browser).
  //   curl -H "x-webhook-secret: $HERO_WEBHOOK_SECRET" \
  //     https://app.treemarkables.co.nz/api/twilio/admin/diagnostic
  app.get('/api/twilio/admin/diagnostic', async (req: Request, res: Response) => {
    const secret = req.headers['x-webhook-secret'];
    const secretOk = !!secret && secret === process.env.HERO_WEBHOOK_SECRET;

    let sessionOk = false;
    if (!secretOk && req.session.employeeId) {
      try {
        const emp = await storage.getEmployee(req.session.employeeId);
        sessionOk = !!emp && emp.role === 'admin';
      } catch {
        sessionOk = false;
      }
    }

    if (!secretOk && !sessionOk) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    const mask = (v?: string) => {
      if (!v) return null;
      if (v.length <= 8) return '••••';
      return `${v.slice(0, 4)}…${v.slice(-4)}`;
    };

    const env = {
      TWILIO_ACCOUNT_SID: { set: !!process.env.TWILIO_ACCOUNT_SID, masked: mask(process.env.TWILIO_ACCOUNT_SID) },
      TWILIO_AUTH_TOKEN: { set: !!process.env.TWILIO_AUTH_TOKEN, masked: mask(process.env.TWILIO_AUTH_TOKEN) },
      TWILIO_API_KEY: { set: !!process.env.TWILIO_API_KEY, masked: mask(process.env.TWILIO_API_KEY) },
      TWILIO_API_SECRET: { set: !!process.env.TWILIO_API_SECRET, masked: mask(process.env.TWILIO_API_SECRET) },
      TWILIO_PHONE_NUMBER: { set: !!process.env.TWILIO_PHONE_NUMBER, value: process.env.TWILIO_PHONE_NUMBER || null },
      TWILIO_OUTBOUND_CALLER_ID: { set: !!process.env.TWILIO_OUTBOUND_CALLER_ID, value: (process.env.TWILIO_OUTBOUND_CALLER_ID || '').trim() || null },
      TWILIO_TWIML_APP_SID: { set: !!process.env.TWILIO_TWIML_APP_SID, masked: mask(process.env.TWILIO_TWIML_APP_SID) },
      TWILIO_PUSH_CREDENTIAL_SID: { set: !!process.env.TWILIO_PUSH_CREDENTIAL_SID, masked: mask(process.env.TWILIO_PUSH_CREDENTIAL_SID) },
      TWILIO_CLIENT_IDENTITY: { set: !!process.env.TWILIO_CLIENT_IDENTITY, value: process.env.TWILIO_CLIENT_IDENTITY || 'treemarkables-owner (default)' },
      OWNER_PHONE_NUMBER: { set: !!process.env.OWNER_PHONE_NUMBER, value: process.env.OWNER_PHONE_NUMBER || null },
      OPENAI_API_KEY: { set: !!process.env.OPENAI_API_KEY, masked: mask(process.env.OPENAI_API_KEY) },
      PRIVATE_OBJECT_DIR: { set: !!process.env.PRIVATE_OBJECT_DIR, value: (process.env.PRIVATE_OBJECT_DIR || '').trim() || null },
    };

    const protocol = req.headers['x-forwarded-proto'] || req.protocol;
    const host = req.headers['x-forwarded-host'] || req.headers.host;
    const observedBaseUrl = `${protocol}://${host}`;
    const expectedBaseUrl = APP_URL;

    const expectedWebhooks = {
      answer: `${expectedBaseUrl}/api/webhooks/twilio-answer`,
      statusCallback: `${expectedBaseUrl}/api/webhooks/twilio-voice`,
      sms: `${expectedBaseUrl}/api/webhooks/sms`,
      outgoing: `${expectedBaseUrl}/api/webhooks/twilio-outgoing`,
    };

    let twilioAccount: any = null;
    let twilioPhoneNumber: any = null;
    let twilioTwimlApp: any = null;
    let twilioVerifiedCallerIds: any = null;
    let twilioFetchError: string | null = null;
    try {
      if (process.env.TWILIO_ACCOUNT_SID && (process.env.TWILIO_AUTH_TOKEN || (process.env.TWILIO_API_KEY && process.env.TWILIO_API_SECRET))) {
        const client = await getTwilioClient();
        const acct = await client.api.accounts(process.env.TWILIO_ACCOUNT_SID!).fetch();
        twilioAccount = { friendlyName: acct.friendlyName, status: acct.status, type: acct.type };

        // Verified outgoing caller IDs AS THE APP'S CREDENTIALS SEE THEM —
        // <Dial callerId> with a non-Twilio number (TWILIO_OUTBOUND_CALLER_ID)
        // is only valid if that number appears in THIS list (error 13214
        // otherwise). Listing it here catches account/subaccount mismatches
        // that the console UI can't reveal.
        try {
          const verifiedIds = await client.outgoingCallerIds.list({ limit: 20 });
          twilioVerifiedCallerIds = verifiedIds.map((v: any) => ({
            phoneNumber: v.phoneNumber,
            friendlyName: v.friendlyName,
          }));
        } catch (vErr: any) {
          twilioVerifiedCallerIds = { error: vErr?.message || String(vErr) };
        }

        // The TwiML App's voice URL is what Twilio hits when a Voice-SDK
        // client places an outgoing call — if it isn't our outgoing webhook,
        // web-dialer calls fail (or hit the wrong flow) with no other symptom.
        if (process.env.TWILIO_TWIML_APP_SID) {
          try {
            const twimlApp = await client.applications(process.env.TWILIO_TWIML_APP_SID).fetch();
            twilioTwimlApp = {
              sid: twimlApp.sid,
              friendlyName: twimlApp.friendlyName,
              voiceUrl: twimlApp.voiceUrl,
              voiceMethod: twimlApp.voiceMethod,
              voiceUrlMatchesExpected: twimlApp.voiceUrl === expectedWebhooks.outgoing,
            };
          } catch (appErr: any) {
            twilioTwimlApp = { error: appErr?.message || String(appErr) };
          }
        }

        if (process.env.TWILIO_PHONE_NUMBER) {
          const list = await client.incomingPhoneNumbers.list({ phoneNumber: process.env.TWILIO_PHONE_NUMBER, limit: 1 });
          const num = list[0];
          if (num) {
            twilioPhoneNumber = {
              sid: num.sid,
              friendlyName: num.friendlyName,
              voiceUrl: num.voiceUrl,
              voiceMethod: num.voiceMethod,
              smsUrl: num.smsUrl,
              smsMethod: num.smsMethod,
              statusCallback: num.statusCallback,
              voiceUrlMatchesExpected: num.voiceUrl === expectedWebhooks.answer,
              smsUrlMatchesExpected: num.smsUrl === expectedWebhooks.sms,
            };
          } else {
            twilioFetchError = `No matching incoming number found in Twilio account for ${process.env.TWILIO_PHONE_NUMBER}`;
          }
        }
      } else {
        twilioFetchError = 'Twilio credentials not set — cannot query Twilio API';
      }
    } catch (err: any) {
      twilioFetchError = err?.message || String(err);
    }

    let recentCalls: any[] = [];
    try {
      // Twilio inbound calls land in the `calls` table (storage.createCall in the
      // twilio-voice webhook) — NOT `call_records`, which is a different feature.
      // Querying the wrong table made this diagnostic report recentCalls: [] even
      // while calls were flowing.
      const calls = await storage.getAllCalls(5);
      recentCalls = calls.map((c: any) => ({
        id: c.id,
        phoneNumber: c.phoneNumber,
        direction: c.direction,
        status: c.status,
        duration: c.duration,
        hasRecording: !!c.recordingUrl,
        hasTranscript: !!c.transcriptText,
        createdAt: c.createdAt,
      }));
    } catch (err: any) {
      // non-fatal
    }

    // Ground truth from Twilio's side, for debugging "phone not ringing":
    // - call legs: each inbound call's child leg to client:<identity> reveals
    //   whether a registered device existed and what the dial did (a leg that
    //   goes straight to 'no-answer'/'failed' with ~0 duration means the VoIP
    //   push never reached a live device).
    // - debugger alerts: APNs/push delivery failures surface here with 52xxx
    //   error codes (e.g. credential/environment mismatch, invalid device
    //   token) that name the root cause outright.
    let twilioCallLegs: any[] = [];
    let twilioAlerts: any[] = [];
    let twilioMonitorError: string | null = null;
    try {
      if (process.env.TWILIO_ACCOUNT_SID && (process.env.TWILIO_AUTH_TOKEN || (process.env.TWILIO_API_KEY && process.env.TWILIO_API_SECRET))) {
        const client = await getTwilioClient();
        const legs = await client.calls.list({ limit: 20 });
        twilioCallLegs = legs.map((c: any) => ({
          sid: c.sid,
          parentCallSid: c.parentCallSid || null,
          from: c.from,
          to: c.to,
          status: c.status,
          startTime: c.startTime,
          duration: c.duration,
        }));
      }
      if (process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN) {
        const basic = Buffer.from(`${process.env.TWILIO_ACCOUNT_SID}:${process.env.TWILIO_AUTH_TOKEN}`).toString('base64');
        const alertsRes = await fetch('https://monitor.twilio.com/v1/Alerts?PageSize=20', {
          headers: { Authorization: `Basic ${basic}` },
        });
        if (alertsRes.ok) {
          const alertsJson: any = await alertsRes.json();
          twilioAlerts = (alertsJson.alerts || []).map((a: any) => ({
            dateCreated: a.date_created,
            logLevel: a.log_level,
            errorCode: a.error_code,
            alertText: typeof a.alert_text === 'string' ? a.alert_text.slice(0, 300) : a.alert_text,
            resourceSid: a.resource_sid,
          }));
        } else {
          twilioMonitorError = `monitor API returned ${alertsRes.status}`;
        }
      }
    } catch (err: any) {
      twilioMonitorError = err?.message || String(err);
    }

    const recommendations: string[] = [];
    if (!env.TWILIO_ACCOUNT_SID.set) recommendations.push('Set TWILIO_ACCOUNT_SID in DO env vars');
    if (!env.TWILIO_AUTH_TOKEN.set) recommendations.push('Set TWILIO_AUTH_TOKEN in DO env vars (needed for signature validation + recording download)');
    if (!env.TWILIO_PHONE_NUMBER.set) recommendations.push('Set TWILIO_PHONE_NUMBER in DO env vars');
    if (!env.OWNER_PHONE_NUMBER.set) recommendations.push('Set OWNER_PHONE_NUMBER (your personal mobile in E.164, e.g. +6421XXXXXXX)');
    if (!env.OPENAI_API_KEY.set) recommendations.push('Set OPENAI_API_KEY (used for Whisper transcription + GPT extraction)');
    if (!env.PRIVATE_OBJECT_DIR.set) recommendations.push('Set PRIVATE_OBJECT_DIR so recordings persist to GCS Object Storage');
    if (!env.TWILIO_API_KEY.set || !env.TWILIO_API_SECRET.set) recommendations.push('Set TWILIO_API_KEY + TWILIO_API_SECRET so the iOS app can register for incoming calls via the Voice SDK');
    if (!env.TWILIO_TWIML_APP_SID.set) recommendations.push('Set TWILIO_TWIML_APP_SID to enable outgoing calls from the iOS app');
    if (!env.TWILIO_PUSH_CREDENTIAL_SID.set) recommendations.push('Set TWILIO_PUSH_CREDENTIAL_SID (a VoIP Push Credential in Twilio Console → Voice → Push Credentials, backed by an Apple VoIP Services APNs certificate) so the iOS app can RECEIVE incoming calls');
    if (twilioPhoneNumber && !twilioPhoneNumber.voiceUrlMatchesExpected) {
      recommendations.push(`Update Twilio console voice webhook to ${expectedWebhooks.answer} (currently: ${twilioPhoneNumber.voiceUrl || 'unset'})`);
    }
    if (twilioTwimlApp && !twilioTwimlApp.error && !twilioTwimlApp.voiceUrlMatchesExpected) {
      recommendations.push(`TwiML App voice URL should be ${expectedWebhooks.outgoing} for web-dialer outgoing calls (currently: ${twilioTwimlApp.voiceUrl || 'unset'}) — POST /api/twilio/admin/configure-outgoing sets it`);
    }
    {
      const outboundCallerId = (process.env.TWILIO_OUTBOUND_CALLER_ID || '').trim();
      if (
        outboundCallerId &&
        outboundCallerId !== process.env.TWILIO_PHONE_NUMBER &&
        Array.isArray(twilioVerifiedCallerIds) &&
        !twilioVerifiedCallerIds.some((v: any) => v.phoneNumber === outboundCallerId)
      ) {
        recommendations.push(`TWILIO_OUTBOUND_CALLER_ID (${outboundCallerId}) is NOT in this account's verified caller IDs — outgoing web calls will fail with error 13214. Verify it at Twilio Console → Phone Numbers → Verified Caller IDs (in THIS account), or unset the env var to fall back to the Twilio line.`);
      }
    }
    // observedBaseUrl is just where the diagnostic was viewed from — it doesn't
    // affect whether Twilio webhooks work. Only the Twilio-side voiceUrl matters.

    res.json({
      success: true,
      observedBaseUrl,
      expectedBaseUrl,
      expectedWebhooks,
      env,
      twilioAccount,
      twilioPhoneNumber,
      twilioTwimlApp,
      twilioVerifiedCallerIds,
      twilioFetchError,
      recentCalls,
      twilioCallLegs,
      twilioAlerts,
      twilioMonitorError,
      recommendations,
    });
  });

  // One-click setup for web-dialer outgoing calls: points the TwiML App's
  // voice URL at /api/webhooks/twilio-outgoing so device.connect() from the
  // browser reaches our dial-out TwiML. Same auth as the diagnostic above
  // (HERO_WEBHOOK_SECRET header for curl, or an admin session).
  app.post('/api/twilio/admin/configure-outgoing', async (req: Request, res: Response) => {
    const secret = req.headers['x-webhook-secret'];
    const secretOk = !!secret && secret === process.env.HERO_WEBHOOK_SECRET;
    let sessionOk = false;
    if (!secretOk && req.session.employeeId) {
      try {
        const emp = await storage.getEmployee(req.session.employeeId);
        sessionOk = !!emp && emp.role === 'admin';
      } catch {
        sessionOk = false;
      }
    }
    if (!secretOk && !sessionOk) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }
    try {
      const twimlAppSid = process.env.TWILIO_TWIML_APP_SID;
      if (!twimlAppSid) {
        return res.status(400).json({ success: false, message: 'TWILIO_TWIML_APP_SID not set — create a TwiML App in the Twilio Console first' });
      }
      const expectedVoiceUrl = `${APP_URL}/api/webhooks/twilio-outgoing`;
      const client = await getTwilioClient();
      const updated = await client.applications(twimlAppSid).update({
        voiceUrl: expectedVoiceUrl,
        voiceMethod: 'POST',
      });
      console.log(`✅ TwiML App ${twimlAppSid} voice URL set to ${updated.voiceUrl}`);
      return res.json({ success: true, sid: updated.sid, voiceUrl: updated.voiceUrl, voiceMethod: updated.voiceMethod });
    } catch (error: any) {
      console.error('❌ Failed to configure TwiML App voice URL:', error);
      return res.status(500).json({ success: false, message: error?.message || 'Failed to update TwiML App' });
    }
  });

  // GET /api/call-records/unlinked — Get call records not linked to any job
  app.get('/api/call-records/unlinked', async (req: Request, res: Response) => {
    try {
      const calls = await storage.getCallRecords({ limit: 100 });
      const unlinked = calls.filter((c: any) => !c.jobId);
      res.json({ success: true, data: unlinked });
    } catch (error) {
      console.error('Error fetching unlinked calls:', error);
      res.status(500).json({ success: false, message: 'Failed to fetch unlinked calls' });
    }
  });

  // POST /api/call-records/:id/link-job — Link a call record to a job
  app.post('/api/call-records/:id/link-job', async (req: Request, res: Response) => {
    try {
      const { jobId } = req.body;
      if (!jobId) {
        return res.status(400).json({ success: false, message: 'jobId is required' });
      }

      // Derive customerId from the job itself (not from the client request)
      const job = await storage.getJob(jobId);
      if (!job) {
        return res.status(404).json({ success: false, message: 'Job not found' });
      }
      const resolvedCustomerId = job.customerId || undefined;

      const updated = await storage.updateCallRecord(req.params.id, {
        jobId,
        customerId: resolvedCustomerId
      });

      // Add diary entry for the linked job
      const callRecord = updated;
      await storage.createJobDiaryEntry({
        jobId,
        entryType: 'call',
        title: `Inbound Call from ${callRecord.callerName || callRecord.fromNumber}`,
        description: `Caller: ${callRecord.fromNumber}\nDuration: ${callRecord.duration || 0}s${callRecord.transcriptionSummary ? `\n\nSummary: ${callRecord.transcriptionSummary}` : ''}${callRecord.transcription ? `\n\nTranscript:\n${callRecord.transcription}` : ''}`,
        authorName: 'System',
        authorRole: 'system',
        tags: ['call', 'vonage', 'inbound', 'recorded'],
        metadata: {
          recordingUrl: callRecord.recordingUrl,
          transcription: callRecord.transcription,
          transcriptionSummary: callRecord.transcriptionSummary,
          duration: callRecord.duration,
          callerNumber: callRecord.fromNumber,
          callRecordId: callRecord.id
        }
      });

      res.json({ success: true, data: updated });
    } catch (error) {
      console.error('Error linking call to job:', error);
      res.status(500).json({ success: false, message: 'Failed to link call to job' });
    }
  });

  // Get all invoices
  app.get('/api/invoices', async (req: Request, res: Response) => {
    try {
      const { jobId, customerId } = req.query;
      
      // Build query with optional filters
      let query = db.select().from(invoices);
      
      if (jobId) {
        query = query.where(eq(invoices.jobId, jobId as string)) as any;
      } else if (customerId) {
        query = query.where(eq(invoices.customerId, customerId as string)) as any;
      }
      
      const result = await query.orderBy(desc(invoices.createdAt));
      
      // Fetch customer and job data for each invoice
      const invoicesWithRelations = await Promise.all(
        result.map(async (invoice) => {
          const [customerData, jobData] = await Promise.all([
            invoice.customerId ? db.select().from(customers).where(eq(customers.id, invoice.customerId)).limit(1) : Promise.resolve([]),
            invoice.jobId ? db.select().from(jobs).where(eq(jobs.id, invoice.jobId)).limit(1) : Promise.resolve([])
          ]);
          
          return {
            ...invoice,
            customer: customerData[0] || null,
            job: jobData[0] || null
          };
        })
      );
      
      res.json({ success: true, data: invoicesWithRelations });
    } catch (error) {
      console.error('Error fetching invoices:', error);
      res.status(500).json({ success: false, message: 'Error fetching invoices' });
    }
  });

  // Get invoice by ID
  app.get('/api/invoices/:id', async (req: Request, res: Response) => {
    try {
      // Query invoice directly from database
      const result = await db.select()
        .from(invoices)
        .where(eq(invoices.id, req.params.id))
        .limit(1);
      
      if (result.length === 0) {
        return res.status(404).json({ success: false, message: 'Invoice not found' });
      }
      
      const invoice = result[0];
      
      // Fetch related customer, job, and sections data in parallel for faster loading
      const [customerData, jobData, sections, tpl, bizSettings] = await Promise.all([
        invoice.customerId ? db.select().from(customers).where(eq(customers.id, invoice.customerId)).limit(1) : Promise.resolve([]),
        invoice.jobId ? db.select().from(jobs).where(eq(jobs.id, invoice.jobId)).limit(1) : Promise.resolve([]),
        storage.getInvoiceSectionsByInvoice(invoice.id),
        // Per-tenant identity scoped to the invoice owner (so the viewer never shows
        // another business's contact — or bank account). Same shape as the public route.
        storage.getDefaultDocumentTemplateForBusiness(invoice.businessId, 'invoice'),
        storage.getBusinessSettingsForBusiness(invoice.businessId),
      ]);

      const company = {
        name: tpl?.companyName ?? '',
        email: tpl?.companyEmail ?? '',
        phone: tpl?.companyPhone ?? '',
        address: tpl?.companyAddress ?? '',
        gstNumber: tpl?.gstNumber ?? '',
        bankAccountName: bizSettings?.bankAccountName ?? '',
        bankAccountNumber: bizSettings?.bankAccountNumber ?? '',
      };

      res.json({
        success: true,
        data: {
          ...invoice,
          customer: customerData[0] || null,
          job: jobData[0] || null,
          company,
          sections: sections.map(s => ({
            ...s,
            images: Array.isArray(s.images) ? s.images : [],
          })),
        }
      });
    } catch (error) {
      console.error('Error fetching invoice:', error);
      res.status(500).json({ success: false, message: 'Error fetching invoice' });
    }
  });

  // Download invoice PDF
  app.get('/api/invoices/:id/pdf', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      
      // Get invoice with relations
      const result = await db.select()
        .from(invoices)
        .where(eq(invoices.id, id))
        .limit(1);
      
      if (result.length === 0) {
        return res.status(404).json({ success: false, message: 'Invoice not found' });
      }
      
      const invoice = result[0];
      
      // Fetch related customer and job data
      const [customerData, jobData] = await Promise.all([
        invoice.customerId ? db.select().from(customers).where(eq(customers.id, invoice.customerId)).limit(1) : Promise.resolve([]),
        invoice.jobId ? db.select().from(jobs).where(eq(jobs.id, invoice.jobId)).limit(1) : Promise.resolve([])
      ]);
      
      const customer = customerData[0] || null;
      const job = jobData[0] || null;
      
      // Fetch invoice template for block-config-aware PDF rendering. Scope to the
      // invoice's OWNING tenant — this is a public, session-less route, so the
      // unscoped lookup returned Treemarkables' template (name/GST) for every
      // tenant's PDF.
      const invoiceTemplate2 = (await storage.getDefaultDocumentTemplateForBusiness(invoice.businessId, 'invoice')) || null;

      // Photos for the PDF: prefer images persisted on the invoice's photo sections
      // (these are the ones the sender explicitly attached at send time), then fall
      // back to the job's after-/before-photos so the PDF still shows something when
      // an older invoice has no photo section yet.
      const invoicePhotoSections = await storage.getInvoiceSectionsByInvoice(invoice.id);
      const sectionPhotos: string[] = invoicePhotoSections
        .flatMap(s => (s.images || []) as string[]);
      const fallbackJobPhotos: string[] = [
        ...((job?.afterPhotos as string[] | null) || []),
        ...((job?.beforePhotos as string[] | null) || []),
      ];
      const pdfPhotos: string[] = Array.from(new Set(
        (sectionPhotos.length > 0 ? sectionPhotos : fallbackJobPhotos).filter(isSupportedPhotoUrl)
      ));

      // Generate PDF using the shared helper (same code as email attachment)
      const pdfBuffer = await generateInvoicePDFBuffer(invoice, job, customer, invoiceTemplate2, pdfPhotos);

      res.setHeader('Content-Type', 'application/pdf');
      // Inline so the PDF renders in-browser when customers click the email link
      // (Microsoft PDF-stripping workaround). `attachment` left the tab blank on
      // desktop and failed silently in mobile email in-app browsers.
      res.setHeader('Content-Disposition', `inline; filename="Invoice-${invoice.invoiceNumber}.pdf"`);
      res.send(pdfBuffer);
      
    } catch (error) {
      console.error('Error generating invoice PDF:', error);
      res.status(500).json({ success: false, message: 'Error generating invoice PDF' });
    }
  });

  // Update invoice status (for payment recording, etc.)
  app.patch('/api/invoices/:id', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;

      // Pre-process date strings into Date objects before Zod validation
      const processedBody = { ...req.body };
      if (typeof processedBody.dueDate === 'string' && processedBody.dueDate) {
        processedBody.dueDate = new Date(processedBody.dueDate);
      }
      if (typeof processedBody.issueDate === 'string' && processedBody.issueDate) {
        processedBody.issueDate = new Date(processedBody.issueDate);
      }
      if (typeof processedBody.paidAt === 'string' && processedBody.paidAt) {
        processedBody.paidAt = new Date(processedBody.paidAt);
      }

      // Validate request body with Zod schema
      const validationResult = schema.updateInvoiceSchema.safeParse(processedBody);
      if (!validationResult.success) {
        return res.status(400).json({ 
          success: false, 
          message: 'Invalid invoice data', 
          errors: validationResult.error.errors 
        });
      }
      
      const updateData = validationResult.data;
      // Never let an update move the invoice to another tenant. (Marking paid /
      // setting paidAt stays allowed — it's the legitimate manual-payment flow.)
      delete (updateData as any).businessId;

      const invoice = await storage.getInvoice(id);
      if (!invoice) {
        return res.status(404).json({ success: false, message: 'Invoice not found' });
      }

      // Auto-set paidAt when status changes to 'paid' for the first time
      if (updateData.status === 'paid' && invoice.status !== 'paid' && !updateData.paidAt) {
        (updateData as any).paidAt = new Date();
      }

      // Update invoice using proper updateInvoice method
      const updatedInvoice = await storage.updateInvoice(id, updateData);

      // Sync invoice amount to job's totalAmount for revenue/profit tracking
      if (updateData.amount && invoice.jobId) {
        try {
          await storage.updateJob(invoice.jobId, {
            totalAmount: updateData.amount.toString()
          });
          console.log('💰 Synced invoice amount to job total_amount:', updateData.amount);
        } catch (syncErr) {
          console.error('⚠️ Failed to sync invoice amount to job:', syncErr);
        }
      }

      // Backfill the job description from the invoice when the job has none yet,
      // so a description typed into the invoice surfaces on the job card.
      // Only fill when empty — never clobber an existing job description.
      if (typeof updateData.description === 'string' && updateData.description.trim() && invoice.jobId) {
        try {
          const linkedJob = await storage.getJob(invoice.jobId);
          if (linkedJob && !(linkedJob.description || '').trim()) {
            await storage.updateJob(invoice.jobId, {
              description: updateData.description.trim()
            });
            console.log('📝 Backfilled empty job description from invoice');
          }
        } catch (syncErr) {
          console.error('⚠️ Failed to sync invoice description to job:', syncErr);
        }
      }

      console.log(`📋 Invoice ${invoice.invoiceNumber} updated:`, updateData);

      res.json({ success: true, data: updatedInvoice });
    } catch (error) {
      console.error('Error updating invoice:', error);
      res.status(500).json({ success: false, message: 'Error updating invoice' });
    }
  });

