  // Revenue breakdown - list of jobs that make up the revenue
  app.get('/api/revenue-breakdown', async (req: Request, res: Response) => {
    try {
      const { from, to, leadSource, type } = req.query;
      
      let fromDate: Date | undefined;
      let toDate: Date | undefined;
      
      // Parse dates as NZ timezone
      if (from && typeof from === 'string') {
        fromDate = fromZonedTime(`${from}T00:00:00`, 'Pacific/Auckland');
        if (isNaN(fromDate.getTime())) {
          return res.status(400).json({ success: false, message: 'Invalid from date format' });
        }
      }
      
      if (to && typeof to === 'string') {
        toDate = fromZonedTime(`${to}T23:59:59.999`, 'Pacific/Auckland');
        if (isNaN(toDate.getTime())) {
          return res.status(400).json({ success: false, message: 'Invalid to date format' });
        }
      }
      
      // Get completed jobs with invoices in the date range.
      // Fetch in parallel — these four queries are independent. We use
      // getJobsForAnalytics (slim SELECT * FROM jobs) instead of getAllJobs;
      // the breakdown doesn't need the customer LEFT JOIN or the diary-reply
      // correlated subqueries, and skipping those drops job-fetch time from
      // ~5s to ~1s on a 3k-job table.
      const [allJobs, allInvoices, allCustomers, allProposals] = await Promise.all([
        storage.getJobsForAnalytics(),
        storage.getAllInvoices(),
        storage.getAllCustomers(),
        storage.getAllProposals(),
      ]);
      
      // Create customer map
      const customerMap = new Map(allCustomers.map(c => [c.id, c]));
      
      // Build invoice maps from invoices whose issueDate falls within the requested
      // date range. This matches how getRevenueStats anchors its totals: revenue is
      // recognised when the invoice is issued, not when the job was completed. Without
      // this filter the drilldown total can include older or partial invoices on jobs
      // completed in the window, drifting away from the Revenue card figure.
      const jobInvoiceMap = new Map<string, number>();
      const jobInvoiceDateMap = new Map<string, string>(); // jobId -> latest invoice issue date in window
      // Internal metrics show ex-GST per business rule. invoiceRevenueExGst()
      // prefers items[].amount (always ex-GST) over amount/1.15, because amount
      // has been stored inconsistently (inc-GST on some rows, ex-GST on others).
      for (const invoice of allInvoices) {
        if (invoice.status === 'cancelled' || !invoice.jobId) continue;
        // Anchor on issueDate; fall back to createdAt so invoices without an issueDate still count.
        const anchor = invoice.issueDate ? new Date(invoice.issueDate) :
                       invoice.createdAt ? new Date(invoice.createdAt) : null;
        if (fromDate || toDate) {
          if (!anchor) continue;
          if (fromDate && anchor < fromDate) continue;
          if (toDate && anchor > toDate) continue;
        }
        const existingAmount = jobInvoiceMap.get(invoice.jobId) || 0;
        const invoiceAmount = invoiceRevenueExGst(invoice);
        jobInvoiceMap.set(invoice.jobId, existingAmount + invoiceAmount);
        if (invoice.issueDate) {
          const dateStr = invoice.issueDate.toString();
          const existing = jobInvoiceDateMap.get(invoice.jobId);
          if (!existing || dateStr > existing) {
            jobInvoiceDateMap.set(invoice.jobId, dateStr);
          }
        }
      }
      
      // Create proposal amount map (highest proposal per job)
      const jobProposalMap = new Map<string, number>();
      for (const proposal of allProposals) {
        if (proposal.jobId && proposal.totalPrice) {
          // Check if proposal is in date range
          if (fromDate || toDate) {
            const createdAt = proposal.createdAt ? new Date(proposal.createdAt) : null;
            if (createdAt) {
              if (fromDate && createdAt < fromDate) continue;
              if (toDate && createdAt > toDate) continue;
            }
          }
          const proposalAmount = parseFloat(proposal.totalPrice?.toString() || '0');
          const existingAmount = jobProposalMap.get(proposal.jobId) || 0;
          if (proposalAmount > existingAmount) {
            jobProposalMap.set(proposal.jobId, proposalAmount);
          }
        }
      }
      
      // Filter jobs by lead source if specified
      let filteredJobs = allJobs.filter(job => job.status !== 'archived');
      
      if (leadSource && typeof leadSource === 'string') {
        const normalizedLeadSource = leadSource.toLowerCase().replace(/\s+/g, '_');
        filteredJobs = filteredJobs.filter(job => {
          const jobLeadSource = (job.leadSource || 'other').toLowerCase().replace(/\s+/g, '_');
          return jobLeadSource === normalizedLeadSource || 
                 (normalizedLeadSource === 'other' && !job.leadSource);
        });
      }
      
      // Determine what type of breakdown (invoiced or quoted)
      const breakdownType = type === 'quoted' ? 'quoted' : 'invoiced';
      
      // Build breakdown based on type
      let breakdown;
      if (breakdownType === 'quoted') {
        // Show jobs with proposals
        breakdown = filteredJobs
          .map(job => {
            const quotedAmount = jobProposalMap.get(job.id) || 0;
            const customer = customerMap.get(job.customerId || '');
            return {
              jobNumber: job.jobNumber,
              jobId: job.id,
              customerName: customer?.name || 'Unknown',
              title: job.title || '',
              leadSource: job.leadSource || 'other',
              status: job.status,
              completedDate: job.completedDate,
              amount: quotedAmount,
              amountType: 'quoted'
            };
          })
          .filter(j => j.amount > 0)
          .sort((a, b) => b.amount - a.amount);
      } else {
        // Show jobs whose invoices fall in the date window. Anchoring on invoice
        // issueDate (jobInvoiceMap is already date-filtered above) keeps the
        // drilldown rows + total aligned with the Revenue card, which also
        // recognises revenue at invoice time.
        const invoicedJobIds = new Set(jobInvoiceMap.keys());
        breakdown = filteredJobs
          .filter(job => invoicedJobIds.has(job.id))
          .map(job => {
            const invoiceAmount = jobInvoiceMap.get(job.id) || 0;
            const customer = customerMap.get(job.customerId || '');
            return {
              jobNumber: job.jobNumber,
              jobId: job.id,
              customerName: customer?.name || 'Unknown',
              title: job.title || '',
              leadSource: job.leadSource || 'other',
              status: job.status,
              completedDate: job.completedDate,
              invoiceDate: jobInvoiceDateMap.get(job.id) || null,
              amount: invoiceAmount,
              amountType: 'invoiced'
            };
          })
          .filter(j => j.amount > 0)
          .sort((a, b) => new Date(b.invoiceDate || b.completedDate || 0).getTime() - new Date(a.invoiceDate || a.completedDate || 0).getTime());
      }
      
      const total = breakdown.reduce((sum, j) => sum + j.amount, 0);
      
      res.json({ success: true, data: { breakdown, total, type: breakdownType } });
    } catch (error) {
      console.error('Error fetching revenue breakdown:', error);
      res.status(500).json({ success: false, message: 'Error fetching revenue breakdown' });
    }
  });

