  // Upload photos for a job (before/after documentation)
  app.post('/api/jobs/:jobId/photos/batch', imageUpload.array('photos', 50), async (req: Request, res: Response) => {
    try {
      const { jobId } = req.params;
      const { type } = req.body; // 'before' or 'after'

      if (!req.session.employeeId) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
      }

      // Validate job ID format
      if (!jobId || typeof jobId !== 'string' || jobId.length < 1) {
        return res.status(400).json({ success: false, message: 'Invalid job ID' });
      }

      if (!req.files || !Array.isArray(req.files) || req.files.length === 0) {
        return res.status(400).json({ success: false, message: 'No photos provided' });
      }

      if (!type || (type !== 'before' && type !== 'after')) {
        return res.status(400).json({ 
          success: false, 
          message: 'Photo type must be either "before" or "after"' 
        });
      }

      // Check if job exists AND belongs to the caller's tenant — this is a multer
      // route, so getJob runs on the owner (BYPASSRLS) connection and would happily
      // return another tenant's job (see note on /api/jobs/:jobId/photos).
      const job = await storage.getJob(jobId);
      if (!job || (job.businessId && req.session.businessId && job.businessId !== req.session.businessId)) {
        // No cleanup needed for memory storage
        return res.status(404).json({ success: false, message: 'Job not found' });
      }

      // Upload to GCS via PhotoStorageService so files survive DO App Platform
      // deploys (the local uploads/ disk is ephemeral and gets wiped on every
      // autodeploy). Photos uploaded here are served at /objects/photos/{name}
      // by the existing /objects/photos/:filename route.
      const photoStorage = new PhotoStorageService();
      const photoUrls: string[] = [];

      for (let i = 0; i < req.files.length; i++) {
        const file = req.files[i] as Express.Multer.File;
        try {
          const { url } = await photoStorage.uploadPhoto(file.buffer, file.originalname, file.mimetype);
          photoUrls.push(url);
        } catch (uploadErr) {
          console.error(`Error uploading photo ${i + 1}/${req.files.length} to GCS:`, uploadErr);
          // Keep going so a single bad file doesn't fail the whole batch
        }
      }

      if (photoUrls.length === 0) {
        return res.status(500).json({
          success: false,
          message: 'Failed to upload any photos to storage',
        });
      }

      // Update job with new photos
      const currentPhotos = type === 'before' ? job.beforePhotos || [] : job.afterPhotos || [];
      const updatedPhotos = [...currentPhotos, ...photoUrls];
      
      const updateData = type === 'before' 
        ? { beforePhotos: updatedPhotos }
        : { afterPhotos: updatedPhotos };

      await storage.updateJob(jobId, updateData);

      res.json({
        success: true,
        message: `Successfully uploaded ${photoUrls.length} ${type} photos`,
        photos: photoUrls,
        jobId
      });
    } catch (error) {
      // No cleanup needed for memory storage
      
      console.error('Error uploading job photos:', error);
      res.status(500).json({
        success: false,
        message: error instanceof Error ? error.message : 'Error uploading photos',
      });
    }
  });

