  // Update business settings
  app.put('/api/business-settings', requireAdmin, async (req: Request, res: Response) => {
    try {
      // Pre-process values to match Zod schema expectations before validation
      const rawBody = { ...req.body };

      // Timestamp fields: convert ISO strings → Date objects
      if (typeof rawBody.metricsStartDate === 'string' && rawBody.metricsStartDate) {
        rawBody.metricsStartDate = new Date(rawBody.metricsStartDate);
      } else if (rawBody.metricsStartDate === null || rawBody.metricsStartDate === '') {
        rawBody.metricsStartDate = null;
      }

      // Decimal fields: Drizzle maps them to z.string() — convert numbers → strings
      if (typeof rawBody.defaultGrossMarginPct === 'number') {
        rawBody.defaultGrossMarginPct = String(rawBody.defaultGrossMarginPct);
      }
      if (typeof rawBody.dailyRevenueTarget === 'number') {
        rawBody.dailyRevenueTarget = String(rawBody.dailyRevenueTarget);
      }
      if (typeof rawBody.defaultDepositValue === 'number') {
        rawBody.defaultDepositValue = String(rawBody.defaultDepositValue);
      }

      const validationResult = updateBusinessSettingsSchema.safeParse(rawBody);
      if (!validationResult.success) {
        console.error('Business settings validation error:', JSON.stringify(validationResult.error.errors, null, 2));
        return res.status(400).json({
          success: false,
          message: 'Validation error',
          errors: validationResult.error.errors,
        });
      }
      const validatedData = validationResult.data;
      
      // Filter out sensitive fields that should not be updated with masked values
      const cleanData = { ...validatedData };
      if (cleanData.servicem8ApiKey === '••••••••' || cleanData.servicem8ApiKey === '') {
        delete cleanData.servicem8ApiKey; // Don't update with mask or empty
      }
      
      const settings = await storage.updateBusinessSettings(cleanData);
      
      // Remove sensitive fields and add boolean indicators
      const { servicem8ApiKey, ...publicSettings } = settings;
      const safeSettings = {
        ...publicSettings,
        hasServicem8ApiKey: Boolean(servicem8ApiKey),
      };
      
      res.json({
        success: true,
        data: safeSettings,
        message: 'Settings updated successfully'
      });
    } catch (error) {
      // Handle validation errors properly
      if (error instanceof Error && 'issues' in error) { // ZodError check
        res.status(400).json({
          success: false,
          message: 'Validation failed',
          errors: (error as any).issues
        });
        return;
      }
      
      console.error('Error updating business settings:', error);
      res.status(500).json({
        success: false,
        message: 'Error updating business settings'
      });
    }
  });

