  // POST /api/mobile/calls/upload - Upload call recording from mobile app
  app.post('/api/mobile/calls/upload', requireApiKey, (req: Request, res: Response, next: express.NextFunction) => {
    // Handle multer errors explicitly
    audioUpload.single('audio')(req, res, (err) => {
      if (err) {
        if (err instanceof multer.MulterError) {
          if (err.code === 'LIMIT_FILE_SIZE') {
            return res.status(400).json({ 
              success: false, 
              message: 'Audio file is too large. Maximum size is 50MB.' 
            });
          }
          return res.status(400).json({ 
            success: false, 
            message: `File upload error: ${err.message}` 
          });
        }
        return res.status(400).json({ 
          success: false, 
          message: err.message || 'Invalid audio file' 
        });
      }
      next();
    });
  }, async (req: Request, res: Response) => {
    try {
      const file = req.file;
      if (!file) {
        return res.status(400).json({ 
          success: false, 
          message: 'No audio file uploaded' 
        });
      }

      // Validate required fields
      const { phoneNumber, direction, duration, status } = req.body;
      if (!phoneNumber || !direction) {
        return res.status(400).json({ 
          success: false, 
          message: 'Missing required fields: phoneNumber, direction' 
        });
      }

      // Create the recording URL (relative path that will be accessible via the server)
      const recordingUrl = `/uploads/recordings/${file.filename}`;

      // Create call record in database
      const callData = {
        phoneNumber,
        direction,
        status: status || 'answered',
        duration: duration ? parseInt(duration) : undefined,
        recordingUrl,
        customerId: req.body.customerId || undefined,
        leadId: req.body.leadId || undefined,
      };

      const validation = insertCallSchema.safeParse(callData);
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid call data',
          errors: validation.error.errors
        });
      }

      // Multer route (session-less: API-key auth) — the ALS tenant context is lost
      // behind busboy anyway, so stamp the insert from the API key's business.
      const callBusinessId = (req as any).apiKey?.businessId ?? req.session?.businessId;
      const call = await runWithBusiness(callBusinessId ?? undefined, () => storage.createCall(validation.data));

      res.json({ 
        success: true, 
        data: call,
        message: 'Call recording uploaded successfully' 
      });
    } catch (error) {
      console.error('Error uploading call recording:', error);
      res.status(500).json({ 
        success: false, 
        message: 'Error uploading call recording' 
      });
    }
  });

  // POST /api/mobile/calls/:callId/transcribe - Transcribe call recording using OpenAI Whisper
  app.post('/api/mobile/calls/:callId/transcribe', requireApiKey, async (req: Request, res: Response) => {
    try {
      const { callId } = req.params;
      
      if (!callId) {
        return res.status(400).json({ 
          success: false, 
          message: 'Call ID is required' 
        });
      }

      // Get the call record
      const call = await storage.getCallById(callId);
      if (!call) {
        return res.status(404).json({ 
          success: false, 
          message: 'Call not found' 
        });
      }

      // Check if already transcribed
      if (call.transcript) {
        return res.json({ 
          success: true, 
          data: { 
            callId: call.id,
            transcript: call.transcript,
            alreadyTranscribed: true 
          },
          message: 'Call already transcribed' 
        });
      }

      // Check if recording exists
      if (!call.recordingUrl) {
        return res.status(400).json({ 
          success: false, 
          message: 'Call has no recording to transcribe' 
        });
      }

      // Build the file path from the recording URL
      // Strip leading slash to prevent absolute path resolution
      const relativePath = call.recordingUrl.startsWith('/') 
        ? call.recordingUrl.substring(1) 
        : call.recordingUrl;
      const recordingPath = path.join(__dirname, '..', relativePath);
      
      // Check if file exists
      if (!fs.existsSync(recordingPath)) {
        return res.status(404).json({ 
          success: false, 
          message: 'Recording file not found on server' 
        });
      }

      // Transcribe using OpenAI Whisper
      console.log(`Transcribing call ${callId} from ${recordingPath}`);
      const transcription = await openai.audio.transcriptions.create({
        file: fs.createReadStream(recordingPath),
        model: 'whisper-1',
        language: 'en',
        response_format: 'text'
      });

      // Extract text from response (handles both string and object responses)
      const rawTranscriptText = typeof transcription === 'string' 
        ? transcription 
        : (transcription as any).text || String(transcription);

      // Capitalize names in transcript using GPT
      let transcriptText = rawTranscriptText;
      try {
        const capitalizationResponse = await openai.chat.completions.create({
          model: 'gpt-4o',
          messages: [
            {
              role: 'system',
              content: 'You are a text formatter. Your only job is to take transcribed text and properly capitalize all proper nouns (names of people, places, companies) while keeping everything else exactly as it is. Return ONLY the corrected text with no explanations or formatting.'
            },
            {
              role: 'user',
              content: rawTranscriptText
            }
          ],
          temperature: 0.1
        });
        
        transcriptText = capitalizationResponse.choices[0].message.content?.trim() || rawTranscriptText;
        console.log(`✅ Names capitalized in transcript`);
      } catch (capError) {
        console.warn('⚠️ Could not capitalize names, using raw transcript:', capError);
        transcriptText = rawTranscriptText;
      }

      // Update call record with transcript
      const updatedCall = await storage.updateCall(callId, {
        transcript: transcriptText
      });

      res.json({ 
        success: true, 
        data: {
          callId: updatedCall.id,
          transcript: updatedCall.transcript
        },
        message: 'Call transcribed successfully' 
      });
    } catch (error) {
      console.error('Error transcribing call:', error);
      res.status(500).json({ 
        success: false, 
        message: error instanceof Error ? error.message : 'Error transcribing call' 
      });
    }
  });

