  // POST /api/calls/:callId/create-job — manual conversion of a recorded call
  // into a job/lead, triggered from the "Create Job" button next to the
  // transcript in Communications Management. Re-runs GPT extraction on the
  // stored transcript to populate the job, since auto-creation is disabled.
  app.post('/api/calls/:callId/create-job', async (req: Request, res: Response) => {
    try {
      if (!req.session.employeeId) {
        return res.status(401).json({ success: false, message: 'Not authenticated' });
      }
      const { callId } = req.params;
      const call = await storage.getCall(callId);
      if (!call) {
        return res.status(404).json({ success: false, message: 'Call not found' });
      }
      const transcript = call.transcriptText || '';
      if (!transcript) {
        return res.status(400).json({ success: false, message: 'Call has no transcript yet — wait for transcription to finish' });
      }
      const callerPhone = call.phoneNumber || 'unknown';

      const businessId = req.session.businessId;
      if (businessId) {
        const ok = await usageMeter.guard('ai', businessId, 'call_to_job');
        if (!ok) return res.status(429).json({ success: false, message: 'Monthly AI limit reached — upgrade your plan or wait for the next billing cycle.' });
      }

      // Re-extract structured data from the transcript (same prompt as the
      // recording handler used to use). Cheap GPT call, gives us a fresh
      // extraction each time the staff member clicks the button.
      const extraction = await openai.chat.completions.create({
        model: 'gpt-4o',
        messages: [
          {
            role: 'system',
            content: `You are a data extraction assistant for a field-service business in New Zealand.
Extract structured job information from customer call transcripts.

Extract:
- customerName: Full name if mentioned
- customerPhone: Use "${callerPhone}"
- serviceType: One of [tree-removal, tree-pruning, stump-grinding, hedge-trimming, emergency, other]
- address: Full address if mentioned
- urgency: One of [emergency, urgent, normal, low]
- estimatedPrice: Number only if quoted (no $ sign)
- notes: Key details about the job

Return ONLY valid JSON, no markdown. If a field isn't mentioned, use null.`,
          },
          { role: 'user', content: transcript },
        ],
        response_format: { type: 'json_object' },
      });
      const jobData = JSON.parse(extraction.choices[0].message.content || '{}');

      // Resolve the customer this job belongs to. Priority:
      //   1. The customer the call is already linked to (authoritative).
      //   2. A customer whose phone/mobile matches the caller's number.
      //   3. A brand-new customer built from the transcript (unknown caller).
      // Match on the last 8 phone digits to ignore country-code variations
      // (021... vs +6421...). A manual "Create Job" click is the staff member
      // explicitly confirming this caller is whoever the call log attributed
      // the number to, so a phone match WINS over the transcript-spoken name
      // (which is often a different person merely mentioned on the call). The
      // spoken name only disambiguates when one number maps to several
      // customers.
      const normForCompare = (p: string | null | undefined) =>
        String(p || '').replace(/\D/g, '').slice(-8);
      const normName = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');
      const callerKey = normForCompare(callerPhone);
      const extractedName = String(jobData.customerName || '').trim();
      let customer: any = null;

      if (call.customerId) {
        customer = await storage.getCustomer(call.customerId) || null;
      }

      if (!customer && callerKey) {
        const allCustomers = await storage.getAllCustomers();
        const phoneMatches = allCustomers.filter(
          (c: any) =>
            (c.phone && normForCompare(c.phone) === callerKey) ||
            (c.mobile && normForCompare(c.mobile) === callerKey),
        );
        if (phoneMatches.length === 1) {
          customer = phoneMatches[0];
        } else if (phoneMatches.length > 1) {
          // Same number on multiple records — use the spoken name to pick the
          // right one, falling back to the first match.
          const en = normName(extractedName);
          customer =
            (en &&
              phoneMatches.find((c: any) => {
                const cn = normName(c.name || '');
                return cn && (cn === en || cn.includes(en) || en.includes(cn));
              })) ||
            phoneMatches[0];
        }
      }

      if (!customer) {
        customer = await storage.createCustomer({
          name: extractedName || `Caller ${callerPhone}`,
          phone: callerPhone,
          address: jobData.address || undefined,
          source: 'phone_call',
        });
      }

      // Build the job. job_number is NOT NULL and createJob does not
      // auto-assign it — fetch the next sequential number explicitly.
      // Prefer the resolved customer's name for the job contact; only fall back
      // to the transcript-spoken name (which is what a brand-new customer was
      // created from anyway).
      const nameParts = String(customer.name || jobData.customerName || '').trim().split(/\s+/);
      const jobContactFirstName = nameParts[0] || undefined;
      const jobContactLastName = nameParts.slice(1).join(' ') || undefined;
      const jobNumber = await storage.getNextJobNumber();
      const job = await storage.createJob({
        jobNumber,
        customerId: customer.id,
        status: 'lead',
        address: jobData.address || customer.address || 'TBD',
        serviceType: jobData.serviceType || 'other',
        priority: jobData.urgency === 'emergency' ? 'urgent' : 'normal',
        estimatedAmount: jobData.estimatedPrice ? String(jobData.estimatedPrice) : undefined,
        notes: jobData.notes || '',
        jobContactPhone: callerPhone,
        jobContactFirstName,
        jobContactLastName,
      });

      // Link the call to the new job, then drop a diary entry with the
      // recording + transcript so the audio is playable from the job card.
      await storage.updateCall(call.id, { jobId: job.id, customerId: customer.id });
      await storage.createJobDiaryEntry({
        jobId: job.id,
        entryType: 'call',
        title: '📞 Job Created from Phone Call',
        description: `Call from ${customer.name} (${callerPhone})\n\nTranscript:\n${transcript}`,
        authorName: 'Manual conversion',
        authorRole: 'system',
        tags: ['call', 'manual-conversion'],
        metadata: {
          recordingUrl: call.recordingUrl,
          transcription: transcript,
          extractedJobData: jobData,
        },
      });

      console.log(`✅ Job #${job.jobNumber} manually created from call ${call.id}`);
      if (businessId) await usageMeter.recordUsage('ai', businessId, { feature: 'call_to_job' });
      res.json({ success: true, data: { job, customer, extracted: jobData } });
    } catch (error) {
      console.error('Error creating job from call:', error);
      res.status(500).json({
        success: false,
        message: error instanceof Error ? error.message : 'Failed to create job',
      });
    }
  });

  // POST /api/mobile/calls/:callId/attach-to-job/:jobId - Attach call to existing job
  app.post('/api/mobile/calls/:callId/attach-to-job/:jobId', requireApiKey, async (req: Request, res: Response) => {
    try {
      const { callId, jobId } = req.params;
      
      if (!callId || !jobId) {
        return res.status(400).json({ 
          success: false, 
          message: 'Call ID and Job ID are required' 
        });
      }

      // Verify call and job exist
      const call = await storage.getCall(callId);
      if (!call) {
        return res.status(404).json({ 
          success: false, 
          message: 'Call not found' 
        });
      }

      const job = await storage.getJob(jobId);
      if (!job) {
        return res.status(404).json({ 
          success: false, 
          message: 'Job not found' 
        });
      }

      // Prepare diary entry data and validate before transaction
      const diaryContent = call.transcript 
        ? `Call recording and transcript from ${call.phoneNumber}\n\nTranscript:\n${call.transcript}`
        : `Call recording from ${call.phoneNumber}`;
      
      const diaryEntry = {
        jobId,
        entryType: 'note',
        title: `Phone Call - ${new Date(call.createdAt).toLocaleString()}`,
        description: diaryContent,
        authorName: 'Mobile App',
        authorRole: 'system',
      };
      const diaryValidation = insertJobDiaryEntrySchema.safeParse(diaryEntry);
      if (!diaryValidation.success) {
        return res.status(400).json({ 
          success: false, 
          message: 'Invalid diary entry data',
          errors: diaryValidation.error.errors 
        });
      }

      // Sequential because the neon-http driver does not support db.transaction().
      // If the diary insert fails after the call link succeeds, the call still
      // points at the job (the user-visible link they asked for) and a retry will
      // create the diary entry.
      const [updatedCall] = await db.update(schema.calls)
        .set({ jobId })
        .where(eq(schema.calls.id, callId))
        .returning();

      const [createdDiary] = await db.insert(schema.jobDiaryEntries)
        .values(withTenant(diaryValidation.data))
        .returning();

      res.json({
        success: true,
        data: {
          call: updatedCall,
          diaryEntry: createdDiary
        },
        message: 'Call attached to job successfully'
      });
    } catch (error) {
      console.error('Error attaching call to job:', error);
      res.status(500).json({ 
        success: false, 
        message: error instanceof Error ? error.message : 'Error attaching call to job' 
      });
    }
  });

