  // AI-powered dispatch board analyzer - provides insights on workload and days of work
  app.get('/api/analytics/dispatch-ai', async (req: Request, res: Response) => {
    try {
      // Get active jobs (work_order, scheduled, in_progress)
      const { jobs: allJobs } = await storage.getAllJobs({ limit: 999999 });
      // Active = work_order. 'scheduled' was retired as a status in 2026-05;
      // the conceptual bucket is now "work_order with a scheduledDate" vs
      // "work_order without one". Both still count as active.
      const activeJobs = allJobs.filter(job => job.status === 'work_order');

      // Get employees for crew count calculation
      const employees = await storage.getAllEmployees();

      // Calculate summary stats. workOrder = unscheduled work orders ready
      // to book in. scheduled = work orders that have a date set.
      const workOrderJobs = activeJobs.filter(j => !j.scheduledDate);
      const scheduledJobs = activeJobs.filter(j => !!j.scheduledDate);
      const inProgressJobs: typeof activeJobs = [];
      
      const totalValue = activeJobs.reduce((sum, job) => sum + parseFloat(job.totalAmount || '0'), 0);
      const totalEstimatedHours = activeJobs.reduce((sum, job) => sum + parseFloat(job.estimatedManHours || '0'), 0);
      
      // Assume 8 hours per crew day
      const hoursPerDay = 8;
      const activeCrewCount = employees.filter(e => e.role === 'crew' || e.role === 'climber' || e.role === 'groundsman').length || 1;
      const daysOfWork = totalEstimatedHours / (hoursPerDay * Math.max(activeCrewCount, 1));
      
      // Build job summaries for AI analysis
      const jobSummaries = activeJobs.slice(0, 50).map(job => ({
        jobNumber: job.jobNumber,
        title: job.title,
        status: job.status,
        value: job.totalAmount || '0',
        estimatedHours: job.estimatedManHours || '0',
        address: job.address,
        scheduledDate: job.scheduledDate
      }));
      
      // Build AI prompt
      const __idDispatch = getBusinessIdentity(await storage.getBusinessSettings());
      const prompt = `You are an AI assistant for a ${__idDispatch.discipline} business called ${__idDispatch.name}. Analyze the dispatch board data and provide a concise business insight summary.

DISPATCH BOARD DATA:
- Work Orders (ready to schedule): ${workOrderJobs.length} jobs worth $${workOrderJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0).toFixed(2)} NZD
- Scheduled Jobs: ${scheduledJobs.length} jobs worth $${scheduledJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0).toFixed(2)} NZD
- In Progress: ${inProgressJobs.length} jobs worth $${inProgressJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0).toFixed(2)} NZD
- Total Active Jobs: ${activeJobs.length}
- Total Pipeline Value: $${totalValue.toFixed(2)} NZD
- Total Estimated Hours: ${totalEstimatedHours.toFixed(1)} hours
- Active Crew Members: ${activeCrewCount}
- Estimated Days of Work: ${daysOfWork.toFixed(1)} days (at 8 hours/day with current crew)

JOB DETAILS (first 50):
${jobSummaries.map(j => `- Job #${j.jobNumber}: ${j.title} | ${j.status} | $${j.value} | ${j.estimatedHours}h${j.scheduledDate ? ` | Scheduled: ${j.scheduledDate}` : ''}`).join('\n')}

Provide a brief, actionable summary (3-4 sentences) covering:
1. How many days of work you have in the pipeline
2. The total value and what it means for the business
3. Any recommendations (e.g., "Consider hiring more crew" or "Good time to schedule more quotes")

Keep the tone professional but conversational. Use NZD for currency.`;

      // Call OpenAI
      const completion = await openai.chat.completions.create({
        model: "gpt-5",
        messages: [{ role: "user", content: prompt }],
        max_completion_tokens: 500
      });
      
      const aiInsight = completion.choices[0]?.message?.content || 'Unable to generate insights.';
      
      res.json({
        success: true,
        data: {
          summary: {
            workOrderCount: workOrderJobs.length,
            workOrderValue: workOrderJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0),
            scheduledCount: scheduledJobs.length,
            scheduledValue: scheduledJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0),
            inProgressCount: inProgressJobs.length,
            inProgressValue: inProgressJobs.reduce((s, j) => s + parseFloat(j.totalAmount || '0'), 0),
            totalJobs: activeJobs.length,
            totalValue,
            totalEstimatedHours,
            activeCrewCount,
            estimatedDaysOfWork: daysOfWork
          },
          aiInsight
        }
      });
    } catch (error) {
      console.error('Error generating dispatch AI insights:', error);
      res.status(500).json({ success: false, message: 'Error generating dispatch insights' });
    }
  });

  // Booked workload — jobs scheduled in a calendar week (Mon–Sun in NZ time)
  // or, for legacy callers, a rolling N-day window from today.
  app.get('/api/analytics/booked-workload', async (req: Request, res: Response) => {
    try {
      const periodParam = String(req.query.period || '');
      const validPeriods = ['this_week', 'next_week', 'week_after', 'next_month'] as const;
      type Period = typeof validPeriods[number];
      const period: Period | null = (validPeriods as readonly string[]).includes(periodParam)
        ? (periodParam as Period)
        : null;

      const requestedDays = parseInt(req.query.days as string, 10);
      const days = Number.isFinite(requestedDays)
        ? Math.max(1, Math.min(365, requestedDays))
        : 7;

      const nowNZ = toZonedTime(new Date(), 'Pacific/Auckland');
      let startNZ: Date;
      let endNZ: Date;

      if (period) {
        // dow: 0=Sun..6=Sat. We want Monday as week start, so days-since-Monday is (dow+6)%7.
        const dow = nowNZ.getDay();
        const daysSinceMonday = (dow + 6) % 7;
        const monday = new Date(nowNZ);
        monday.setDate(nowNZ.getDate() - daysSinceMonday);
        if (period === 'next_week') monday.setDate(monday.getDate() + 7);
        else if (period === 'week_after') monday.setDate(monday.getDate() + 14);
        const spanDays = period === 'next_month' ? 28 : 7;
        startNZ = monday;
        endNZ = new Date(monday);
        endNZ.setDate(monday.getDate() + spanDays - 1);
      } else {
        startNZ = nowNZ;
        endNZ = new Date(nowNZ);
        endNZ.setDate(endNZ.getDate() + days - 1);
      }

      const startStr = `${startNZ.getFullYear()}-${String(startNZ.getMonth() + 1).padStart(2, '0')}-${String(startNZ.getDate()).padStart(2, '0')}`;
      const endStr = `${endNZ.getFullYear()}-${String(endNZ.getMonth() + 1).padStart(2, '0')}-${String(endNZ.getDate()).padStart(2, '0')}`;

      const fromUTC = fromZonedTime(`${startStr}T00:00:00`, 'Pacific/Auckland');
      const toUTC = fromZonedTime(`${endStr}T23:59:59.999`, 'Pacific/Auckland');

      const [{ jobs: allJobs }, employees, allQuotes, allInvoices, allProposals, allProposalLineItems, allProposalChoices] = await Promise.all([
        storage.getAllJobs({ limit: 999999 }),
        storage.getAllEmployees(),
        storage.getAllQuotes(),
        storage.getAllInvoices(),
        storage.getAllProposals(),
        db.select().from(schema.proposalLineItems),
        db.select().from(schema.proposalLineItemChoices),
      ]);

      // "Booked" = anything on the calendar in this window, whether still to do
      // or already done. We exclude leads/quotes (never booked), cancelled/
      // unsuccessful (booking fell through), and archived (housekeeping) so the
      // total reflects work that actually was/is scheduled to happen.
      // 'scheduled' retired 2026-05 — work_order with a scheduledDate is
      // the new "booked" signal.
      const BOOKED_STATUSES = new Set([
        'work_order', 'completed', 'invoiced'
      ]);
      const bookedJobs = allJobs.filter(job => {
        if (!job.scheduledDate) return false;
        if (!BOOKED_STATUSES.has(job.status)) return false;
        const sched = new Date(job.scheduledDate);
        return sched >= fromUTC && sched <= toUTC;
      });

      // Fallback price lookup: proposal (line items or stored subtotal) → invoice sum → quote.
      // Proposals are the primary booking instrument; the Job Card reads proposal line
      // items regardless of proposal status (draft/sent/viewed/accepted) when the
      // proposal's stored subtotal is stale, so this report mirrors that priority.
      const invoicesByJob = new Map<string, number>();
      for (const inv of allInvoices) {
        if (!inv.jobId) continue;
        const amt = parseFloat(inv.amount || '0');
        if (amt > 0) invoicesByJob.set(inv.jobId, (invoicesByJob.get(inv.jobId) ?? 0) + amt);
      }

      // Sum each proposal's selected line items, ex-GST, mirroring the Job Card calc.
      const choicePriceById = new Map<string, number>();
      for (const c of allProposalChoices) {
        choicePriceById.set(c.id, parseFloat(c.price || '0'));
      }
      const proposalLineItemsExGst = new Map<string, number>();
      for (const li of allProposalLineItems) {
        if (li.selected === false) continue;
        let raw = 0;
        if (li.pricingType === 'choice' && li.selectedChoiceId) {
          raw = choicePriceById.get(li.selectedChoiceId) ?? 0;
        } else if (li.pricingType === 'fixed' && li.fixedPrice) {
          raw = parseFloat(li.fixedPrice || '0');
        } else {
          raw = parseFloat(li.totalPrice || '0');
        }
        if (!(raw > 0)) continue;
        const exGst = li.priceIncludesTax ? raw / 1.15 : raw;
        proposalLineItemsExGst.set(li.proposalId, (proposalLineItemsExGst.get(li.proposalId) ?? 0) + exGst);
      }

      // Most recent proposal per job, any status. Use stored subtotal if non-zero,
      // otherwise sum of selected line items (the Job Card's same fallback).
      const proposalsByJob = new Map<string, { amount: number; createdAt: number }>();
      for (const p of allProposals) {
        if (!p.jobId) continue;
        const stored = parseFloat(p.subtotal || '0');
        const computed = proposalLineItemsExGst.get(p.id) ?? 0;
        const amt = stored > 0 ? stored : computed;
        if (amt <= 0) continue;
        const created = p.createdAt ? new Date(p.createdAt).getTime() : 0;
        const existing = proposalsByJob.get(p.jobId);
        if (!existing || created > existing.createdAt) {
          proposalsByJob.set(p.jobId, { amount: Math.round(amt * 100) / 100, createdAt: created });
        }
      }
      const quotesByJob = new Map<string, { amount: number; createdAt: number }>();
      for (const q of allQuotes) {
        if (!q.jobId) continue;
        const amt = parseFloat(q.amount || '0');
        if (amt <= 0) continue;
        const created = q.createdAt ? new Date(q.createdAt).getTime() : 0;
        const existing = quotesByJob.get(q.jobId);
        if (!existing || created > existing.createdAt) {
          quotesByJob.set(q.jobId, { amount: amt, createdAt: created });
        }
      }

      // jobs.subtotal is reliably ex-GST; jobs.total_amount mixes ex- and inc-GST
      // depending on how the row was created. Prefer subtotal so the card stays ex-GST.
      const resolveValue = (j: typeof bookedJobs[number]): { value: number; source: 'job' | 'invoice' | 'proposal' | 'quote' | null } => {
        const subtotal = parseFloat(j.subtotal || '0');
        if (subtotal > 0) return { value: subtotal, source: 'job' };
        const direct = parseFloat(j.totalAmount || '0');
        if (direct > 0) return { value: direct, source: 'job' };
        // Proposal next: matches the Job Card display, which trusts proposal line
        // items even on draft/sent/viewed proposals when subtotal/totalAmount are 0.
        const proposalFallback = proposalsByJob.get(j.id)?.amount ?? 0;
        if (proposalFallback > 0) return { value: proposalFallback, source: 'proposal' };
        // totalIncludingGst as last-resort: sometimes the only price on legacy/imported
        // rows where subtotal/total_amount/proposal were never written. Strip GST.
        const incGst = parseFloat(j.totalIncludingGst || '0');
        if (incGst > 0) {
          const taxRate = parseFloat(j.taxRate || '15');
          const exGst = taxRate > 0 ? incGst / (1 + taxRate / 100) : incGst;
          return { value: Math.round(exGst * 100) / 100, source: 'job' };
        }
        const invFallback = invoicesByJob.get(j.id) ?? 0;
        if (invFallback > 0) return { value: invFallback, source: 'invoice' };
        const quoteFallback = quotesByJob.get(j.id)?.amount ?? 0;
        if (quoteFallback > 0) return { value: quoteFallback, source: 'quote' };
        return { value: 0, source: null };
      };

      const jobsList = bookedJobs.map(j => {
        const { value, source } = resolveValue(j);
        return {
          id: j.id,
          jobNumber: j.jobNumber,
          customerName: (j as any).customerName ?? null,
          title: j.title ?? null,
          status: j.status,
          scheduledDate: j.scheduledDate,
          estimatedManHours: parseFloat(j.estimatedManHours || '0'),
          value,
          valueSource: source,
        };
      });
      jobsList.sort((a, b) => {
        const av = a.scheduledDate ? new Date(a.scheduledDate).getTime() : 0;
        const bv = b.scheduledDate ? new Date(b.scheduledDate).getTime() : 0;
        return av - bv;
      });

      const totalValue = jobsList.reduce((sum, j) => sum + j.value, 0);
      const unpricedJobCount = jobsList.filter(j => j.value === 0).length;
      const totalHours = bookedJobs.reduce((sum, j) => sum + parseFloat(j.estimatedManHours || '0'), 0);

      const hoursPerDay = 8;
      const activeCrewCount = employees.filter(e =>
        e.role === 'crew' || e.role === 'climber' || e.role === 'groundsman'
      ).length || 1;
      const crewDays = totalHours / (hoursPerDay * Math.max(activeCrewCount, 1));

      const dayCount = Math.round((endNZ.getTime() - startNZ.getTime()) / 86_400_000) + 1;

      res.json({
        success: true,
        data: {
          period,
          days: period ? dayCount : days,
          from: startStr,
          to: endStr,
          jobCount: bookedJobs.length,
          totalValue,
          totalHours,
          activeCrewCount,
          crewDays,
          unpricedJobCount,
          jobs: jobsList,
        },
      });
    } catch (error) {
      console.error('Error fetching booked workload:', error);
      res.status(500).json({ success: false, message: 'Error fetching booked workload' });
    }
  });

  // Get service-level performance analytics (revenue and margin by service/material)
  app.get('/api/analytics/service-performance', async (req: Request, res: Response) => {
    try {
      // Get all paid invoices and completed jobs for revenue/margin analysis
      const allInvoices = await storage.getAllInvoices();
      const paidInvoices = allInvoices.filter(inv => inv.status === 'paid');
      
      // Get materials/services for name lookup
      const materials = await storage.getAllMaterials();
      const services = await storage.getAllServices();
      
      // Create lookup maps for quick reference
      const materialMap = new Map(materials.map(m => [m.id, m]));
      const serviceMap = new Map(services.map(s => [s.id, s]));
      
      // Aggregate by service/material from invoice line items
      const servicePerformance: Record<string, {
        id: string;
        name: string;
        type: 'material' | 'service';
        category: string;
        totalRevenue: number;
        totalCost: number;
        totalQuantity: number;
        invoiceCount: number;
        grossMargin: number;
        marginPercentage: number;
      }> = {};
      
      // Also track performance from all invoices (not just paid)
      for (const invoice of allInvoices) {
        const items = invoice.items as any[];
        if (!items || !Array.isArray(items)) continue;
        
        for (const item of items) {
          // Try to identify the service/material from the item
          let id = item.serviceId || item.materialId;
          let name = item.description || 'Unknown';
          let type: 'material' | 'service' = item.serviceId ? 'service' : 'material';
          let category = item.category || 'other';
          
          // Look up actual name from material/service tables
          if (item.serviceId && serviceMap.has(item.serviceId)) {
            const service = serviceMap.get(item.serviceId)!;
            name = service.name;
            category = service.category || category;
            type = 'service';
          } else if (item.materialId && materialMap.has(item.materialId)) {
            const material = materialMap.get(item.materialId)!;
            name = material.name;
            category = material.category || category;
            type = 'material';
          }
          
          // Use description as fallback ID if no service/material ID
          if (!id) {
            // Normalize description to create a pseudo-ID
            id = `desc:${(item.description || '').toLowerCase().trim().replace(/[^a-z0-9]/g, '-')}`;
            type = 'service'; // Assume service for unlinked items
          }
          
          const quantity = parseFloat(item.quantity?.toString() || '1');
          const revenue = parseFloat(item.amount?.toString() || item.total?.toString() || '0');
          const unitCost = parseFloat(item.unitCost?.toString() || '0');
          const totalCost = unitCost * quantity;
          
          if (!servicePerformance[id]) {
            servicePerformance[id] = {
              id,
              name,
              type,
              category,
              totalRevenue: 0,
              totalCost: 0,
              totalQuantity: 0,
              invoiceCount: 0,
              grossMargin: 0,
              marginPercentage: 0
            };
          }
          
          // Only count revenue from paid invoices
          if (invoice.status === 'paid') {
            servicePerformance[id].totalRevenue += revenue;
            servicePerformance[id].totalCost += totalCost;
            servicePerformance[id].totalQuantity += quantity;
            servicePerformance[id].invoiceCount += 1;
          }
        }
      }
      
      // Calculate margins
      const performanceArray = Object.values(servicePerformance)
        .filter(item => item.totalRevenue > 0 || item.invoiceCount > 0) // Only include items with data
        .map(item => {
          item.grossMargin = item.totalRevenue - item.totalCost;
          item.marginPercentage = item.totalRevenue > 0 
            ? ((item.totalRevenue - item.totalCost) / item.totalRevenue) * 100 
            : 0;
          return item;
        })
        .sort((a, b) => b.totalRevenue - a.totalRevenue); // Sort by revenue descending
      
      // Summary stats
      const totalRevenue = performanceArray.reduce((sum, item) => sum + item.totalRevenue, 0);
      const totalCost = performanceArray.reduce((sum, item) => sum + item.totalCost, 0);
      const overallMargin = totalRevenue > 0 ? ((totalRevenue - totalCost) / totalRevenue) * 100 : 0;
      
      res.json({ 
        success: true, 
        data: {
          services: performanceArray,
          summary: {
            totalRevenue,
            totalCost,
            grossMargin: totalRevenue - totalCost,
            marginPercentage: overallMargin,
            servicesTracked: performanceArray.length
          }
        }
      });
    } catch (error) {
      console.error('Error generating service performance analytics:', error);
      res.status(500).json({ success: false, message: 'Error generating service analytics' });
    }
  });

  // Unsuccessful jobs analytics - breakdown by reason
  app.get('/api/analytics/unsuccessful-jobs', async (req: Request, res: Response) => {
    try {
      const { jobs: allJobs } = await storage.getAllJobs({ limit: 999999 });
      
      // Filter to only unsuccessful jobs
      const unsuccessfulJobs = allJobs.filter(job => job.status === 'unsuccessful');
      
      // Reason labels for display
      const reasonLabels: Record<string, string> = {
        'price_too_high': 'Price too high',
        'went_competitor': 'Went with competitor',
        'changed_mind': 'Customer changed mind',
        'no_longer_needed': 'Job no longer needed',
        'scheduling': 'Scheduling issues',
        'no_response': 'No response from customer',
        'scope_change': 'Scope changed',
        'other': 'Other',
        'unspecified': 'Not specified'
      };
      
      // Group by reason
      const reasonCounts: Record<string, number> = {};
      const reasonValues: Record<string, number> = {}; // Potential revenue lost
      const recentUnsuccessful: any[] = [];
      
      unsuccessfulJobs.forEach(job => {
        const reason = job.unsuccessfulReason || 'unspecified';
        reasonCounts[reason] = (reasonCounts[reason] || 0) + 1;
        
        // Add up potential revenue lost (from quotes/line items)
        const jobValue = parseFloat(job.totalAmount || '0') || parseFloat(job.totalIncludingGst || '0') || 0;
        reasonValues[reason] = (reasonValues[reason] || 0) + jobValue;
        
        // Track recent unsuccessful jobs (last 30 days)
        if (job.unsuccessfulDate) {
          const thirtyDaysAgo = new Date();
          thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
          if (new Date(job.unsuccessfulDate) > thirtyDaysAgo) {
            recentUnsuccessful.push({
              id: job.id,
              jobNumber: job.jobNumber,
              title: job.title,
              reason: job.unsuccessfulReason,
              reasonLabel: reasonLabels[job.unsuccessfulReason || 'unspecified'] || job.unsuccessfulReason,
              notes: job.unsuccessfulNotes,
              date: job.unsuccessfulDate,
              potentialValue: jobValue
            });
          }
        }
      });
      
      // Calculate monthly trends (last 6 months)
      const monthlyTrends: { month: string; count: number; value: number }[] = [];
      const now = new Date();
      
      for (let i = 5; i >= 0; i--) {
        const monthStart = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const monthEnd = new Date(now.getFullYear(), now.getMonth() - i + 1, 0);
        const monthName = monthStart.toLocaleString('en-NZ', { month: 'short', year: '2-digit' });
        
        const monthJobs = unsuccessfulJobs.filter(job => {
          if (!job.unsuccessfulDate) return false;
          const date = new Date(job.unsuccessfulDate);
          return date >= monthStart && date <= monthEnd;
        });
        
        const totalValue = monthJobs.reduce((sum, job) => {
          return sum + (parseFloat(job.totalAmount || '0') || parseFloat(job.totalIncludingGst || '0') || 0);
        }, 0);
        
        monthlyTrends.push({
          month: monthName,
          count: monthJobs.length,
          value: totalValue
        });
      }
      
      // Build response with breakdown by reason
      const byReason = Object.keys(reasonLabels).filter(key => reasonCounts[key] > 0).map(reason => ({
        reason,
        label: reasonLabels[reason] || reason,
        count: reasonCounts[reason] || 0,
        potentialRevenueLost: reasonValues[reason] || 0,
        percentage: unsuccessfulJobs.length > 0 
          ? Math.round((reasonCounts[reason] || 0) / unsuccessfulJobs.length * 100) 
          : 0
      })).sort((a, b) => b.count - a.count);
      
      // Calculate totals
      const totalPotentialRevenueLost = Object.values(reasonValues).reduce((sum, val) => sum + val, 0);
      
      res.json({
        success: true,
        data: {
          totalUnsuccessful: unsuccessfulJobs.length,
          totalPotentialRevenueLost,
          byReason,
          monthlyTrends,
          recentUnsuccessful: recentUnsuccessful.slice(0, 10) // Last 10 recent ones
        }
      });
    } catch (error) {
      console.error('Error generating unsuccessful jobs analytics:', error);
      res.status(500).json({ success: false, message: 'Error generating unsuccessful jobs analytics' });
    }
  });

  // Export analytics data as CSV
  app.get('/api/analytics/export/:type', async (req: Request, res: Response) => {
    try {
      const { type } = req.params;
      const { format = 'csv' } = req.query;

      let data: any;
      let filename: string;

      switch (type) {
        case 'dashboard':
          const jobs = await storage.getAllJobs();
          const customers = await storage.getAllCustomers();
          const quotes = await storage.getAllQuotes();
          const equipment = await storage.getAllEquipment();
          data = await businessIntelligenceService.calculateDashboardStats(jobs, customers, quotes, equipment);
          filename = `dashboard_export_${new Date().toISOString().split('T')[0]}.csv`;
          break;
          
        case 'revenue':
          const revenueJobs = await storage.getAllJobs();
          const revenueCustomers = await storage.getAllCustomers();
          data = await businessIntelligenceService.calculateRevenueAnalytics(revenueJobs, revenueCustomers);
          filename = `revenue_export_${new Date().toISOString().split('T')[0]}.csv`;
          break;
          
        default:
          return res.status(400).json({ success: false, message: 'Invalid export type' });
      }

      if (format === 'csv') {
        // Convert data to CSV format
        const csv = Object.entries(data)
          .map(([key, value]) => `${key},${value}`)
          .join('\n');
        
        res.setHeader('Content-Type', 'text/csv');
        res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
        res.send(`Metric,Value\n${csv}`);
      } else {
        res.json({ success: true, data, filename });
      }
    } catch (error) {
      console.error('Error exporting analytics data:', error);
      res.status(500).json({ success: false, message: 'Error exporting analytics data' });
    }
  });

