  // Get compliance dashboard analytics
  app.get('/api/compliance/analytics', async (req: Request, res: Response) => {
    try {
      const requirements = await storage.getAllComplianceRequirements();
      const records = await storage.getAllComplianceRecords();

      const now = new Date();
      const overdueRequirements = requirements.filter(r => new Date(r.nextDue) < now && r.status !== 'completed');
      const upcomingRequirements = requirements.filter(r => {
        const dueDate = new Date(r.nextDue);
        const daysUntilDue = Math.ceil((dueDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
        return daysUntilDue <= 30 && daysUntilDue > 0 && r.status !== 'completed';
      });

      const analytics = {
        totalRequirements: requirements.length,
        pendingRequirements: requirements.filter(r => r.status === 'pending').length,
        overdueRequirements: overdueRequirements.length,
        upcomingRequirements: upcomingRequirements.length,
        completedThisMonth: records.filter(r => {
          const completedDate = new Date(r.completedAt);
          return completedDate.getMonth() === now.getMonth() && 
                 completedDate.getFullYear() === now.getFullYear();
        }).length,
        averageComplianceScore: requirements.filter(r => r.complianceScore).length > 0 
          ? Math.round(requirements.filter(r => r.complianceScore).reduce((sum, r) => sum + (r.complianceScore || 0), 0) / requirements.filter(r => r.complianceScore).length)
          : 0,
        requirementsByCategory: requirements.reduce((acc: any, req) => {
          acc[req.category] = (acc[req.category] || 0) + 1;
          return acc;
        }, {}),
        requirementsByStatus: requirements.reduce((acc: any, req) => {
          acc[req.status] = (acc[req.status] || 0) + 1;
          return acc;
        }, {}),
      };

      res.json({
        success: true,
        data: analytics,
        message: 'Compliance analytics retrieved successfully'
      });
    } catch (error) {
      console.error('Error getting compliance analytics:', error);
      res.status(500).json({
        success: false,
        message: 'Error retrieving compliance analytics'
      });
    }
  });

  // ========================================
  // PROPOSAL MANAGEMENT ROUTES
  // ========================================

  // Get accepted proposals for drill-down analytics
  app.get('/api/proposals-accepted', async (req: Request, res: Response) => {
    try {
      const { from, to } = req.query;
      
      // Parse dates as NZ timezone
      let fromDate: Date | undefined;
      let toDate: Date | undefined;
      
      if (from && typeof from === 'string') {
        fromDate = fromZonedTime(`${from}T00:00:00`, 'Pacific/Auckland');
      }
      if (to && typeof to === 'string') {
        toDate = fromZonedTime(`${to}T23:59:59.999`, 'Pacific/Auckland');
      }
      
      // Get all proposals and filter to accepted ones
      const allProposals = await storage.getAllProposals();
      const acceptedProposals = allProposals.filter(p => p.status === 'accepted');
      
      // Filter by date range if provided (using accepted_at or sent_date)
      let filteredProposals = acceptedProposals;
      if (fromDate || toDate) {
        filteredProposals = acceptedProposals.filter(p => {
          const acceptedDate = p.acceptedAt ? new Date(p.acceptedAt) : (p.sentDate ? new Date(p.sentDate) : null);
          if (!acceptedDate) return false;
          if (fromDate && acceptedDate < fromDate) return false;
          if (toDate && acceptedDate > toDate) return false;
          return true;
        });
      }
      
      // Fetch job and customer info for each proposal
      const enrichedProposals = await Promise.all(
        filteredProposals.map(async (proposal) => {
          let jobNumber: string | undefined;
          let customerName: string | undefined;
          let title: string | undefined;
          
          if (proposal.jobId) {
            const job = await storage.getJobById(proposal.jobId);
            if (job) {
              jobNumber = job.jobNumber?.toString();
              title = job.title || undefined;
              if (job.customerId) {
                const customer = await storage.getCustomerById(job.customerId);
                customerName = customer?.name || undefined;
              }
            }
          } else if (proposal.customerId) {
            const customer = await storage.getCustomerById(proposal.customerId);
            customerName = customer?.name || undefined;
          }
          
          // proposal.totalAmount is inc-GST; strip GST so the internal metrics drilldown
          // reconciles with the ex-GST revenue tiles on the Business Metrics page.
          const amountExGst = (parseFloat(proposal.totalAmount?.toString() || '0') / 1.15).toFixed(2);
          return {
            id: proposal.id,
            jobId: proposal.jobId,
            jobNumber,
            customerName,
            amount: amountExGst,
            sentDate: proposal.sentDate,
            acceptedDate: proposal.acceptedAt,
            title
          };
        })
      );
      
      res.json({ success: true, data: enrichedProposals });
    } catch (error) {
      console.error('Error fetching accepted proposals:', error);
      res.status(500).json({ success: false, message: 'Error fetching accepted proposals' });
    }
  });

  // Get all proposals
  app.get('/api/proposals', async (req: Request, res: Response) => {
    try {
      const { customerId, quoteId, jobId, includeSections } = req.query;
      
      let proposals;
      if (customerId) {
        proposals = await storage.getProposalsByCustomer(customerId as string);
      } else if (quoteId) {
        proposals = await storage.getProposalsByQuote(quoteId as string);
      } else if (jobId) {
        proposals = await storage.getProposalsByJob(jobId as string);
      } else {
        proposals = await storage.getAllProposals();
      }

      // Only fetch sections and line items if explicitly requested
      if (includeSections === 'true') {
        // Batch fetch all sections and line items for all proposals in just 2 queries
        const proposalIds = proposals.map(p => p.id);
        
        // Fetch all sections and line items in parallel (2 bulk queries total)
        const [allSections, allLineItems] = await Promise.all([
          storage.getProposalSectionsByProposalIds(proposalIds),
          storage.getProposalLineItemsByProposalIds(proposalIds)
        ]);

        // Group sections and line items by proposal ID
        const sectionsByProposalId = new Map<string, any[]>();
        const lineItemsByProposalId = new Map<string, any[]>();
        
        allSections.forEach(section => {
          if (!sectionsByProposalId.has(section.proposalId)) {
            sectionsByProposalId.set(section.proposalId, []);
          }
          sectionsByProposalId.get(section.proposalId)!.push(section);
        });
        
        allLineItems.forEach(item => {
          if (!lineItemsByProposalId.has(item.proposalId)) {
            lineItemsByProposalId.set(item.proposalId, []);
          }
          lineItemsByProposalId.get(item.proposalId)!.push(item);
        });

        // Combine the data
        const proposalsWithData = proposals.map(proposal => {
          const sections = sectionsByProposalId.get(proposal.id) || [];
          const lineItems = lineItemsByProposalId.get(proposal.id) || [];

          // Attach line items to their sections, map content → description, and images → photos
          const sectionsWithLineItems = sections.map(section => ({
            ...section,
            description: section.content || '',
            photos: (Array.isArray(section.images) ? section.images : []).map((url: string) => {
              const filename = url.split('/').pop() || 'photo';
              const thumbnailUrl = url.includes('/objects/photos/')
                ? url.replace(/\/([^/]+)\.(jpg|jpeg|png|webp)$/i, '/thumb_$1.webp')
                : url;
              return {
                id: `photo-${filename}`,
                url,
                thumbnailUrl,
                filename,
                type: 'before' as const,
                category: 'documentation' as const,
                capturedAt: new Date().toISOString(),
              };
            }),
            lineItems: lineItems.filter(item => item.sectionId === section.id)
          }));

          return {
            ...proposal,
            sections: sectionsWithLineItems
          };
        });

        res.json({
          success: true,
          data: proposalsWithData,
          count: proposalsWithData.length,
          message: 'Proposals retrieved successfully'
        });
      } else {
        res.json({
          success: true,
          data: proposals,
          count: proposals.length,
          message: 'Proposals retrieved successfully'
        });
      }
    } catch (error) {
      console.error('Error fetching proposals:', error);
      res.status(500).json({
        success: false,
        message: 'Error fetching proposals'
      });
    }
  });

  // Get proposal with customer and template (optimized for public viewing)
  // IMPORTANT: This must come BEFORE the generic /:id route
  app.get('/api/proposals/:id/public', async (req: Request, res: Response) => {
    try {
      const proposal = await storage.getProposal(req.params.id);
      if (!proposal) {
        return res.status(404).json({
          success: false,
          message: 'Proposal not found'
        });
      }
      
      // Fetch all data in parallel for speed
      const [sections, allLineItems, customer, job, template] = await Promise.all([
        storage.getProposalSectionsByProposal(proposal.id),
        storage.getProposalLineItemsByProposal(proposal.id),
        proposal.customerId ? storage.getCustomer(proposal.customerId) : Promise.resolve(null),
        proposal.jobId ? storage.getJob(proposal.jobId) : Promise.resolve(null),
        // Scope the branding template to the proposal's OWNING tenant — this is a
        // public, session-less route, so the unscoped lookup returns Treemarkables'
        // template for every tenant's customer (cross-tenant branding leak).
        storage.getDefaultDocumentTemplateForBusiness(proposal.businessId, 'proposal')
      ]);

      // Fetch choices for all line items in parallel
      const lineItemsWithChoices = await Promise.all(
        allLineItems.map(async (item) => {
          const choices = await storage.getProposalLineItemChoicesByLineItem(item.id);
          return {
            ...item,
            choices: choices || []
          };
        })
      );
      
      // Map images → photos and attach line items with choices to each section
      const sectionsWithPhotosAndLineItems = sections.map(section => ({
        ...section,
        description: section.content, // Map content to description for frontend
        photos: (Array.isArray(section.images) ? section.images : []).map((url: string) => {
          // Generate thumbnail URL: /objects/photos/filename.jpg → /objects/photos/thumb_filename.webp
          const filename = url.split('/').pop() || 'photo';
          const thumbnailUrl = url.includes('/objects/photos/') 
            ? url.replace(/\/([^/]+)\.(jpg|jpeg|png|webp)$/i, '/thumb_$1.webp')
            : url;
          
          return {
            id: `photo-${Date.now()}-${Math.random()}`,
            url,
            thumbnailUrl,
            filename,
            type: 'before' as const,
            category: 'documentation' as const,
            capturedAt: new Date().toISOString(),
          };
        }),
        lineItems: lineItemsWithChoices.filter(item => item.sectionId === section.id)
      }));

      // Use template or fallback. Company fields are left BLANK (not Treemarkables)
      // so a tenant with no configured template never shows another business's
      // details — the tenant-scoped lookup above already supplies TM's own template.
      const finalTemplate = template || {
        id: 'default',
        name: 'Default Template',
        type: 'proposal',
        companyName: '',
        companyPhone: '',
        companyEmail: '',
        companyAddress: '',
        paymentTerms: 'This proposal is valid for 30 days from the date above. Payment due within 7 days of acceptance.',
        gstNumber: ''
      };
      
      // Return combined data in one response
      res.json({
        success: true,
        data: {
          proposal: {
            ...proposal,
            blockConfig: (proposal as any).blockConfig ?? schema.DEFAULT_PROPOSAL_BLOCKS,
            sections: sectionsWithPhotosAndLineItems,
          },
          customer,
          job,
          template: finalTemplate
        }
      });
    } catch (error) {
      console.error('Error fetching proposal public data:', error);
      res.status(500).json({
        success: false,
        message: 'Error fetching proposal'
      });
    }
  });

  // Get single proposal
  app.get('/api/proposals/:id', async (req: Request, res: Response) => {
    try {
      const proposal = await storage.getProposal(req.params.id);
      if (!proposal) {
        return res.status(404).json({
          success: false,
          message: 'Proposal not found'
        });
      }
      
      // Get proposal sections and all line items in parallel
      const [sections, allLineItems] = await Promise.all([
        storage.getProposalSectionsByProposal(proposal.id),
        storage.getProposalLineItemsByProposal(proposal.id),
      ]);
      
      // Fetch choices for each line item
      const lineItemsWithChoices = await Promise.all(
        allLineItems.map(async (item) => {
          const choices = await storage.getProposalLineItemChoicesByLineItem(item.id);
          return { ...item, choices: choices || [] };
        })
      );

      const mapPhotos = (images: string[] | unknown) =>
        (Array.isArray(images) ? images : []).map((url: string) => ({
          id: `photo-${Date.now()}-${Math.random()}`,
          url,
          filename: url.split('/').pop() || 'photo',
          type: 'before' as const,
          category: 'documentation' as const,
          capturedAt: new Date().toISOString(),
        }));

      // Helper: map raw job lineItems JSONB entries to the shape ProposalTemplate expects
      const mapJobItems = (rawItems: any[]): any[] =>
        rawItems.map((item: any, i: number) => {
          const qty = parseFloat(String(item.quantity ?? 1)) || 1;
          const rawTotal = parseFloat(String(item.totalPrice ?? item.total ?? item.price ?? 0)) || 0;
          const rawUnit = parseFloat(String(item.unitPrice ?? item.price ?? 0));
          const unitPrice = rawUnit || (rawTotal > 0 ? rawTotal / qty : 0);
          const totalPrice = rawTotal || (qty * unitPrice);
          return {
            id: item.id || `synth-item-${i}`,
            description: item.description || item.name || '',
            quantity: qty,
            unitPrice,
            totalPrice,
            unit: item.unit || 'each',
            category: item.category || item.itemCode || '',
            isOptional: item.isOptional || false,
            selected: true,
            pricingType: item.pricingType || 'normal',
            choices: item.choices || [],
            priceIncludesTax: item.priceIncludesTax || false,
            fixedPrice: item.fixedPrice ? parseFloat(String(item.fixedPrice)) : undefined,
            sortOrder: i,
          };
        });

      let sectionsWithPhotosAndLineItems: any[];

      if (allLineItems.length === 0 && proposal.jobId) {
        // No proposal_line_items saved yet — fall back to the job's lineItems JSONB
        const job = await storage.getJob(proposal.jobId);
        const rawJobItems: any[] = Array.isArray((job as any)?.lineItems) ? (job as any).lineItems : [];
        const mappedJobItems = mapJobItems(rawJobItems);

        if (sections.length === 0) {
          // No builder sections at all — synthesise everything from the job
          const builtSections: any[] = [];
          const desc = (job as any)?.description || '';
          builtSections.push({
            id: 'synth-desc',
            title: (job as any)?.serviceType || 'Job Description',
            description: desc,
            photos: [],
            lineItems: [],
            sortOrder: 0,
            sectionType: 'fixed',
          });
          if (mappedJobItems.length > 0) {
            builtSections.push({
              id: 'synth-items',
              title: 'Line Items',
              description: '',
              photos: [],
              lineItems: mappedJobItems,
              sortOrder: 1,
              sectionType: 'fixed',
            });
          }
          sectionsWithPhotosAndLineItems = builtSections;
        } else {
          // Sections exist but have no line items — inject job items into the first
          // section whose title / type looks like a "line items" section.
          let injected = false;
          sectionsWithPhotosAndLineItems = sections.map((section, idx) => {
            const normType = ((section as any).sectionType || '').toLowerCase();
            const normTitle = (section.title || '').toLowerCase();
            const isLineItemsSection =
              normType === 'lineitems' || normType === 'pricing' ||
              normTitle.includes('line item') || normTitle === 'items' ||
              normTitle === 'pricing' || normTitle === 'services' || normTitle === 'quote';

            if (!injected && isLineItemsSection && mappedJobItems.length > 0) {
              injected = true;
              return {
                ...section,
                description: section.content || '',
                photos: mapPhotos((section.images || []) as string[]),
                lineItems: mappedJobItems,
                sectionType: 'fixed',
              };
            }
            return {
              ...section,
              description: section.content || '',
              photos: mapPhotos((section.images || []) as string[]),
              lineItems: [],
              sectionType: normType === 'custom' ? 'fixed' : (normType || 'fixed'),
            };
          });

          // Only synthesise a section if the proposal has no sections at all for line items
          // (don't append one if the user intentionally removed the line-items block)
        }
      } else {
        // Normal path: builder-saved sections with their own line items
        sectionsWithPhotosAndLineItems = sections.map(section => {
          const normType = ((section as any).sectionType || '').toLowerCase();
          return {
            ...section,
            description: section.content || '',
            photos: mapPhotos((section.images || []) as string[]),
            lineItems: lineItemsWithChoices.filter(item => item.sectionId === section.id),
            sectionType: normType === 'custom' ? 'fixed' : (normType || 'fixed'),
          };
        });
      }
      
      res.json({
        success: true,
        data: {
          ...proposal,
          blockConfig: (proposal as any).blockConfig ?? schema.DEFAULT_PROPOSAL_BLOCKS,
          sections: sectionsWithPhotosAndLineItems,
        },
      });
    } catch (error) {
      console.error('Error fetching proposal:', error);
      res.status(500).json({
        success: false,
        message: 'Error fetching proposal'
      });
    }
  });

  // Create new proposal
  app.post('/api/proposals', async (req: Request, res: Response) => {
    try {
      console.log('🚀 CREATE PROPOSAL REQUEST - Status from frontend:', req.body.status);
      
      // Auto-generate proposalNumber if not provided
      const proposalData = {
        ...req.body,
        proposalNumber: req.body.proposalNumber || `PROP-${Date.now()}`,
      };
      
      console.log('📋 Proposal data before validation - Status:', proposalData.status);
      
      const validatedData = insertProposalSchema.parse(proposalData);
      console.log('✅ Validated data - Status:', validatedData.status);
      
      const proposal = await storage.createProposal(validatedData);
      console.log('💾 Created proposal - Status:', proposal.status, 'ID:', proposal.id);
      
      // Save proposal sections and line items if provided
      if (req.body.sections && Array.isArray(req.body.sections)) {
        // NOTE: Do NOT write section[0].description back into job.description here.
        // The proposal builder seeds section[0] from job.description ONCE on open and
        // never refreshes it, so any in-flight edits the user makes on the job card
        // after the builder mounts get clobbered by the stale captured value when
        // they hit Send. Job description is the source of truth — proposal sections
        // stay in the proposal.

        for (const section of req.body.sections) {
          // Create section
          const createdSection = await storage.createProposalSection({
            proposalId: proposal.id,
            sectionType: section.sectionType || 'fixed',
            title: section.title || 'Untitled Section',
            content: section.description || '',
            images: section.photos?.map((p: any) => p.url) || [],
            sortOrder: section.sortOrder || 0,
            isVisible: true
          });
          
          // Create line items for this section
          if (section.lineItems && Array.isArray(section.lineItems)) {
            for (let i = 0; i < section.lineItems.length; i++) {
              const item = section.lineItems[i];
              const createdItem = await storage.createProposalLineItem({
                proposalId: proposal.id,
                sectionId: createdSection.id,
                sourceType: 'fixed',
                sourceId: null,
                description: item.description || '',
                quantity: item.quantity?.toString() || '1',
                unitPrice: item.unitPrice?.toString() || '0',
                totalPrice: item.totalPrice?.toString() || '0',
                unit: item.unit || 'each',
                category: item.category,
                notes: item.notes,
                sortOrder: i,
                isOptional: item.isOptional || false,
                pricingType: item.pricingType || 'normal',
                selectedChoiceId: item.selectedChoiceId,
                fixedPrice: item.fixedPrice?.toString(),
                selected: item.selected !== false,
                priceIncludesTax: item.priceIncludesTax || false
              });
              
              // Create choices for this line item if they exist
              if (item.choices && Array.isArray(item.choices)) {
                for (let j = 0; j < item.choices.length; j++) {
                  const choice = item.choices[j];
                  await storage.createProposalLineItemChoice({
                    lineItemId: createdItem.id,
                    label: choice.label || '',
                    description: choice.description,
                    price: choice.price?.toString() || '0',
                    isDefault: choice.isDefault || false,
                    sortOrder: j
                  });
                }
              }
            }
          }
        }
      }
      
      // Note: Diary entries are only created when proposal is SENT (via email/SMS)
      // not when it's saved/created as a draft to prevent duplicate entries
      
      // Recompute subtotal server-side from actual stored line items (authoritative)
      // This prevents frontend calculation bugs from corrupting the stored value
      try {
        const storedItems = await storage.getProposalLineItemsByProposal(proposal.id);
        const storedSections = await storage.getProposalSectionsByProposal(proposal.id);
        // Build set of optional section IDs — items in these sections are excluded from the total
        const optionalSectionIds = new Set(
          storedSections
            .filter(s => s.sectionType === 'optional' || s.sectionType === 'multipleChoice')
            .map(s => s.id)
        );
        const taxRate = parseFloat(req.body.taxRate || '15') / 100;
        const discountAmt = parseFloat(req.body.discountAmount || '0') || 0;
        let recomputedSubtotal = 0;
        for (const item of storedItems) {
          const inOptionalSection = optionalSectionIds.has(item.sectionId || '');
          if (item.selected !== false && !item.isOptional && !inOptionalSection) {
            const price = parseFloat(item.totalPrice?.toString() || '0') || 0;
            recomputedSubtotal += item.priceIncludesTax ? price / (1 + taxRate) : price;
          }
        }
        // discountAmount arrives as the pre-computed dollar discount the
        // builder already applied (it always sends discountValue in dollars,
        // regardless of discountType). Subtract it directly — matching the
        // accept path and the customer-facing renderers.
        const discountValue = discountAmt;
        const subtotalAfterDiscount = Math.max(0, recomputedSubtotal - discountValue);
        const recomputedGst = subtotalAfterDiscount * taxRate;
        const recomputedTotal = subtotalAfterDiscount + recomputedGst;
        // Update proposal with correct values
        await storage.updateProposal(proposal.id, {
          subtotal: parseFloat(recomputedSubtotal.toFixed(2)),
          gstAmount: parseFloat(recomputedGst.toFixed(2)),
          totalAmount: parseFloat(recomputedTotal.toFixed(2)),
        });
        // Sync correct values to job
        if (proposal.jobId && recomputedSubtotal > 0) {
          await storage.updateJob(proposal.jobId, {
            subtotal: recomputedSubtotal.toFixed(2),
            totalAmount: recomputedSubtotal.toFixed(2),
            gstAmount: recomputedGst.toFixed(2),
            totalIncludingGst: recomputedTotal.toFixed(2)
          });
          console.log('✅ Synced job prices from recomputed line items (CREATE):', { subtotal: recomputedSubtotal.toFixed(2), gst: recomputedGst.toFixed(2), total: recomputedTotal.toFixed(2) });
        }
      } catch (error) {
        console.error('❌ Error recomputing/syncing job prices (CREATE):', error);
      }
      
      res.status(201).json({
        success: true,
        data: proposal,
        message: 'Proposal created successfully'
      });
    } catch (error: any) {
      console.error('Error creating proposal:', error);
      
      if (error.name === 'ZodError') {
        return res.status(400).json({
          success: false,
          message: 'Invalid proposal data',
          errors: error.errors
        });
      }
      
      res.status(500).json({
        success: false,
        message: 'Error creating proposal'
      });
    }
  });

  // Update proposal
  app.put('/api/proposals/:id', async (req: Request, res: Response) => {
    try {
      console.log('📝 PUT proposal request body keys:', Object.keys(req.body));
      console.log('📝 PUT proposal sections:', req.body.sections);
      
      const validatedData = updateProposalSchema.parse(req.body);
      const proposal = await storage.updateProposal(req.params.id, validatedData);
      
      // Delete existing sections and recreate them (simpler than updating)
      if (req.body.sections && Array.isArray(req.body.sections)) {
        console.log('📝 PUT proposal - updating sections:', {
          proposalId: proposal.id,
          sectionCount: req.body.sections.length,
          sections: req.body.sections.map((s: any) => ({
            title: s.title,
            lineItemCount: s.lineItems?.length || 0,
            lineItems: s.lineItems
          }))
        });
        
        // First, delete all existing sections for this proposal
        const existingSections = await storage.getProposalSectionsByProposal(proposal.id);
        for (const section of existingSections) {
          await storage.deleteProposalSection(section.id);
        }

        // NOTE: Do NOT write section[0].description back into job.description here —
        // see matching comment in POST /api/proposals. Job description is the source
        // of truth; proposal sections stay in the proposal.

        // Now create new sections
        for (const section of req.body.sections) {
          // Create section
          const createdSection = await storage.createProposalSection({
            proposalId: proposal.id,
            sectionType: section.sectionType || 'fixed',
            title: section.title || 'Untitled Section',
            content: section.description || '',
            images: section.photos?.map((p: any) => p.url) || [],
            sortOrder: section.sortOrder || 0,
            isVisible: true
          });
          
          console.log(`  ✅ Created section ${createdSection.id}: ${section.title}`);
          
          // Create line items for this section
          if (section.lineItems && Array.isArray(section.lineItems)) {
            console.log(`  📋 Section has ${section.lineItems.length} line items to create`);
            for (let i = 0; i < section.lineItems.length; i++) {
              const item = section.lineItems[i];
              console.log(`    Creating line item ${i + 1}:`, item.description);
              console.log(`    📊 priceIncludesTax from frontend:`, item.priceIncludesTax, `(type: ${typeof item.priceIncludesTax})`);
              const lineItemData = {
                proposalId: proposal.id,
                sectionId: createdSection.id,
                sourceType: 'fixed',
                sourceId: null,
                description: item.description || '',
                quantity: item.quantity?.toString() || '1',
                unitPrice: item.unitPrice?.toString() || '0',
                totalPrice: item.totalPrice?.toString() || '0',
                unit: item.unit || 'each',
                category: item.category,
                notes: item.notes,
                sortOrder: i,
                isOptional: item.isOptional || false,
                pricingType: item.pricingType || 'normal',
                selectedChoiceId: item.selectedChoiceId,
                fixedPrice: item.fixedPrice?.toString(),
                selected: item.selected !== false,
                priceIncludesTax: item.priceIncludesTax !== undefined ? item.priceIncludesTax : false
              };
              console.log(`    📊 Sending priceIncludesTax to DB:`, lineItemData.priceIncludesTax, `(type: ${typeof lineItemData.priceIncludesTax})`);
              const createdItem = await storage.createProposalLineItem(lineItemData);
              console.log(`    ✅ Created line item ${createdItem.id} with priceIncludesTax =`, createdItem.priceIncludesTax);
              
              // Create choices for this line item if they exist
              if (item.choices && Array.isArray(item.choices)) {
                for (let j = 0; j < item.choices.length; j++) {
                  const choice = item.choices[j];
                  await storage.createProposalLineItemChoice({
                    lineItemId: createdItem.id,
                    label: choice.label || '',
                    description: choice.description,
                    price: choice.price?.toString() || '0',
                    isDefault: choice.isDefault || false,
                    sortOrder: j
                  });
                }
              }
            }
          } else {
            console.log(`  ⚠️ Section has no line items or lineItems is not an array:`, section.lineItems);
          }
        }
      } else {
        console.log('⚠️ PUT proposal - no sections in request body');
      }
      
      // Recompute subtotal server-side from actual stored line items (authoritative)
      // This prevents frontend calculation bugs from corrupting the stored value
      try {
        const storedItemsPut = await storage.getProposalLineItemsByProposal(proposal.id);
        const storedSectionsPut = await storage.getProposalSectionsByProposal(proposal.id);
        const optionalSectionIdsPut = new Set(
          storedSectionsPut
            .filter(s => s.sectionType === 'optional' || s.sectionType === 'multipleChoice')
            .map(s => s.id)
        );
        const taxRatePut = parseFloat(req.body.taxRate || '15') / 100;
        const discountAmtPut = parseFloat(req.body.discountAmount || '0') || 0;
        let recomputedSubtotalPut = 0;
        for (const item of storedItemsPut) {
          const inOptionalSectionPut = optionalSectionIdsPut.has(item.sectionId || '');
          if (item.selected !== false && !item.isOptional && !inOptionalSectionPut) {
            const price = parseFloat(item.totalPrice?.toString() || '0') || 0;
            recomputedSubtotalPut += item.priceIncludesTax ? price / (1 + taxRatePut) : price;
          }
        }
        // discountAmount is the pre-computed dollar discount (see CREATE above).
        const discountValuePut = discountAmtPut;
        const subtotalAfterDiscountPut = Math.max(0, recomputedSubtotalPut - discountValuePut);
        const recomputedGstPut = subtotalAfterDiscountPut * taxRatePut;
        const recomputedTotalPut = subtotalAfterDiscountPut + recomputedGstPut;
        // Update proposal with correct values
        await storage.updateProposal(proposal.id, {
          subtotal: parseFloat(recomputedSubtotalPut.toFixed(2)),
          gstAmount: parseFloat(recomputedGstPut.toFixed(2)),
          totalAmount: parseFloat(recomputedTotalPut.toFixed(2)),
        });
        // Sync correct values to job
        if (proposal.jobId && recomputedSubtotalPut > 0) {
          await storage.updateJob(proposal.jobId, {
            subtotal: recomputedSubtotalPut.toFixed(2),
            totalAmount: recomputedSubtotalPut.toFixed(2),
            gstAmount: recomputedGstPut.toFixed(2),
            totalIncludingGst: recomputedTotalPut.toFixed(2)
          });
          console.log('✅ Synced job prices from recomputed line items (PUT):', { subtotal: recomputedSubtotalPut.toFixed(2), gst: recomputedGstPut.toFixed(2), total: recomputedTotalPut.toFixed(2) });
        }
      } catch (error) {
        console.error('❌ Error recomputing/syncing job prices (PUT):', error);
      }
      
      res.json({
        success: true,
        data: proposal,
        message: 'Proposal updated successfully'
      });
    } catch (error: any) {
      console.error('Error updating proposal:', error);
      
      if (error.message === 'Proposal not found') {
        return res.status(404).json({
          success: false,
          message: 'Proposal not found'
        });
      }
      
      if (error.name === 'ZodError') {
        return res.status(400).json({
          success: false,
          message: 'Invalid proposal data',
          errors: error.errors
        });
      }
      
      res.status(500).json({
        success: false,
        message: 'Error updating proposal'
      });
    }
  });

  // Mark proposal as viewed by client (public endpoint - no auth required)
  app.post('/api/proposals/:id/viewed', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      
      const proposal = await storage.getProposal(id);
      if (!proposal) {
        return res.status(404).json({ success: false, message: 'Proposal not found' });
      }

      // Only update if not already viewed
      if (!proposal.viewedDate) {
        const updatedProposal = await storage.updateProposal(id, {
          viewedDate: new Date(),
          status: proposal.status === 'sent' ? 'viewed' : proposal.status,
        });

        // Create diary entry for the view
        if (proposal.jobId) {
          const customer = proposal.customerId ? await storage.getCustomer(proposal.customerId) : null;
          const viewedDocWord = proposal.templateUsed === 'quote' ? 'Quote' : 'Proposal';
          await storage.createJobDiaryEntry({
            jobId: proposal.jobId,
            entryType: 'note',
            title: `${viewedDocWord} Viewed`,
            description: `${viewedDocWord} "${proposal.title || proposal.proposalNumber}" was viewed by ${customer?.name || customer?.firstName || 'the customer'}`,
            authorName: 'System',
            authorRole: 'system',
            metadata: {
              proposalId: id,
              action: 'proposal_viewed',
              viewedAt: new Date().toISOString(),
            }
          });
        }

        console.log(`👁️ Proposal ${id} marked as viewed`);
        return res.json({ success: true, data: updatedProposal, firstView: true });
      }

      // Already viewed - just return success
      return res.json({ success: true, data: proposal, firstView: false });
    } catch (error: any) {
      console.error('Error marking proposal as viewed:', error);
      res.status(500).json({ success: false, message: 'Error marking proposal as viewed' });
    }
  });

  // Accept proposal - converts to work order and creates notification
  app.post('/api/proposals/:id/accept', async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { selectedChoices } = req.body || {};
      console.log('🚀 ACCEPT PROPOSAL REQUEST RECEIVED - Proposal ID:', id);
      console.log('📋 Request method:', req.method);
      console.log('🔐 Session ID:', req.session?.id);
      console.log('👤 Employee ID:', req.session?.employeeId);
      console.log('🎯 Selected choices:', selectedChoices);
      
      // Get the proposal
      const proposal = await storage.getProposal(id);
      console.log('📄 Proposal found:', proposal ? 'YES' : 'NO', proposal?.status);
      
      if (!proposal) {
        console.log('❌ Proposal not found:', id);
        return res.status(404).json({ success: false, message: 'Proposal not found' });
      }

      // Check if already accepted - if so, just return success (customer-friendly)
      if (proposal.status === 'accepted') {
        console.log('⚠️ Proposal already accepted, returning success:', id);
        const job = proposal.jobId ? await storage.getJob(proposal.jobId) : null;
        return res.json({
          success: true,
          data: {
            proposal: proposal,
            workOrder: job,
            message: `${proposal.templateUsed === 'quote' ? 'Quote' : 'Proposal'} accepted successfully`
          }
        });
      }

      // Already accepted but deposit not yet paid — return the same shape
      // the deposit-required path returns below so the customer UI can
      // re-open the Stripe Checkout flow.
      if (proposal.status === 'accepted_pending_deposit') {
        const pendingAmount = computeDepositAmount(
          (proposal as any).depositType,
          (proposal as any).depositValue,
          proposal.totalAmount,
        );
        return res.json({
          success: true,
          requiresDeposit: true,
          data: {
            proposal,
            depositType: (proposal as any).depositType,
            depositValue: (proposal as any).depositValue,
            depositAmount: pendingAmount,
            totalAmount: parseFloat(proposal.totalAmount?.toString() || '0'),
            message: 'Deposit payment required to finalize acceptance',
          },
        });
      }

      // Check if expired
      if ((proposal as any).validUntil && new Date((proposal as any).validUntil) < new Date()) {
        return res.status(400).json({ success: false, message: 'Proposal has expired' });
      }

      // If customer selected different choices, update the proposal sections
      let updatedSections = proposal.sections;
      let updatedTotalAmount: number = parseFloat(proposal.totalAmount?.toString() || '0');
      let updatedSubtotal: number = parseFloat(proposal.subtotal?.toString() || '0');

      // When no choices are made, recompute from actual DB line items (more reliable than cached proposal.subtotal)
      if (!selectedChoices || Object.keys(selectedChoices).length === 0) {
        try {
          const acceptLineItems = await storage.getProposalLineItemsByProposal(id);
          const acceptTaxRate = parseFloat(proposal.taxRate?.toString() || '15') / 100;
          const acceptDiscountAmt = parseFloat(proposal.discountAmount?.toString() || '0') || 0;
          let computedSubtotal = 0;
          for (const item of acceptLineItems) {
            if (item.selected !== false) {
              const price = parseFloat(item.totalPrice?.toString() || '0') || 0;
              computedSubtotal += item.priceIncludesTax ? price / (1 + acceptTaxRate) : price;
            }
          }
          // discountAmount is the pre-computed dollar discount (see CREATE/PUT).
          const acceptDiscountValue = acceptDiscountAmt;
          const acceptSubtotalAfterDiscount = Math.max(0, computedSubtotal - acceptDiscountValue);
          const acceptGst = acceptSubtotalAfterDiscount * acceptTaxRate;
          updatedSubtotal = Math.round(computedSubtotal * 100) / 100;
          updatedTotalAmount = Math.round((acceptSubtotalAfterDiscount + acceptGst) * 100) / 100;
          console.log(`💰 Accept: recomputed from line items: subtotal=${updatedSubtotal}, total=${updatedTotalAmount}`);
        } catch (err) {
          console.error('⚠️ Accept: failed to recompute from line items, using cached values:', err);
        }
      }
      
      if (selectedChoices && Object.keys(selectedChoices).length > 0 && Array.isArray(proposal.sections)) {
        console.log('🎯 Applying customer-selected choices to proposal...');
        
        // Update sections with selected choices (validate choice IDs)
        updatedSections = proposal.sections.map((section: any) => ({
          ...section,
          lineItems: (section.lineItems || []).map((item: any) => {
            if (selectedChoices[item.id] && item.pricingType === 'choice') {
              // Validate that the selected choice exists
              const validChoice = (item.choices || []).find((c: any) => c.id === selectedChoices[item.id]);
              if (validChoice) {
                console.log(`🎯 Updating line item ${item.id} with choice ${selectedChoices[item.id]}`);
                return {
                  ...item,
                  selectedChoiceId: selectedChoices[item.id]
                };
              } else {
                console.log(`⚠️ Invalid choice ${selectedChoices[item.id]} for item ${item.id}, keeping original`);
              }
            }
            return item;
          })
        }));
        
        // Recalculate totals based on selected choices (matching ProposalTemplate logic)
        let subtotalExGst = 0;
        let gstAmount = 0;
        const gstRate = 0.15;
        
        updatedSections.forEach((section: any) => {
          (section.lineItems || []).forEach((item: any) => {
            if (item.selected) {
              let itemPrice = 0;
              if (item.pricingType === 'choice' && item.selectedChoiceId) {
                const selectedChoice = (item.choices || []).find((c: any) => c.id === item.selectedChoiceId);
                if (selectedChoice) {
                  itemPrice = Number(selectedChoice.price) * Number(item.quantity);
                }
              } else if (item.pricingType === 'fixed' && item.fixedPrice) {
                itemPrice = Number(item.fixedPrice);
              } else {
                itemPrice = Number(item.totalPrice);
              }
              
              // Handle priceIncludesTax flag (matching ProposalTemplate logic)
              const isInclusive = item.priceIncludesTax || false;
              
              if (isInclusive) {
                // Price includes GST - extract the ex-GST amount
                const exGst = itemPrice / (1 + gstRate);
                subtotalExGst += exGst;
                gstAmount += itemPrice - exGst;
              } else {
                // Price is ex-GST
                subtotalExGst += itemPrice;
                gstAmount += itemPrice * gstRate;
              }
            }
          });
        });
        
        // Apply discount (discount reduces the taxable amount - matching ProposalTemplate logic)
        const discountAmount = Number(proposal.discountAmount || 0);
        const subtotalAfterDiscount = Math.max(0, subtotalExGst - discountAmount);
        
        // GST is calculated on the discounted amount (less GST)
        const gstOnDiscounted = subtotalAfterDiscount * gstRate;
        const totalAmount = subtotalAfterDiscount + gstOnDiscounted;
        
        // Round to 2 decimal places (matching UI formatting)
        updatedSubtotal = Math.round(subtotalExGst * 100) / 100;
        updatedTotalAmount = Math.round(totalAmount * 100) / 100;
        const roundedGst = Math.round(gstOnDiscounted * 100) / 100;
        console.log(`💰 Recalculated totals: subtotal=${updatedSubtotal}, discount=${discountAmount}, subtotalAfterDiscount=${Math.round(subtotalAfterDiscount * 100) / 100}, gst=${roundedGst}, total=${updatedTotalAmount}`);
      }
      
      // Deposit gate. If this proposal requires an upfront payment, persist
      // the updated sections/totals and stop here — the customer UI will
      // open Stripe Checkout via /api/proposals/:id/deposit-checkout and
      // the webhook will run finalizeProposalAcceptance() on payment.
      const depositAmount = computeDepositAmount(
        (proposal as any).depositType,
        (proposal as any).depositValue,
        updatedTotalAmount,
      );

      if (depositAmount > 0) {
        const pendingProposal = await storage.updateProposal(id, {
          status: 'accepted_pending_deposit',
          acceptedDate: new Date(),
          sections: updatedSections,
          totalAmount: updatedTotalAmount,
          subtotal: updatedSubtotal,
        } as any);
        console.log(`⏸️ Proposal ${proposal.proposalNumber} acceptance pending deposit of ${depositAmount}`);
        return res.json({
          success: true,
          requiresDeposit: true,
          data: {
            proposal: pendingProposal,
            depositType: (proposal as any).depositType,
            depositValue: (proposal as any).depositValue,
            depositAmount,
            totalAmount: updatedTotalAmount,
            message: 'Deposit payment required to finalize acceptance',
          },
        });
      }

      // No deposit required — full acceptance now
      const updatedProposal = await storage.updateProposal(id, {
        status: 'accepted',
        acceptedDate: new Date(),
        sections: updatedSections,
        totalAmount: updatedTotalAmount,
        subtotal: updatedSubtotal,
      } as any);

      // Owner-pathed public accept link (no session) → bind the proposal's tenant so
      // every insert inside finalizeProposalAcceptance (job, payment, notifications,
      // diary) is stamped with the proposal owner, not the DEFAULT (Treemarkables)
      // tenant. Without this, a second tenant's accepted proposal would create the
      // work order under Treemarkables.
      const { job, jobNumber } = await runWithBusiness(
        proposal.businessId ?? undefined,
        () => finalizeProposalAcceptance({
          proposal: { ...proposal, totalAmount: updatedTotalAmount as any } as any,
          updatedTotalAmount,
          updatedSubtotal,
        }),
      );

      console.log(`✅ Proposal ${proposal.proposalNumber} accepted and converted to work order ${jobNumber}`);

      res.json({
        success: true,
        data: {
          proposal: updatedProposal,
          workOrder: job,
          message: `${proposal.templateUsed === 'quote' ? 'Quote' : 'Proposal'} accepted successfully and work order created`
        }
      });
    } catch (error) {
      console.error('Error accepting proposal:', error);
      res.status(500).json({ success: false, message: 'Error accepting proposal' });
    }
  });

  // Create a Stripe Checkout Session for a proposal's required deposit.
  // Called from the customer-facing ProposalAccept page after the customer
  // hits Accept and the accept response came back with requiresDeposit=true.
  // The webhook (see /api/stripe/webhook) finalizes the acceptance and
  // creates the work order on payment success.
  app.post('/api/proposals/:id/deposit-checkout', async (req: Request, res: Response) => {
    try {
      if (!isStripeConfigured()) {
        return res.status(503).json({
          success: false,
          message: 'Payment processing is not yet configured. Please contact us to complete acceptance.',
        });
      }

      const { id } = req.params;
      const proposal = await storage.getProposal(id);
      if (!proposal) {
        return res.status(404).json({ success: false, message: 'Proposal not found' });
      }
      // Deposits: Treemarkables (platform account) or a Connect tenant with charges
      // enabled (direct charge → funds go to the tenant). Everyone else → bank transfer.
      const { canTakeCard: depositCanCard, connectedAccountId: depositConnectAccount } = await resolveCardPayment(proposal.businessId);
      if (!depositCanCard) {
        return res.status(403).json({
          success: false,
          message: 'Online card payment is not available for this business. Please arrange the deposit by bank transfer.',
        });
      }

      if (proposal.status !== 'accepted_pending_deposit') {
        return res.status(400).json({
          success: false,
          message: 'Proposal is not in a state that requires a deposit',
        });
      }

      const depositAmount = computeDepositAmount(
        (proposal as any).depositType,
        (proposal as any).depositValue,
        proposal.totalAmount,
      );
      if (depositAmount <= 0) {
        return res.status(400).json({ success: false, message: 'No deposit amount calculated for this proposal' });
      }
      const amountCents = Math.round(depositAmount * 100);

      const customer = proposal.customerId ? await storage.getCustomer(proposal.customerId) : null;
      const settings = await storage.getBusinessSettings().catch(() => null);

      // Build absolute return URLs. Customer-facing links always point at
      // the canonical production host per CLAUDE.md, falling back to the
      // request origin in dev/preview environments.
      const origin =
        process.env.NODE_ENV === 'production'
          ? APP_URL
          : `${req.protocol}://${req.get('host')}`;
      const successUrl = `${origin}/proposal/${proposal.id}/accept?deposit=success&session_id={CHECKOUT_SESSION_ID}`;
      const cancelUrl = `${origin}/proposal/${proposal.id}/accept?deposit=cancelled`;

      const session = await createDepositCheckoutSession({
        proposalId: proposal.id,
        proposalNumber: proposal.proposalNumber,
        amountCents,
        customerEmail: customer?.email || null,
        customerName: customer?.name || null,
        successUrl,
        cancelUrl,
        businessName: (settings as any)?.businessName || 'Treemarkables',
        connectedAccountId: depositConnectAccount,
      });

      res.json({ success: true, data: { sessionId: session.id, url: session.url, depositAmount } });
    } catch (error: any) {
      console.error('Error creating deposit checkout session:', error);
      res.status(500).json({
        success: false,
        message: error?.message || 'Error creating deposit checkout session',
      });
    }
  });

  // Lightweight public endpoint so the customer modal can guard the "Pay
  // now" button when Stripe isn't configured yet (e.g. local dev).
  app.get('/api/payments/config', async (_req: Request, res: Response) => {
    res.json({
      success: true,
      data: {
        stripeConfigured: isStripeConfigured(),
        stripePublishableKey: getPublishableKey(),
      },
    });
  });

  // Stripe webhook. Verifies signature against the raw body captured by the
  // express.json verify callback, then dispatches by event type. Idempotent:
  // a duplicate checkout.session.completed for the same session_id will be
  // rejected by the unique index on payments.provider_session_id.
  // ── Subscription billing (Inflow — Phase 4) ───────────────────────────────
  // List the active plans (for the pricing / upgrade UI).
  app.get('/api/billing/plans', async (_req: Request, res: Response) => {
    try {
      res.json({ success: true, data: await billing.getActivePlans() });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Failed to load plans' });
    }
  });

  // Getting-started checklist state for the current business (drives the new-tenant
  // onboarding card). Each step is "done" once the tenant has configured that thing.
  // A fully set-up business (incl. comped Treemarkables) has every step done → card hides.
  app.get('/api/onboarding-status', async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const settings = await storage.getBusinessSettings().catch(() => null);
      const [channel] = await db.select({ id: schema.tenantChannels.id }).from(schema.tenantChannels)
        .where(eq(schema.tenantChannels.businessId, businessId)).limit(1);
      const [job] = await db.select({ id: schema.jobs.id }).from(schema.jobs)
        .where(eq(schema.jobs.businessId, businessId)).limit(1);
      const name = (settings?.businessName ?? '').trim();
      res.json({ success: true, data: {
        business: !!name && name !== 'My Business',
        channel: !!channel,
        bank: !!(settings?.bankAccountNumber ?? '').trim(),
        firstJob: !!job,
      }});
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Failed to load onboarding status' });
    }
  });

  // Current business's subscription status.
  app.get('/api/billing/subscription', async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      res.json({ success: true, data: (await billing.getSubscriptionByBusiness(businessId)) || null });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message });
    }
  });

  // Current business's SMS + AI usage vs the plan's bundled caps (for the billing UI meters).
  app.get('/api/billing/usage', async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      res.json({ success: true, data: await usageMeter.getUsageSummary(businessId) });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message });
    }
  });

  // Start (or change) a subscription — returns a Stripe Checkout URL to redirect to.
  app.post('/api/billing/checkout', requireAdmin, async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    const employeeId = req.session.employeeId;
    if (!businessId || !employeeId) return res.status(401).json({ success: false, message: 'Not logged in' });
    if (!isStripeConfigured()) return res.status(503).json({ success: false, message: 'Billing is not available right now.' });
    try {
      const { planKey } = req.body as { planKey?: string };
      if (!planKey) return res.status(400).json({ success: false, message: 'planKey required' });
      const plan = await billing.getPlanByKey(planKey);
      if (!plan) return res.status(404).json({ success: false, message: 'Unknown plan' });
      if (!plan.stripePriceId) return res.status(400).json({ success: false, message: `${plan.name} is free — no checkout needed.` });

      const employee = await storage.getEmployee(employeeId);
      const existing = await billing.getSubscriptionByBusiness(businessId);
      const customerId = await getOrCreateStripeCustomer(businessId, {
        email: employee?.email,
        name: `${employee?.firstName ?? ''} ${employee?.lastName ?? ''}`.trim() || undefined,
        existingId: existing?.stripeCustomerId,
      });
      // Persist the customer id now so we never create a duplicate on retry.
      await billing.upsertSubscription(businessId, {
        stripeCustomerId: customerId,
        planId: plan.id,
        status: existing?.status ?? 'incomplete',
      });

      const base = APP_URL;
      const session = await createSubscriptionCheckoutSession({
        businessId,
        priceId: plan.stripePriceId,
        planKey,
        customerId,
        successUrl: `${base}/settings/billing?status=success&session_id={CHECKOUT_SESSION_ID}`,
        cancelUrl: `${base}/settings/billing?status=cancelled`,
      });
      res.json({ success: true, url: session.url });
    } catch (e: any) {
      console.error('billing checkout error:', e?.message);
      res.status(500).json({ success: false, message: e?.message || 'Failed to start checkout' });
    }
  });

  // Billing portal — subscriber updates their card / cancels.
  app.post('/api/billing/portal', requireAdmin, async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const sub = await billing.getSubscriptionByBusiness(businessId);
      if (!sub?.stripeCustomerId) return res.status(400).json({ success: false, message: 'No billing account yet — subscribe first.' });
      const { url } = await createBillingPortalSession(sub.stripeCustomerId, `${APP_URL}/settings/billing`);
      res.json({ success: true, url });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message });
    }
  });

  // ── Stripe Connect (Express) — per-tenant card payments, Phase 1: onboarding ──
  const CONNECT_RETURN = `${APP_URL}/settings/billing?connect=done`;
  const CONNECT_REFRESH = `${APP_URL}/settings/billing?connect=refresh`;

  // Start (or resume) Stripe-hosted onboarding. Creates the tenant's Express account on
  // first call, stores the acct_… id, and returns a hosted onboarding URL to redirect to.
  app.post('/api/billing/connect/onboard', requireAdmin, async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const settings = await storage.getBusinessSettings();
      let accountId = (settings?.stripeConnectAccountId ?? '').trim();
      if (!accountId) {
        const employee = req.session.employeeId ? await storage.getEmployee(req.session.employeeId) : null;
        accountId = await createConnectAccount({ email: employee?.email, businessName: settings?.businessName });
        await storage.updateBusinessSettings({ stripeConnectAccountId: accountId } as any);
      }
      const url = await createConnectAccountLink(accountId, { returnUrl: CONNECT_RETURN, refreshUrl: CONNECT_REFRESH });
      res.json({ success: true, url });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Could not start Stripe onboarding.' });
    }
  });

  // Current Connect status for the UI. Does a fresh retrieve + syncs chargesEnabled to
  // the DB, so the card-payment gate (Phase 2) reflects reality without the webhook.
  app.get('/api/billing/connect/status', async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const settings = await storage.getBusinessSettings();
      const accountId = (settings?.stripeConnectAccountId ?? '').trim();
      if (!accountId) return res.json({ success: true, data: { connected: false, chargesEnabled: false } });
      const status = await retrieveConnectAccount(accountId);
      if (status.chargesEnabled !== !!settings?.stripeConnectChargesEnabled) {
        await storage.updateBusinessSettings({ stripeConnectChargesEnabled: status.chargesEnabled } as any);
      }
      res.json({ success: true, data: { connected: true, ...status } });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Could not load Stripe status.' });
    }
  });

  // Express dashboard login link, so a connected tenant can view their payouts.
  app.post('/api/billing/connect/dashboard', requireAdmin, async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const settings = await storage.getBusinessSettings();
      const accountId = (settings?.stripeConnectAccountId ?? '').trim();
      if (!accountId) return res.status(400).json({ success: false, message: 'Not connected to Stripe yet.' });
      const url = await createConnectLoginLink(accountId);
      res.json({ success: true, url });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Could not open Stripe dashboard.' });
    }
  });

  // Disconnect: stop taking card payments → fall back to bank transfer. Clears the stored
  // link (so resolveCardPayment no longer routes to it) and best-effort deletes the empty
  // Express account so it doesn't orphan. If the account holds a balance the delete is
  // skipped — the tenant manages/closes it in Stripe; we still unlink either way.
  app.post('/api/billing/connect/disconnect', requireAdmin, async (req: Request, res: Response) => {
    const businessId = req.session.businessId;
    if (!businessId) return res.status(401).json({ success: false, message: 'Not logged in' });
    try {
      const settings = await storage.getBusinessSettings();
      const accountId = (settings?.stripeConnectAccountId ?? '').trim();
      if (accountId) await deleteConnectAccount(accountId); // best-effort, never throws
      await storage.updateBusinessSettings({ stripeConnectAccountId: '', stripeConnectChargesEnabled: false });
      res.json({ success: true });
    } catch (e: any) {
      res.status(500).json({ success: false, message: e?.message || 'Could not disconnect Stripe.' });
    }
  });

  app.post('/api/stripe/webhook', async (req: Request, res: Response) => {
    const rawBody: Buffer | undefined = (req as any).rawBody;
    const signature = req.headers['stripe-signature'] as string | undefined;
    if (!rawBody) {
      console.error('Stripe webhook: raw body unavailable');
      return res.status(400).send('Raw body unavailable');
    }
    let event: any;
    try {
      event = await constructWebhookEvent(rawBody, signature);
    } catch (err: any) {
      console.error('Stripe webhook signature verification failed:', err?.message);
      return res.status(400).send(`Webhook Error: ${err?.message || 'invalid signature'}`);
    }

    try {
      // ── Stripe Connect: a connected account's capabilities changed ──
      // Keep stripe_connect_charges_enabled current so the card-payment gate reflects
      // reality without waiting for the owner to reopen Settings → Billing. Owner
      // connection (session-less webhook), matched by the stored account id. NOTE: only
      // delivered if the webhook endpoint listens to "events on Connected accounts".
      if (event.type === 'account.updated') {
        const acct = event.data.object as any;
        if (acct?.id) {
          try {
            await ownerDb.update(schema.businessSettings)
              .set({ stripeConnectChargesEnabled: !!acct.charges_enabled })
              .where(eq(schema.businessSettings.stripeConnectAccountId, acct.id));
            // Matched by Stripe account id, so we don't know which business's
            // settings row changed — drop the whole settings cache namespace
            // (rare event, tiny cache).
            cacheDeletePrefix('bs:');
          } catch (e: any) {
            console.error('Stripe Connect account.updated sync failed:', e?.message);
          }
        }
        return res.json({ received: true });
      }

      // ── Subscription billing events (Inflow — Phase 4) ──
      // Keep each business's `subscriptions` row in sync with Stripe. Runs outside any
      // request (owner connection), so businessId comes from the event metadata.
      if (event.type === 'customer.subscription.created'
        || event.type === 'customer.subscription.updated'
        || event.type === 'customer.subscription.deleted') {
        const sub = event.data.object as any;
        const businessId: string | undefined = sub?.metadata?.businessId;
        if (businessId) {
          // Don't trust the event's status snapshot. At signup Stripe fires
          // subscription.created (status=incomplete) AND subscription.updated
          // (status=active) within the same second; delivery/processing order is
          // not guaranteed, so a late 'created' would otherwise clobber 'active'
          // and lock a paying customer out. Re-fetch from the API so we always
          // store the CURRENT status regardless of event order (the Stripe-
          // recommended pattern). subscription.deleted → the fetch returns
          // status=canceled. Fall back to the event snapshot if the fetch fails.
          // Capture the status we had BEFORE this sync, so dunning fires only on the
          // transition into a payment problem — not on every resync/retry of the same state.
          const prevStatus = (await storage.getSubscriptionForBusiness(businessId).catch(() => undefined))?.status;
          let fresh = sub;
          try {
            fresh = await retrieveStripeSubscription(sub.id);
          } catch (e: any) {
            console.error(`Stripe webhook: could not re-fetch subscription ${sub.id}, using event snapshot:`, e?.message);
          }
          await billing.syncFromStripeSubscription(businessId, fresh);
          console.log(`Stripe webhook: synced subscription ${sub.id} for business ${businessId} -> ${fresh.status}`);
          // Dunning: payment slipped into a problem state — nudge the owner off-app (bell +
          // email) to fix their card. Only on the transition, so retries don't re-spam.
          const PAYMENT_PROBLEM = new Set(['past_due', 'unpaid', 'incomplete_expired']);
          if (PAYMENT_PROBLEM.has(fresh.status) && fresh.status !== prevStatus) {
            await notifyBillingProblem(businessId, fresh.status);
          }
        }
        return res.json({ received: true });
      }
      // Subscription checkout finished — sync immediately rather than waiting for the
      // subscription.* event, so the owner sees an active plan as soon as they're back.
      if (event.type === 'checkout.session.completed'
        && (event.data.object as any)?.metadata?.kind === 'subscription') {
        const session = event.data.object as any;
        const businessId: string | undefined = session?.client_reference_id || session?.metadata?.businessId;
        if (businessId && session.subscription) {
          const sub = await retrieveStripeSubscription(session.subscription);
          await billing.syncFromStripeSubscription(businessId, sub);
          console.log(`Stripe webhook: subscription checkout completed for business ${businessId}`);
        }
        return res.json({ received: true });
      }

      if (event.type === 'checkout.session.completed') {
        const session = event.data.object as any;
        const proposalId: string | undefined = session?.metadata?.proposalId;
        const kind: string | undefined = session?.metadata?.kind;
        const amountTotalCents: number = session?.amount_total || 0;
        const amountPaid = Math.round(amountTotalCents) / 100;
        const invoiceId: string | undefined = session?.metadata?.invoiceId;

        // Invoice payment (kind='payment'). Record the payment and mark the
        // invoice paid — we always charge the full outstanding balance, so a
        // succeeded session settles it.
        if (kind === 'payment' && invoiceId) {
          const existingInvoicePay = await storage.getPaymentBySessionId(session.id);
          if (existingInvoicePay) {
            console.log(`Stripe webhook: session ${session.id} already processed`);
            return res.json({ received: true, duplicate: true });
          }
          const invoice = await storage.getInvoice(invoiceId);
          if (!invoice) {
            console.error('Stripe webhook: invoice not found for session', { invoiceId, sessionId: session.id });
            // 200 so Stripe stops retrying — the invoice isn't coming back.
            return res.json({ received: true, missingInvoice: true });
          }
          // Stripe webhook runs as owner (no session) → bind the matched invoice's
          // tenant so the payment-ledger row + invoice update stamp the owning
          // business, not the DEFAULT (Treemarkables).
          await runWithBusiness(invoice.businessId ?? undefined, async () => {
            await storage.createPayment({
              jobId: (invoice.jobId || null) as any,
              invoiceId: invoice.id,
              customerId: invoice.customerId,
              amount: amountPaid as any,
              currency: 'NZD',
              provider: 'stripe',
              providerSessionId: session.id,
              providerPaymentId: session.payment_intent || null,
              kind: 'payment',
              status: 'succeeded',
              paidAt: new Date(),
            } as any);
            if (invoice.status !== 'paid') {
              await storage.updateInvoice(invoice.id, { status: 'paid', paidAt: new Date() } as any);
            }
          });
          console.log(`✅ Stripe webhook: payment of $${amountPaid} captured for invoice ${invoice.invoiceNumber}; marked paid`);
          return res.json({ received: true });
        }

        // Job payment (kind='payment' + jobId) — staff "Take payment" on the
        // job card. Record the payment and roll the job's paid/balance forward.
        const jobIdMeta: string | undefined = session?.metadata?.jobId;
        if (kind === 'payment' && jobIdMeta) {
          const existingJobPay = await storage.getPaymentBySessionId(session.id);
          if (existingJobPay) {
            console.log(`Stripe webhook: session ${session.id} already processed`);
            return res.json({ received: true, duplicate: true });
          }
          const job = await storage.getJob(jobIdMeta);
          if (!job) {
            console.error('Stripe webhook: job not found for session', { jobIdMeta, sessionId: session.id });
            return res.json({ received: true, missingJob: true });
          }
          const jobTotal = parseFloat((job as any).totalAmount?.toString() || '0') || 0;
          const prevPaid = parseFloat((job as any).paidAmount?.toString() || '0') || 0;
          const newPaid = Math.round((prevPaid + amountPaid) * 100) / 100;
          const newBalance = Math.max(0, Math.round((jobTotal - newPaid) * 100) / 100);
          // Stripe webhook runs as owner (no session) → bind the matched job's tenant
          // so the payment-ledger row + job update stamp the owning business, not the
          // DEFAULT (Treemarkables).
          await runWithBusiness(job.businessId ?? undefined, async () => {
            await storage.createPayment({
              jobId: job.id,
              customerId: (job as any).customerId || null,
              amount: amountPaid as any,
              currency: 'NZD',
              provider: 'stripe',
              providerSessionId: session.id,
              providerPaymentId: session.payment_intent || null,
              kind: 'payment',
              status: 'succeeded',
              paidAt: new Date(),
            } as any);
            await storage.updateJob(job.id, {
              paidAmount: String(newPaid),
              balanceDue: String(newBalance),
            } as any);
          });

          console.log(`✅ Stripe webhook: payment of $${amountPaid} captured for job ${(job as any).jobNumber}; paid ${newPaid}/${jobTotal}`);
          return res.json({ received: true });
        }

        if (kind !== 'deposit' || !proposalId) {
          console.log('Stripe webhook: ignoring non-deposit checkout.session.completed', { kind, proposalId });
          return res.json({ received: true });
        }

        // Idempotency check — if we've already recorded this session, skip.
        const existing = await storage.getPaymentBySessionId(session.id);
        if (existing) {
          console.log(`Stripe webhook: session ${session.id} already processed`);
          return res.json({ received: true, duplicate: true });
        }

        const proposal = await storage.getProposal(proposalId);
        if (!proposal) {
          console.error('Stripe webhook: proposal not found for session', { proposalId, sessionId: session.id });
          // 200 so Stripe doesn't keep retrying — the proposal isn't coming back.
          return res.json({ received: true, missingProposal: true });
        }

        if (proposal.status === 'accepted') {
          console.log(`Stripe webhook: proposal ${proposalId} already accepted; recording payment only`);
          // Still record the payment so the ledger reflects it, but skip the
          // finalize side effects (job already exists).
          try {
            const targetJobId = proposal.jobId || null;
            // Stripe webhook runs as owner (no session) → stamp the payment with the
            // proposal's tenant, not the DEFAULT, so the ledger row is tenant-correct.
            await runWithBusiness(proposal.businessId ?? undefined, () => storage.createPayment({
              jobId: targetJobId as any,
              proposalId: proposal.id,
              customerId: proposal.customerId,
              amount: amountPaid as any,
              currency: 'NZD',
              provider: 'stripe',
              providerSessionId: session.id,
              providerPaymentId: session.payment_intent || null,
              kind: 'deposit',
              status: 'succeeded',
              paidAt: new Date(),
            } as any));
          } catch (e) {
            console.warn('Stripe webhook: payment insert skipped (likely duplicate)', e);
          }
          return res.json({ received: true });
        }

        // Move proposal to fully accepted + record deposit timestamps
        const updatedProposal = await storage.updateProposal(proposalId, {
          status: 'accepted',
          depositPaidAt: new Date(),
          depositAmountPaid: amountPaid as any,
        } as any);

        const totalAmount = parseFloat(updatedProposal.totalAmount?.toString() || proposal.totalAmount?.toString() || '0');
        const subtotal = parseFloat(updatedProposal.subtotal?.toString() || proposal.subtotal?.toString() || '0');

        // Owner-context webhook → bind the proposal's tenant so the work order and all
        // acceptance side-effect inserts are stamped to the proposal owner, not DEFAULT.
        await runWithBusiness(updatedProposal.businessId ?? undefined, () => finalizeProposalAcceptance({
          proposal: updatedProposal,
          updatedTotalAmount: totalAmount,
          updatedSubtotal: subtotal,
          depositPaid: {
            amount: amountPaid,
            provider: 'stripe',
            providerSessionId: session.id,
            providerPaymentId: session.payment_intent || undefined,
          },
        }));

        console.log(`✅ Stripe webhook: deposit of $${amountPaid} captured for proposal ${updatedProposal.proposalNumber}; work order created`);
        return res.json({ received: true });
      }

      // Other event types we don't act on yet
      console.log(`Stripe webhook: ignoring event type ${event.type}`);
      res.json({ received: true });
    } catch (err: any) {
      console.error('Stripe webhook handler error:', err);
      // 500 so Stripe retries — but only for unexpected errors, not signature failures
      res.status(500).json({ received: false, error: err?.message || 'handler error' });
    }
  });

  // Delete proposal
  app.delete('/api/proposals/:id', requireAdmin, async (req: Request, res: Response) => {
    try {
      // Forensic snapshot. There is no soft-delete on proposals and the
      // delete cascades to proposal_sections + proposal_line_items, so once
      // the row is gone this log is the only trace. Logged at warn level so
      // it surfaces in the DO production log retention.
      const snapshot = await storage.getProposal(req.params.id).catch(() => null);
      if (snapshot) {
        let sectionCount = 0;
        try {
          const sections = await storage.getProposalSectionsByProposal(req.params.id);
          sectionCount = sections?.length ?? 0;
        } catch { /* best-effort, snapshot is still useful */ }
        console.warn(
          `🛑 PROPOSAL_DELETE_AUDIT id=${req.params.id} ts=${new Date().toISOString()} session=${req.session?.employeeId ?? 'anon'} ua=${req.headers['user-agent'] ?? 'n/a'} snapshot=${JSON.stringify({
            jobId: snapshot.jobId,
            customerId: snapshot.customerId,
            proposalNumber: snapshot.proposalNumber,
            status: snapshot.status,
            title: snapshot.title,
            totalAmount: snapshot.totalAmount,
            sentDate: snapshot.sentDate,
            viewedDate: snapshot.viewedDate,
            responseDate: snapshot.responseDate,
            createdAt: snapshot.createdAt,
            updatedAt: snapshot.updatedAt,
            sectionCount,
          })}`
        );
      } else {
        console.warn(`🛑 PROPOSAL_DELETE_AUDIT id=${req.params.id} ts=${new Date().toISOString()} (no snapshot — proposal already missing) session=${req.session?.employeeId ?? 'anon'}`);
      }
      await storage.deleteProposal(req.params.id);
      res.json({
        success: true,
        message: 'Proposal deleted successfully'
      });
    } catch (error) {
      console.error('Error deleting proposal:', error);
      res.status(500).json({
        success: false,
        message: 'Error deleting proposal'
      });
    }
  });

