  // Create proposal line item
  app.post('/api/proposals/:proposalId/lineitems', async (req: Request, res: Response) => {
    try {
      const itemData = {
        ...req.body,
        proposalId: req.params.proposalId
      };
      
      // Ensure totalPrice is computed server-side
      const quantity = parseFloat(itemData.quantity || '1');
      const unitPrice = parseFloat(itemData.unitPrice || '0');
      itemData.totalPrice = (quantity * unitPrice).toString();
      
      const validatedData = insertProposalLineItemSchema.parse(itemData);
      const lineItem = await storage.createProposalLineItem(validatedData);
      
      res.status(201).json({
        success: true,
        data: lineItem,
        message: 'Proposal line item created successfully'
      });
    } catch (error: any) {
      console.error('Error creating proposal line item:', error);
      
      if (error.name === 'ZodError') {
        return res.status(400).json({
          success: false,
          message: 'Invalid line item data',
          errors: error.errors
        });
      }
      
      res.status(500).json({
        success: false,
        message: 'Error creating proposal line item'
      });
    }
  });

  // Update proposal line item
  app.put('/api/proposals/lineitems/:id', async (req: Request, res: Response) => {
    try {
      const validatedData = updateProposalLineItemSchema.parse(req.body);
      const lineItem = await storage.updateProposalLineItem(req.params.id, validatedData);
      
      // Recalculate and sync the proposal's subtotal + totalAmount from all its line items
      if (lineItem.proposalId) {
        try {
          const allLineItems = await storage.getProposalLineItemsByProposal(lineItem.proposalId);
          const newSubtotal = allLineItems
            .filter((i: any) => i.selected !== false)
            .reduce((sum: number, i: any) => {
              const price = parseFloat(i.totalPrice || '0') || 0;
              return sum + (i.priceIncludesTax ? price / 1.15 : price);
            }, 0);
          const gst = newSubtotal * 0.15;
          const newTotal = newSubtotal + gst;
          await storage.updateProposal(lineItem.proposalId, {
            subtotal: parseFloat(newSubtotal.toFixed(2)),
            totalAmount: parseFloat(newTotal.toFixed(2)),
          });
          console.log(`✅ Recalculated proposal ${lineItem.proposalId} subtotal: $${newSubtotal.toFixed(2)} exc GST`);

          // Also sync the linked job's price fields
          const proposal = await storage.getProposal(lineItem.proposalId);
          if (proposal?.jobId && newSubtotal > 0) {
            await storage.updateJob(proposal.jobId, {
              subtotal: newSubtotal.toFixed(2),
              totalAmount: newTotal.toFixed(2),
            });
          }
        } catch (syncErr) {
          console.error('⚠️ Failed to recalculate proposal subtotal:', syncErr);
        }
      }

      res.json({
        success: true,
        data: lineItem,
        message: 'Proposal line item updated successfully'
      });
    } catch (error: any) {
      console.error('Error updating proposal line item:', error);
      
      if (error.message === 'Proposal line item not found') {
        return res.status(404).json({
          success: false,
          message: 'Proposal line item not found'
        });
      }
      
      if (error.name === 'ZodError') {
        return res.status(400).json({
          success: false,
          message: 'Invalid line item data',
          errors: error.errors
        });
      }
      
      res.status(500).json({
        success: false,
        message: 'Error updating proposal line item'
      });
    }
  });

