  // ========================================
  // ACTIVITY DASHBOARD
  // ========================================
  
  // Get activity dashboard data
  app.get("/api/activity-dashboard", async (req, res) => {
    try {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);
      const dayAfterTomorrow = new Date(tomorrow);
      dayAfterTomorrow.setDate(dayAfterTomorrow.getDate() + 1);

      // Get business settings for metrics filtering
      const settings = await storage.getBusinessSettings();
      const metricsStartDate = settings.metricsStartDate ? new Date(settings.metricsStartDate) : null;

      // Get today's jobs
      const { jobs: allJobs } = await storage.getAllJobs({ limit: 999999 });
      
      // Filter jobs for metrics (exclude jobs created before metrics start date)
      const jobsForMetrics = metricsStartDate 
        ? allJobs.filter(job => {
            if (!job.createdAt) return false;
            return new Date(job.createdAt) >= metricsStartDate;
          })
        : allJobs;
      
      const todaysJobs = allJobs.filter(job => {
        if (!job.scheduledDate) return false;
        const jobDate = new Date(job.scheduledDate);
        return jobDate >= today && jobDate < tomorrow;
      });
      
      // Filter today's jobs for metrics calculations
      const todaysJobsForMetrics = todaysJobs.filter(job => {
        if (!metricsStartDate) return true;
        if (!job.createdAt) return false;
        return new Date(job.createdAt) >= metricsStartDate;
      });

      // Get tomorrow's jobs
      const tomorrowsJobs = allJobs.filter(job => {
        if (!job.scheduledDate) return false;
        const jobDate = new Date(job.scheduledDate);
        return jobDate >= tomorrow && jobDate < dayAfterTomorrow;
      });

      // Calculate profit margin for today (using filtered jobs)
      let totalRevenue = 0;
      let totalCosts = 0;
      
      for (const job of todaysJobsForMetrics) {
        // Calculate revenue from line items
        const jobRevenue = (job.lineItems || []).reduce((sum: number, item: any) => {
          return sum + (item.total || 0);
        }, 0);
        totalRevenue += jobRevenue;

        // Calculate costs from line items
        const itemCosts = (job.lineItems || []).reduce((sum: number, item: any) => {
          return sum + (item.totalCost || 0);
        }, 0);
        
        // Add labor costs and additional costs
        const laborCost = job.staffTimeLaborCost || 0;
        const additionalCosts = job.laborCosts || 0;
        
        totalCosts += itemCosts + laborCost + additionalCosts;
      }

      const profitMargin = totalRevenue > 0 
        ? ((totalRevenue - totalCosts) / totalRevenue) * 100 
        : 0;

      // Job status breakdown (using filtered jobs for metrics)
      const statusBreakdown = todaysJobsForMetrics.reduce((acc: any, job) => {
        acc[job.status] = (acc[job.status] || 0) + 1;
        return acc;
      }, {});

      // Get staff bookings for today (time entries)
      // Get time entries from time tracking service
      const todayStr = format(today, 'yyyy-MM-dd');
      const allEmployees = await storage.getActiveEmployees();
      const todaysTimeEntries: any[] = [];
      
      for (const employee of allEmployees) {
        try {
          const employeeEntries = await storage.getDailyTimeEntry(employee.id, todayStr);
          if (employeeEntries && employeeEntries.timeEntries && employeeEntries.timeEntries.length > 0) {
            todaysTimeEntries.push(...employeeEntries.timeEntries);
          }
        } catch (error) {
          // Employee may not have entries for today - skip
        }
      }

      // Group time entries by staff member
      const staffBookings = todaysTimeEntries.reduce((acc: any, entry) => {
        if (!acc[entry.employeeId]) {
          acc[entry.employeeId] = {
            employeeId: entry.employeeId,
            employeeName: entry.employeeName,
            totalHours: 0,
            jobs: []
          };
        }
        acc[entry.employeeId].totalHours += entry.hoursWorked || 0;
        if (entry.jobId && !acc[entry.employeeId].jobs.includes(entry.jobId)) {
          acc[entry.employeeId].jobs.push(entry.jobId);
        }
        return acc;
      }, {});

      // Pending actions
      const conversations = await storage.getAllConversations({ status: 'open' });
      const unansweredConversations = conversations.filter(c => 
        c.lastMessageBy === 'customer' && (c.unreadCount || 0) > 0
      ).length;

      const allQuotes = await storage.getAllQuotes();
      const pendingQuotes = allQuotes.filter(q => q.status === 'draft' || q.status === 'sent').length;

      // Count overdue invoices from jobs (jobs with invoices that are past due)
      const overdueInvoices = allJobs.filter(job => {
        if (!job.invoiceDate) return false; // Not invoiced
        if (job.invoiceStatus === 'paid' || job.invoiceStatus === 'cancelled') return false;
        if (!job.invoiceDueDate) return false;
        return new Date(job.invoiceDueDate) < today;
      }).length;

      const allIncidents = await storage.getSafetyIncidents();
      const pendingIncidents = allIncidents.filter(inc => 
        inc.investigationStatus === 'pending' || inc.investigationStatus === 'in_progress'
      ).length;

      // Recent activity feed (last 10 activities)
      const recentActivities = await storage.getAllActivities(10);

      // Performance indicators (using filtered jobs for metrics)
      const completedToday = todaysJobsForMetrics.filter(j => j.status === 'completed').length;
      const totalScheduledToday = todaysJobsForMetrics.length;
      const completionRate = totalScheduledToday > 0 
        ? (completedToday / totalScheduledToday) * 100 
        : 0;

      // Calculate average job completion time (for completed jobs today, using filtered jobs)
      const completedJobsToday = todaysJobsForMetrics.filter(j => j.status === 'completed');
      let avgCompletionTime = 0;
      if (completedJobsToday.length > 0) {
        const totalTime = completedJobsToday.reduce((sum, job) => {
          if (job.completedDate && job.scheduledDate) {
            const scheduled = new Date(job.scheduledDate).getTime();
            const completed = new Date(job.completedDate).getTime();
            return sum + (completed - scheduled);
          }
          return sum;
        }, 0);
        avgCompletionTime = totalTime / completedJobsToday.length / (1000 * 60 * 60); // Convert to hours
      }

      // Customer response time (average time to first response in conversations)
      const recentConvos = conversations.slice(0, 20);
      let avgResponseTime = 0;
      if (recentConvos.length > 0) {
        const responseTimes = [];
        for (const convo of recentConvos) {
          const messages = await storage.getConversationMessages(convo.id);
          if (messages.length >= 2) {
            const firstMsg = messages[0];
            const firstResponse = messages.find(m => m.direction === 'outbound');
            if (firstResponse && firstMsg.createdAt && firstResponse.createdAt) {
              const responseTime = new Date(firstResponse.createdAt).getTime() - new Date(firstMsg.createdAt).getTime();
              responseTimes.push(responseTime);
            }
          }
        }
        if (responseTimes.length > 0) {
          avgResponseTime = responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length / (1000 * 60); // Convert to minutes
        }
      }

      res.json({
        success: true,
        data: {
          todaysJobs: {
            total: todaysJobs.length,
            jobs: todaysJobs,
            statusBreakdown
          },
          tomorrowsJobs: {
            total: tomorrowsJobs.length,
            jobs: tomorrowsJobs.slice(0, 5) // Preview only first 5
          },
          financials: {
            totalRevenue,
            totalCosts,
            profit: totalRevenue - totalCosts,
            profitMargin: profitMargin.toFixed(2)
          },
          staffBookings: Object.values(staffBookings),
          pendingActions: {
            unansweredConversations,
            pendingQuotes,
            overdueInvoices,
            pendingIncidents,
            total: unansweredConversations + pendingQuotes + overdueInvoices + pendingIncidents
          },
          recentActivities,
          performanceIndicators: {
            completionRate: completionRate.toFixed(1),
            avgCompletionTimeHours: avgCompletionTime.toFixed(1),
            avgResponseTimeMinutes: avgResponseTime.toFixed(0)
          }
        }
      });
    } catch (error) {
      console.error("Error fetching activity dashboard:", error);
      res.status(500).json({ success: false, message: "Failed to fetch activity dashboard data" });
    }
  });

  // Speech to Quote - Convert recorded speech to quote data
  app.post('/api/speech-to-quote', audioUpload.single('audio'), async (req, res) => {
    let audioFilePath: string | null = null;

    try {
      if (!req.session.employeeId) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
      }
      if (!req.file) {
        return res.status(400).json({ success: false, message: 'No audio file uploaded' });
      }

      audioFilePath = req.file.path;
      const context = req.body.context || 'full';
      console.log('📢 Speech to Quote - Processing audio file:', req.file.filename, '| Context:', context);

      const businessId = req.session.businessId;
      if (businessId) {
        const ok = await usageMeter.guard('ai', businessId, 'speech_to_quote');
        if (!ok) return res.status(429).json({ success: false, message: 'Monthly AI limit reached — upgrade your plan or wait for the next billing cycle.' });
      }

      // Step 1: Transcribe audio using Whisper
      const audioReadStream = fs.createReadStream(audioFilePath);

      const transcription = await openai.audio.transcriptions.create({
        file: audioReadStream,
        model: "whisper-1",
        language: "en", // Specify English for better accuracy
        prompt: "This is a job description for a field-service business in New Zealand. The speaker is describing the work, equipment, location, and job details in English.", // Help Whisper with context
      });

      // When using response_format: "text", transcription is a string, not an object
      const rawTranscriptText = typeof transcription === 'string' ? transcription : transcription.text;
      
      // Capitalize names in transcript using GPT
      let transcriptText = rawTranscriptText;
      try {
        const capitalizationResponse = await openai.chat.completions.create({
          model: 'gpt-4o',
          messages: [
            {
              role: 'system',
              content: 'You are a text formatter. Your only job is to take transcribed text and properly capitalize all proper nouns (names of people, places, companies) while keeping everything else exactly as it is. Return ONLY the corrected text with no explanations or formatting.'
            },
            {
              role: 'user',
              content: rawTranscriptText
            }
          ],
          temperature: 0.1
        });
        
        transcriptText = capitalizationResponse.choices[0].message.content?.trim() || rawTranscriptText;
        console.log(`✅ Names capitalized in web transcription`);
      } catch (capError) {
        console.warn('⚠️ Could not capitalize names, using raw transcript:', capError);
        transcriptText = rawTranscriptText;
      }
      
      console.log('📝 Transcription:', transcriptText);

      // If context is description-only or internal notes, format transcription (no full quote extraction)
      if (context === 'job-description' || context === 'invoice-description' || context === 'internal-notes') {
        console.log('📝 Formatting transcription (context: ' + context + ')');

        let formattingPrompt: string;
        let systemPrompt: string;

        if (context === 'internal-notes') {
          systemPrompt = 'You are a note cleaner. Clean up voice transcriptions into readable plain text notes. Keep all the content but remove filler words.';
          formattingPrompt = `Clean up this voice transcription into a readable note. Remove filler words like "okay", "um", "uh", "so", etc. Fix capitalisation of proper nouns. Keep sentences natural — do NOT convert to a task list. When the speaker says "new line" or "next line", start a new line. Return ONLY the cleaned note text.

Voice transcription:
"${transcriptText}"

Cleaned note:`;
        } else {
          systemPrompt = 'You are a professional job description formatter. Format voice transcriptions into clean, structured task lists.';
          formattingPrompt = `You are a job description formatter for a field-service business in New Zealand.

Take this voice transcription and format it as a clean, structured list of tasks. Each task should be on its own line.

Rules:
1. Remove filler words like "okay", "um", "so", etc.
2. Capitalize the first letter of each task
3. Keep technical and proper terms capitalized (product/material names, parts, species, place names, brands)
4. Each task should be a clear, concise action item
5. Return ONLY the formatted task list, with each task on a new line
6. Do NOT add bullet points or dashes - just line breaks between tasks
7. Do NOT number the items
8. IMPORTANT: When the speaker says "new line", "next line", "next item", or "line break", treat that as a command to start the next task on a new line. Remove those command words from the output.

Voice transcription:
"${transcriptText}"

Formatted task list:`;
        }

        const formattingResponse = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: formattingPrompt }
          ],
          temperature: 0.3,
        });

        const formattedText = formattingResponse.choices[0].message.content?.trim() || transcriptText;
        console.log('📝 Formatted text:', formattedText);

        if (businessId) await usageMeter.recordUsage('ai', businessId, { feature: 'speech_to_quote' });

        return res.json({
          success: true,
          data: {
            transcription: formattedText
          }
        });
      }

      // Step 2: Extract quote details using GPT-5 (full quote mode only)
      // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
      let __webQuoteKnowledge = '';
      try {
        // Scoped lookup — this is a multer route (ALS tenant context lost), so the
        // unscoped getBusinessSettings() would return an arbitrary tenant's row and
        // leak its business knowledge into the prompt.
        __webQuoteKnowledge = buildBusinessKnowledgeBlock(await storage.getBusinessSettingsForBusiness(businessId));
      } catch { /* knowledge is optional context */ }
      const extractionPrompt = `You are a quote assistant for a field-service business in New Zealand. 
Extract the following information from this conversation transcription and return it as JSON:

{
  "customerName": "customer's full name or null if not mentioned",
  "customerPhone": "phone number or null if not mentioned",
  "customerEmail": "email or null if not mentioned",
  "address": "property address or null if not mentioned",
  "jobDescription": "detailed description of the work needed",
  "treeTypes": "types of trees mentioned or null if not specified",
  "estimatedPrice": "price mentioned in NZD or null if not mentioned (number only, no $ sign)",
  "urgency": "urgent/normal/low based on conversation tone",
  "notes": "any additional important details"
}
${__webQuoteKnowledge}
Transcription: ${transcriptText}`;

      const extractionResponse = await openai.chat.completions.create({
        model: "gpt-5",
        messages: [
          {
            role: "system",
            content: "You are a helpful assistant that extracts structured quote information from conversations. Always respond with valid JSON."
          },
          {
            role: "user",
            content: extractionPrompt
          }
        ],
        response_format: { type: "json_object" },
      });

      const quoteData = JSON.parse(extractionResponse.choices[0].message.content || '{}');
      console.log('💼 Extracted quote data:', quoteData);

      if (businessId) await usageMeter.recordUsage('ai', businessId, { feature: 'speech_to_quote' });

      res.json({
        success: true,
        data: {
          transcription: transcriptText,
          ...quoteData
        }
      });

    } catch (error) {
      console.error('Error processing speech to quote:', error);
      res.status(500).json({ 
        success: false, 
        message: error instanceof Error ? error.message : 'Failed to process audio' 
      });
    } finally {
      // Always clean up audio file (security: prevent sensitive recordings from accumulating)
      if (audioFilePath && fs.existsSync(audioFilePath)) {
        try {
          fs.unlinkSync(audioFilePath);
          console.log('🗑️ Cleaned up audio file:', audioFilePath);
        } catch (cleanupError) {
          console.error('Error cleaning up audio file:', cleanupError);
        }
      }
    }
  });

