  // Get Firebase config for service worker (public endpoint, no secrets)
  app.get("/api/firebase-config", async (req, res) => {
    // Helper function to clean Firebase config values (remove quotes and extra characters)
    const cleanValue = (value: string | undefined): string => {
      if (!value) return '';
      // Remove leading/trailing quotes, colons, and commas
      return value.replace(/^[:\s"']+|[,\s"']+$/g, '').trim();
    };
    
    // Return Firebase config from environment variables
    // These are public values, safe to expose to the client
    const rawProjectId = cleanValue(process.env.FIREBASE_PROJECT_ID);
    const config = {
      apiKey: cleanValue(process.env.FIREBASE_API_KEY),
      authDomain: cleanValue(process.env.FIREBASE_AUTH_DOMAIN) || `${rawProjectId}.firebaseapp.com`,
      projectId: rawProjectId,
      storageBucket: cleanValue(process.env.FIREBASE_STORAGE_BUCKET) || `${rawProjectId}.appspot.com`,
      messagingSenderId: cleanValue(process.env.FIREBASE_MESSAGING_SENDER_ID),
      appId: cleanValue(process.env.FIREBASE_APP_ID)
    };
    
    // Check if Firebase Cloud Messaging is configured (only required fields)
    const requiredFields = [
      config.apiKey,
      config.projectId,
      config.messagingSenderId,
      config.appId
    ];
    const isConfigured = requiredFields.every(val => val !== '');
    
    res.json({ 
      success: true, 
      configured: isConfigured,
      config: isConfigured ? config : null,
      vapidKey: cleanValue(process.env.FIREBASE_VAPID_KEY) || '' 
    });
  });

  // Register FCM token for push notifications
  app.post("/api/notifications/register-token", async (req, res) => {
    try {
      const employeeId = req.session.employeeId;
      if (!employeeId) {
        return res.status(401).json({ success: false, message: 'Not authenticated' });
      }

      const { token, deviceInfo } = req.body;
      if (!token) {
        return res.status(400).json({ success: false, message: 'Token is required' });
      }

      // Check if token already exists
      const existingToken = await storage.getFcmTokenByToken(token);
      if (existingToken) {
        if (existingToken.employeeId !== employeeId) {
          // The token is registered to a different employee than the one now
          // signed in on this device. Reassign it. This also self-heals tokens
          // that were mis-registered to the hardcoded owner by the old native
          // registration path — once the real user signs in, the token moves
          // to them.
          await storage.updateFcmToken(existingToken.id, { employeeId, isActive: true });
          console.log(`🔄 Reassigned FCM token from ${existingToken.employeeId} to ${employeeId}`);
        } else {
          await storage.markFcmTokenAsUsed(token);
          if (!existingToken.isActive) {
            await storage.updateFcmToken(existingToken.id, { isActive: true });
          }
        }
        return res.json({ success: true, message: 'Token registered' });
      }

      // Create new token
      await storage.createFcmToken({
        employeeId,
        token,
        deviceInfo: deviceInfo || null,
        isActive: true
      });

      // Create default notification preferences if they don't exist
      const existingPrefs = await storage.getNotificationPreferences(employeeId);
      if (!existingPrefs) {
        await storage.createNotificationPreferences({
          employeeId
        });
      }

      console.log(`✅ FCM token registered for employee ${employeeId}`);
      res.json({ success: true, message: 'Token registered successfully' });
    } catch (error) {
      console.error('Error registering FCM token:', error);
      res.status(500).json({ success: false, message: 'Failed to register token' });
    }
  });

  // One iOS device = one live token. A reinstall mints a NEW FCM token while
  // the old ones keep delivering through APNs until Apple notices the
  // uninstall, so an employee accumulates active tokens and every push fans
  // out N times to the same phone (seen as triple "rescheduled" alerts after
  // the June-11 delete-and-reinstall cycle). Whenever a native token checks
  // in, retire any OLDER active native tokens for that employee — the app
  // re-registers its current token on every launch, so a genuinely live
  // second device reactivates itself the next time it's opened.
  async function deactivateOlderNativeTokens(employeeId: string, currentToken: string, currentCreatedAt: Date | null) {
    try {
      const activeTokens = await storage.getActiveFcmTokens(employeeId);
      for (const t of activeTokens) {
        if (t.token === currentToken) continue;
        if (!(t.deviceInfo || '').startsWith('iOS Native')) continue;
        if (currentCreatedAt && t.createdAt && new Date(t.createdAt) >= currentCreatedAt) continue;
        await storage.updateFcmToken(t.id, { isActive: false });
        console.log(`🧹 Deactivated older native FCM token ${t.token.substring(0, 12)}… for employee ${employeeId}`);
      }
    } catch (err) {
      console.error('Error deactivating older native FCM tokens:', err);
    }
  }

  // Native iOS FCM token registration (bypasses session auth using webhook secret)
  // Called directly by Swift code in the Capacitor app
  app.post("/api/notifications/register-native-fcm-token", async (req, res) => {
    try {
      const webhookSecret = req.headers['x-webhook-secret'];
      const expectedSecret = process.env.HERO_WEBHOOK_SECRET;
      if (!expectedSecret || webhookSecret !== expectedSecret) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
      }

      const { token, employeeId, deviceInfo } = req.body;
      if (!token || !employeeId) {
        return res.status(400).json({ success: false, message: 'token and employeeId are required' });
      }

      // Verify employee exists
      const employee = await storage.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ success: false, message: 'Employee not found' });
      }

      // Check if token already exists
      const existingToken = await storage.getFcmTokenByToken(token);
      if (existingToken) {
        await storage.markFcmTokenAsUsed(token);
        if (!existingToken.isActive) {
          await storage.updateFcmToken(existingToken.id, { isActive: true });
        }
        await deactivateOlderNativeTokens(employeeId, token, existingToken.createdAt ? new Date(existingToken.createdAt) : null);
        console.log(`✅ Native FCM token already registered for employee ${employeeId}`);
        return res.json({ success: true, message: 'Token already registered' });
      }

      // Create new token
      await storage.createFcmToken({
        employeeId,
        token,
        deviceInfo: deviceInfo || 'iOS Native',
        isActive: true
      });
      // A brand-new token means this device just (re)installed — every other
      // active native token for this employee predates it.
      await deactivateOlderNativeTokens(employeeId, token, null);

      // Create default notification preferences if they don't exist
      const existingPrefs = await storage.getNotificationPreferences(employeeId);
      if (!existingPrefs) {
        await storage.createNotificationPreferences({ employeeId });
      }

      console.log(`✅ Native FCM token registered for employee ${employeeId} (${employee.name})`);
      res.json({ success: true, message: 'Native token registered successfully' });
    } catch (error) {
      console.error('Error registering native FCM token:', error);
      res.status(500).json({ success: false, message: 'Failed to register token' });
    }
  });

