  // ─── Facebook Messenger Webhook ─────────────────────────────────────────────
  // Shared verify handler — checks FACEBOOK_WEBHOOK_VERIFY_TOKEN or HERO_WEBHOOK_SECRET
  const handleFacebookWebhookVerify = (req: Request, res: Response) => {
    const mode      = req.query['hub.mode'];
    const token     = req.query['hub.verify_token'];
    const challenge = req.query['hub.challenge'];

    const verifyToken = process.env.FACEBOOK_WEBHOOK_VERIFY_TOKEN;
    if (mode === 'subscribe' && token === verifyToken) {
      console.log('✅ Facebook Messenger webhook verified');
      return res.status(200).send(challenge);
    }
    console.warn(`⚠️ Facebook Messenger webhook verification failed (token mismatch)`);
    return res.sendStatus(403);
  };

  // GET: Facebook calls this to verify the webhook endpoint
  app.get('/api/webhooks/facebook/messenger', handleFacebookWebhookVerify);
  // Alias path (shorter URL registered in Meta Developer Console)
  app.get('/api/webhooks/messenger', handleFacebookWebhookVerify);

  // POST: Facebook sends message events here (both paths — /facebook/messenger is canonical, /messenger is alias)
  app.post(['/api/webhooks/facebook/messenger', '/api/webhooks/messenger'], async (req: Request, res: Response) => {
    // Verify Meta's X-Hub-Signature-256 (HMAC-SHA256 of the raw body with the
    // app secret) BEFORE doing anything. Without this, anyone can forge a
    // payload to inject leads, burn a GPT call per request, and trigger an
    // outbound Graph API reply. Fail closed when the secret is unset.
    if (!verifyFacebookSignature(req)) {
      return res.status(403).json({ error: 'Invalid webhook signature' });
    }

    // Acknowledge immediately so Facebook doesn't retry
    res.sendStatus(200);

    try {
      const body = req.body;
      if (body.object !== 'page') return;

      const PAGE_TOKEN = process.env.FACEBOOK_PAGE_ACCESS_TOKEN;
      if (!PAGE_TOKEN) {
        console.warn('⚠️ FACEBOOK_PAGE_ACCESS_TOKEN not set — cannot process Messenger webhook');
        return;
      }

      for (const entry of (body.entry || [])) {
        for (const event of (entry.messaging || [])) {
          // Skip echoes (messages sent by the page itself)
          if (!event.message || event.message.is_echo) continue;

          const senderId   = event.sender?.id;
          const messageText = event.message?.text || '';

          if (!senderId || !messageText.trim()) continue;

          console.log(`📨 Facebook Messenger message from PSID ${senderId}: ${messageText.substring(0, 80)}`);

          // Fetch sender's name from Graph API
          let senderName = '';
          try {
            const profileUrl = `https://graph.facebook.com/v18.0/${senderId}?fields=name&access_token=${PAGE_TOKEN}`;
            const profileRes = await fetch(profileUrl);
            if (profileRes.ok) {
              const profile = await profileRes.json() as { name?: string };
              senderName = profile.name || '';
            }
          } catch (err) {
            console.warn('Could not fetch Facebook sender profile:', err);
          }

          // Use AI to extract job details from the message
          let extracted: { firstName?: string; lastName?: string; phone?: string; email?: string; address?: string; description?: string } = {};
          try {
            const aiResponse = await openai.chat.completions.create({
              model: 'gpt-5',
              messages: [
                {
                  role: 'system',
                  content: 'You are a lead extraction assistant for a New Zealand field-service business. Extract structured information from Facebook messages. Respond ONLY with valid JSON — no markdown, no explanation.'
                },
                {
                  role: 'user',
                  content: `Extract lead details from this Facebook message. Return JSON with keys: firstName, lastName, phone, email, address, description (nature of the work), isJobInquiry (boolean).\n\nMessage:\n${messageText}\n\nSender name from profile: "${senderName}"`
                }
              ],
              response_format: { type: 'json_object' }
            });
            extracted = JSON.parse(aiResponse.choices[0].message.content || '{}');
          } catch (err) {
            console.warn('AI extraction failed for Messenger message:', err);
          }

          // Only create a lead if it looks like a genuine job inquiry
          if (extracted.isJobInquiry !== false) {
            const nameParts = senderName.split(' ');
            const firstName = extracted.firstName || nameParts[0] || 'Facebook';
            const lastName  = extracted.lastName  || nameParts.slice(1).join(' ') || 'Messenger';
            const fullName  = `${firstName} ${lastName}`.trim();

            try {
              const lead = await storage.createPipelineLead({
                name:             fullName,
                phone:            extracted.phone   || '',
                email:            extracted.email   || '',
                address:          extracted.address || '',
                serviceRequested: extracted.description || messageText,
                source:           'facebook_messenger',
                status:           'new',
                urgency:          'medium',
                notes:            `Facebook Messenger message:\n\n${messageText}`
              });

              console.log(`✅ Lead created from Facebook Messenger: ${lead.id} (${fullName})`);

              // Auto-reply to the sender
              try {
                const replyUrl = `https://graph.facebook.com/v18.0/me/messages?access_token=${PAGE_TOKEN}`;
                await fetch(replyUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({
                    recipient: { id: senderId },
                    message:   { text: "Hi! Thanks for reaching out. We've received your message and will be in touch shortly!" }
                  })
                });
              } catch (err) {
                console.warn('Could not send Messenger auto-reply:', err);
              }
            } catch (err) {
              console.error('Failed to create lead from Facebook Messenger:', err);
            }
          }
        }
      }
    } catch (err) {
      console.error('Error processing Facebook Messenger webhook:', err);
    }
  });

